/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200309-3","meetingId":"r02-c-budget","date":"2020年3月9日","dateIso":"2020-03-09","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を180件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"湯澤委員","kind":"質問","question":"現在、区内の認知症の方は１万２,０００人程度と認識しておりますが、これは何を基準にカウントした数でしょうか。実際にはもっと多くの方が認知症でいらっしゃるとお考えか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"この中には軽度、いわゆる予備軍と言われる方は含まれていないと認識しています。令和３年度から認知症の検診というものに着手したいと考えておりまして、令和２年度は医師会等々と調整してその準備をしたいと考えております。","id":"exchange-001"},{"speaker":"湯澤委員","kind":"意見","question":"早期治療、当事者の記憶や認識が明確なうちに備えることができれば、当事者の意思を尊重しながらさまざまなことに対応できるかと思います。そこで、区では介護者や、これから介護するかもしれないといった方々に対してどんな取り組みをされているかもお答えほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"介護者、改めてご家族の方がどのように接することが正しい認知症の方への対応になるのかといったことを含めた１時間半程度の講義になっておりまして。","id":"exchange-002"},{"speaker":"湯澤委員","kind":"質問・要望","question":"誰が見てもわかりやすいような、さらによいものにしていただければなということを要望しまして、次の質問に移らせていただきます。障害を持つ方が一般就労に安心してチャレンジできるよう自己負担の軽減策を検討すべきかと思いますが、そちらに関して区の見解を示すよう求めました。","respondent":"松山障害者福祉課長","answer":"委員のご指摘のとおり、就労移行とご本人の就職の収入と、あるいは訓練等で、なかなかそのバランスというのが難しいというお声は伺っております。今、当事者の状況を就労移行支援事業所と連携してお声を聞きながら、何か支援策はないか検討していきたいと考えています。","id":"exchange-003"},{"speaker":"湯澤委員","kind":"意見","question":"もう一つ、区は、交通費についても安心して一般就労を目指している方の環境を整えるためにも全ての通所者に交通費助成を検討するべきかと考えます。区のご見解をお知らせくださいとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"委員お尋ねの就労移行支援事業所に通う際の交通費についてです。就労移行支援事業所に通っていただきたいということと、どの程度の負担感なのか、まずは移行支援事業所を通じて実態の把握に努めたいと考えています。","id":"exchange-004"},{"speaker":"湯澤委員","kind":"意見","question":"ぜひ自立に対して強い意志を持つ障害者の方に対しまして、こういった軽減策の検討を、今後よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"せお委員","kind":"質問","question":"２５９ページ、お時間があれば２１３ページ、紙おむつ支給についてお伺いします。３歳ぐらいからはみんな一緒に生活のベースは保育園、児童発達支援は支援ですから、補助的な役割で通うのが妥当と思われます。","respondent":"築山障害者施策推進担当課長","answer":"療育といたしましては一律ではなく、その方に合った支援が提供できるようにするものと考えています。児童発達支援センターにおける療育のあり方については、指定管理者と協議しながら検証を進めてまいります。","id":"exchange-006"},{"speaker":"せお委員","kind":"確認","question":"その際ですが、先ほども申しましたように保育園、幼稚園の受け入れ体制も整っていなくてはなりません。確認となりますが、今年度とどのように変わってくるのか、説明を求めました。","respondent":"佐藤保育課長","answer":"幼稚園は、私立保育園、幼稚園も含めて一定数のそういった施設に通われているお子さんもお預かりしています。特別支援保育の充実に関しましては平成３０年度に体制を見直しまして、今後も積極的に充実に努めてまいります。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問・要望","question":"こちらは要望で終わります。現在、そちらの２施設の活用方法は検討されていますか尋ねました。","respondent":"築山障害者施策推進担当課長、松山障害者福祉課長","answer":"私からは、こみゅにてぃぷらざ八潮の現在の状況についてご説明いたします。現在は工事も終わりましたので原状復帰し、所管課へ返還しています。 医療的ケアの必要なお子さんのご家族が抱える不安等を解消するため、医療的ケアに関する相談業務を実施したいと考えております。医療的ケアが必要なお子さんと地域の子どもたちが一緒に遊べる場、親子で集える場の提供を考えております。","id":"exchange-008"},{"speaker":"せお委員","kind":"質問・要望","question":"そちらの検討会とかは当事者も加わったような何か会議とかになりますでしょうか。お伝えできる範囲で説明を求めました。","respondent":"松山障害者福祉課長","answer":"医療的ケア児に対する区の支援体制につきましては、２月に医療的ケア等の支援関係連絡会の準備会を立ち上げておりまして、特別支援学校。引き続きその会議の中で検討していきたいと考えています。","id":"exchange-009"},{"speaker":"せお委員","kind":"質問・要望","question":"国土交通省は昨年、これと並行して交通事業者に対し、障害者手帳の確認方法の見直しについて理解と協力を求める文書を出しています。款が違うところはお答えいただかなくて結構ですが、お答えできる範囲で品川区のこちらの考えをお聞きかせいただくよう求めました。","respondent":"松山障害者福祉課長","answer":"ただ、他区の状況も踏まえまして、また東京都と情報交換をしていきたいと考えています。障害者にとって利便性のある情報につきましては、今後区のホームページに上げていきたいと考えています。","id":"exchange-010"},{"speaker":"せお委員","kind":"確認","question":"品川区においては、このような取り扱いでよろしいでしょうか。確認になりますが、説明を求めました。","respondent":"佐藤保育課長","answer":"４月入園児の取り扱いの関係です。委員ご紹介のとおり先週の金曜日、３月６日の夕方に国から通知がございまして、区といたしましてもそのように対応したいと考えています。","id":"exchange-011"},{"speaker":"せお委員","kind":"意見","question":"そこで心配になるものの１つが食の問題で、高齢者の孤食はコミュニケーション不足と栄養問題にまで及びます。このようなＮＰＯ法人と連携して交流する事業も必要かと考えますが、見解を説明するよう求めました。","respondent":"宮尾高齢者地域支援課長","answer":"食をテーマとした高齢者の社会参加です。現在、介護予防のほうでも栄養改善をテーマにした事業、それから男性の方に少し重点を置いた料理教室等々を行っているところです。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"こちらはどのような補助金でしょうか。説明を求めました。","respondent":"大澤保育支援課長","answer":"お尋ねの補助金ですが、運営費の助成のほかに教員の研修費、園児の教材費、児童の健康管理費、そして心身障害児教育事業費補助金、防災安全対策費補助金というふうに項目が分かれてあります。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"確認なのですが、社協でのこのサービスでは、紙おむつは不足していませんでしょうか。発注も大変かと思うのですが、確認でお聞きかせいただくよう求めました。","respondent":"寺嶋高齢者福祉課長","answer":"マスク不足に伴いまして、先週末に念のため社会福祉協議会に状況を確認させていただいたところです。社会福祉協議会のほうから事業者に確認をとったところ、今の段階で特段の不足等の状態は生じていないというような回答を得たと聞いております。","id":"exchange-014"},{"speaker":"つる委員","kind":"提案","question":"直近の品川区でまとめていただいている資料を確認すると、在宅でずっと育てる方が３割、数にすると約６,２００名ぐらいがその各年でいらっしゃると。","respondent":"廣田子ども育成課長","answer":"まださらなる努力が必要という認識もありますし、事務効率の面からも考えていかなければいけないと考えているところです。一番大事なのは総合的に子育て支援を俯瞰できるような形、仕組みづくりが必要と認識していますけれども。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"次に、子ども家庭支援センターに関連して、保育ソーシャルワークについて伺っていきたいと思います。そうした意味でも既存の対応連携の支援、それからこうした国の補助金の活用について、枠組みの活用について、ご見解を改めて示すよう求めました。","respondent":"崎村児童相談担当課長","answer":"保育所等における要支援児童の対応、また関係機関との連携、先ほどご紹介がありました地域連携推進員というものを配置するといったものです。我々としても、その置かれた地域連携推進員と連携しながら要保護児童、要支援児童に対応していきたいと考えているところです。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"それから明晴学園の方々からご意見を伺っているところだというところで、多岐にわたっていろいろと精査されているということを理解しています。先日もろうあの方の家族の方からお話を伺ったときに、今現在の品川区の手話言語条例に対する考え方、方向性を説明するよう求めました。","respondent":"松山障害者福祉課長","answer":"これまで品川区といたしましても、聴覚障害者協会、明晴学園と丁寧なすり合わせを行ってまいりました。日本語対応手話を分けて、考えのすり合わせ、合意を重ねていきたいと考えています。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"私からは２１３ページの特別養護老人ホーム運営費に関わって、特養ホームについて質問いたします。今年２月末締め切りの特養ホーム入所申込み申請者数を説明するよう求めました。","respondent":"寺嶋高齢者福祉課長","answer":"２月末日で今回の特養ホームの入所調整の申し込みを締め切りまして、正確な数字は今の段階では申し上げることができませんが、前々回と比較して若干下回っているというような見込みです。","id":"exchange-018"},{"speaker":"おくの委員","kind":"質問","question":"そして介護状況、この４つの観点から点数がつけられることになっていて、特養ホームに入れる点数はおおよそ７０点だと伺っています。この認識でおおむねよろしいでしょうか、いかがでしょう。","respondent":"寺嶋高齢者福祉課長","answer":"それから点数につきましては、これは全く毎回違っておりまして、７０点と限定されたものではありません。平均すると、７０点までしか入れないということは、今までは特に起きていないと認識しています。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"おおむね６０点から７０点程度というふうに認識しておいてよろしいですか、伺います。","respondent":"寺嶋高齢者福祉課長","answer":"もちろん空きがあればの話ですけれども、ご希望の方がいて空きっぱなしにしていくということは基本的にはありませんので、その場合は点数が若干低くなっても入っているという事例は実際にあります。","id":"exchange-020"},{"speaker":"おくの委員","kind":"質問","question":"今、４８歳ですから、もう何十年もその生活を続けざるを得ません。この点をお伺いいたします。","respondent":"寺嶋高齢者福祉課長","answer":"それから、そういった方についてはどういった介護サービスがあるかということをきちんとご説明をするのも私どもの役割だと考えております。特養ホームではなく、そういったものをきちんとご説明した上でご理解、ご判断いただくというところが重要だと考えております。","id":"exchange-021"},{"speaker":"おくの委員","kind":"質問","question":"そういうふうにお伺いしたのです。いかがか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"先ほど申し上げたとおりですけれども、１点補足しますと、まず有料老人ホームからでも特養ホームへの入所申し込みは可能です。当然申し込みをいただいて特養ホームに入るということも可能ですので、未来永劫その状態かどうかというのは判断しかねるところです。","id":"exchange-022"},{"speaker":"おくの委員","kind":"質問","question":"この状態は不当ではないでしょうか。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"２４３ページ、子どもの未来応援事業から、これはふるさと納税を活用したガバメントクラウドファンディングだと思うのですけれども、改めて寄附金額、寄附者数、区内・区外の内訳を教えていただきたいのと、プレス発表にも出ていますけれども、来年度はどういう形になっていくのか、説明を求めました。","respondent":"三ッ橋子ども家庭支援課長","answer":"５５７万３,０７３円の内訳ですが、区内は１５７万３,０００円、区外は４００万７３円となっております。今年度は目標金額３００万円といたしておりましたが、来年度につきましては５００万円と寄附金額の目標を上げしています。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"この事業は子ども家庭支援課から子育て応援課にかわるのですか。子育て応援課というのは聞いたことはないですけれども、事業はこの子育て応援課に継承していっていただけるのか尋ねました。","respondent":"三ッ橋子ども家庭支援課長","answer":"児童相談機能強化のため子ども家庭支援センターが課として設置されますので、その関係で子ども家庭支援課から子育て応援課に課名が変わります。今回のガバメントクラウドファンディング、ふるさと納税を活用した食の支援は子育て応援課が引き続き実施してまいります。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"私自身、区の代表電話の０３－３７７７－１１１１にかけて課名を言うときに、「あの、あの」と出てこないときがあるのです。この辺も、課の名前はなるべく変えないで済むなら変えないほうがいいと思っているのですが、その辺についてはいかがか尋ねました。","respondent":"三ッ橋子ども家庭支援課長","answer":"こちらにつきましてはさまざまな状況がありますので、子ども家庭支援課から子育て応援課に課名変更となっております。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"トラブルはありませんね、事故はありませんねと担当課長に伺ってきて、なぜ今になって基本計画を策定していかないといけないのでしょうか。このまましっかりやっていけば、私は何の問題もないと思うのですけれども、経費を使ってそれをする理由を説明するよう求めました。","respondent":"大串福祉計画課長","answer":"平成２８年に成年後見制度の利用の促進に関する法律というものが制定されておりまして、私どものほうで利用促進計画を策定していこうというものです。この法の趣旨は、各区市町村で利用促進を図るように計画を進めろというところで、国からの要請を受けて策定するものです。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"伺って、今まで何の事故もトラブルもないわけですから、引き続きこの施策はやっていっていただきたいと考えています。事ここに至っては、外国人も採用しなければ介護の仕事が成立しない、定員が足りないということでこの施策は出てきたのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"その辺も加味しまして、品川区としてはまだ外国人材の受け入れを進めているところがほとんどありません。この辺の情報を今年度収集しまして、来年度の予算案として計上させていただいたところです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"介護士の方たちの夫婦のお給料で品川区におうちを１軒持てないではないですか。課長、バサッと保険ですからと切らないで、ぜひ前向きな答弁をほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"今、１人当たり８万円以上の給料アップができる人を１人設置するか、特定の１人だけ８万円アップするとモチベーションの関係があるので。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"それだったら人が集まらないわけがないではないですか。そして本当に一生懸命やってくれている、そこに応えていくというのは、行政の仕事ではないか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"介護報酬との兼ね合いがありまして、なかなかストレートに人件費等々という形で対応するのは制度上非常に困難な部分が残念ながらあります。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"私の一般質問で再質問をしたときに、福祉部長から、給料だけではなくて総合的に上げていきますという答弁をいただいたと思っています。この件に関して私はずっと、議員でいるうちは追っていきたいと考えていますので、どうにか喜んでいただける職場環境に一緒にしていきましょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"２４３ページからは未来を拓く学習支援と学習支援ボランティア事業、時間があるところまで伺います。東京都へは、品川区のほうからそういう東京都の備蓄のマスクなどを要請しているのか、伺いたいと思います。","respondent":"立川総務課長、松山障害者福祉課長、廣田子ども育成課長、寺嶋高齢者福祉課長","answer":"都のほうから既に東京都の備蓄分を放出ということで、品川区の割り当てについては近々持ってくるということで連絡を受けているところです。１事業所当たり約９０枚ということで、児童発達支援の事業所等へも配布可能だということで、職員が手分けして各事業所に配布する予定です。すまいるスクールには東京マラソンで使用しなかったマスクと消毒液を学童用にということで一部提供を受けているところです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"私の読み違いでなければ、次年度は民間事業者を１事業者増やす予算だと読み取れるのですが、伺いたいと思います。障害児者の包括的な相談支援体制の強化と書いてあるのですが、障害児の相談支援体制につながっているのか、その辺の実績も伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"在宅介護支援センターに併設する高齢障害の方、あるいは２号被保険者の方に対応するような特化したようなタイプのものが２事業所できました。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"どういうところにどういう形で検討の委託を行うのか、伺います。伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"どこまで外部と庁内との連携がとれるシステムが構築できるのかということにつきましては、業者に委託して区と一緒に考える予定です。２点目の相談員の月１２日の報酬ですけれども、相談機能強化専門員としては来年度につきましても１２３万円を計上していますし、計画しています。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望として、ぜひそういう方向で検討してほしいと求めました。どういう形態、それともある程度１つの相談をしたら継続して何回かで解決、その辺のシステムについても伺います。","respondent":"松山障害者福祉課長","answer":"電話相談が延べ６９０件、それからサポーター養成講座というのを５回実施いたしまして、これは相談員が講師となっております。城南ブロックの高次脳機能障害の拠点病院の荏原病院と連携しまして、高次脳機能障害の症例検討会等を実施している仕組みになっております。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"平成３０年度の実の数字が５５人というのは、この５５人はみんな専門的な相談に対応できる方の相談を１回は受けたと理解してよろしいでしょうか。やはり最初に高次脳機能障害の状態を把握するために専門的な人のチェックが必要と理解したのですが、それでよろしいか尋ねました。","respondent":"松山障害者福祉課長","answer":"相談の実人員ですけれども、この相談につきましては、拠点相談支援センターでももちろん高次脳機能障害の方の相談をお受けしております。５５人の方が受けているです。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"クロスチェックをどのように行うかはこれから検討ということでしたが、検討していただけたのでしょうか。これらの実態把握はどのように進んでいるか、それぞれ伺います。","respondent":"寺嶋高齢者福祉課長、築山障害者施策推進担当課長","answer":"実態調査ということで、今までは例年、おおむね３年間で全員から回答をいただくということでやっておりました。この中で令和元年度に実施したモニタリングアンケート調査の中に… 障害者福祉課のほうでは、第６期品川区障害福祉計画および第２期品川区障害児福祉計画策定に当たりまして基礎調査を実施したところです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"提案","question":"議員提案での上程を目指していて、プロジェクトチームで議論が進められていて、昨年１２月に条例案についての進捗の報告を聞く機会がありました。","respondent":"寺嶋高齢者福祉課長","answer":"こういったことは地域包括支援センター、場合によっては支え愛・ほっとステーション等でも、そういったご相談をいただいた段階できちんとした支援につながるように取り組んでいるところです。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひその辺をちょっと頭の隅にでもいいから置いていただいて、日々の掘り起こしということに努めてほしいと求めました。ほかのことは別の機会に伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"２４９ページ、あと２５５ページと２５９ページにあるのですけれども、オリンピック・パラリンピック応援事業ついて伺えればと思います。その中でふれあい給食というものがあるのですけれども、こちらの事業内容、開催頻度、参加者の声などの反響がございましたら説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"今年度は１２月末時点で２８校にご協力いただいて実施しています。例年大体３０校程度にご協力いただいて実施しています。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"かなり開催していただいているということで、いいことだと思います。一度接点を持った、給食を一緒に食べたような児童とシニア世代の方たちがその後も継続的に交流するというようなことはあるのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"残念ながら単発でといいますか、基本的にはその１日限りということになってしまうところではありますが、整備を進めさせていただいているところです。こちらのほうも引き続き内容の充実を図ってまいりたいと考えております。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"今は５年、１０年下の世代となるとなかなか話題が合わないと、みたいなことがよくあるのです。交流する中で話が合わないかもしれないといった懸念というか、不安のところを払拭する上では、何か工夫はされていますか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"かなり年が離れた方たちが一堂に会して話をするというところでは、話がなかなか通じにくいというお声もあることは事実です。ふだんなかなか機会のない、ご高齢の方の昔話だったり、こういった声を大切にしながら今後の運営に反映してまいりたいと考えています。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"ここはなかなか難しいという話を私も地域から伺っていて、なぜかといったら、ここの部分が結構大きいのだろうなと思います。コミュニケーションに特化した考え方というか、コミュニケーションを意識した視点というのがこちらにあるのかなというところを伺えればと思います。","respondent":"宮尾高齢者地域支援課長","answer":"私からは、いきいきラボ関ヶ原で実施しておりますパソコン・タブレット教室についてお答えします。今現在では操作方法、そういった手段を、スキルをアップさせていこうというところをメインにやらせていただいているところです。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問・要望","question":"これは要望です。これは区立保育園と限定されているのですけれども、これを区立に限定されている趣旨というのはどういうことでしょうか、お願いします。","respondent":"佐藤保育課長","answer":"プレスの編集の単位なのですけれども、保育課ということで区立保育園に特化したものを書いておりまして、内容といたしましては実際に観戦するときの熱中症対策経費と、実施競技の体験教室とか英語体験も一定程度やりますので、その辺を書いているところです。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"そうなのです。認可外の方たちに対して、区民の公平性というところからどうなのかなということもあるのですけれども、そのあたりはいかがか尋ねました。","respondent":"大澤保育支援課長","answer":"オリンピック・パラリンピックの……。","id":"exchange-045"},{"speaker":"芹澤委員","kind":"質問","question":"私からは２４３ページ、しあわせ食卓事業、関連して坂井市との連携について、時間があれば２６５ページのフードパントリー事業について伺います。しあわせ食卓事業について伺います。","respondent":"三ッ橋子ども家庭支援課長","answer":"しかしながら、確かに１,５００世帯という部分ですので、できる限りいろいろな周知を徹底していきたいと考えています。しあわせ食卓事業について、支援はすごくありがたい制度だと、申請された方からは言われているところです。","id":"exchange-046"},{"speaker":"芹澤委員","kind":"質問","question":"そうすると、３００万円のもともとの目標額は当然達成されて、これから食料が配送されるということですが、想定していたよりも多い食料、もしくは高品質のものが送られるというような認識でよろしいのか尋ねました。","respondent":"三ッ橋子ども家庭支援課長","answer":"ひとり親家庭のしあわせ食卓事業以外に子ども食堂への継続支援というものもありますので、そちらを差し引いた部分を支援してまいります。実際に３００万円のところが５００万円ですので、品数等々、またさまざまなことを検証しながら食品を配送していきたいと考えています。","id":"exchange-047"},{"speaker":"芹澤委員","kind":"質問","question":"来年から目標額も大きく引き上げられるということですから、役所のお世話になる、ぜひそこは引き続き支援を拡充してほしいと求めました。関連して、坂井市との連携について伺います。","respondent":"三ッ橋子ども家庭支援課長","answer":"寄附することで、自分のためではなく誰かのためになるというような趣旨でございまして、ふるさとチョイス対応のきふとというものです。こちらのきふとというものを坂井市が実際に実施してございまして、ふるさとチョイスを通じて品川区のしあわせ食卓事業を坂井市がご存じでした。","id":"exchange-048"},{"speaker":"芹澤委員","kind":"質問・要望","question":"どういった経緯であれ、発送の時点なのか、どこかのタイミングで坂井市に対して感謝を表明できるような計画というのも考えていただきたい。坂井市からのふるさと納税で受け取る方もいらっしゃいますので、その方々へもぜひ周知というのをご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"松澤委員","kind":"質問","question":"２１３ページ、２２１ページ、順不同にて質問いたします。特に力を入れている、また評価が高い、そういった取り組みなどがありましたら説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"安心してそちらで身元がわかるまでの間滞在していただくということの取り組みをお約束して、実施させていただいたということです。２回目の会議は、区のほうで取り組んでいます見守りアイテム、登録につなげたという実績があります。","id":"exchange-050"},{"speaker":"松澤委員","kind":"質問","question":"１１か所から２０か所と、広がりを見せていますが、どのような経緯で広がりがあったのでしょうか。説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"現在２０か所、実際には医療機関でやっていただいているものを含めますとさらにあと４か所ほどあるのですけれども、今、数が増えております。２回程度を想定したのですけれども、最大で４回実施していただいているというようなカフェもあり、大変進んでいると聞いております。","id":"exchange-051"},{"speaker":"松澤委員","kind":"質問","question":"やはり皆さん生き生きとしていまして、やはり自分が元気でいることが見られることがすごい喜びだということで大変好評だったのです。そういった映像を流すとか、そういった取り組み、こういうものはありますか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"連携ができておりまして、いろいろな形で情報交換、情報共有を行っているところです。過去に講演会を行った際には、当事者の方に実際にご講演いただきまして、ご来場の方からも大変感銘を受けたという声をいただいているところです。","id":"exchange-052"},{"speaker":"松澤委員","kind":"質問","question":"しかし、やはり一番は早期診断であると思います。そこで、先ほどもちょっと答弁が出ましたけれども、品川区における早期診断の取り組みについてのお考えはありますか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"そういった意味で、来年度、医師会の方にご協力いただきまして、令和３年度に向けた認知症検診の実施に向けた準備を進めていきたいと考えております。","id":"exchange-053"},{"speaker":"松澤委員","kind":"質問","question":"都内全域で約５万４,５００人が家具類の転倒・落下により負傷すると想定され、建物の耐震化と並び重大な地震対策ではないでしょうか。そこで、ここ数年において、この助成金が使われている傾向を説明するよう求めました。","respondent":"宮尾高齢者地域支援課長","answer":"実績ですが、今年度は２月末時点で２７件の申請をいただいております。平成３０年度は６２件、平成３０年度が他の年度よりも突出して高かったのは、その影響を受けて申請件数が伸びたと分析しています。","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問・要望","question":"家具転倒は寝ているときが一番危険だとお聞きしました。そういったところにしっかり拡充できるように、これからも支援してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本事業を声の上げにくい子どもたちと困難のあるご家庭のために継続性を持った事業としてぜひ育てていただきたいと要望しておりましたので。先ほど幾つか確認がありましたが、子ども食堂としあわせ食卓事業の２つに割り振るということになっていますが、その割合を説明するよう求めました。","respondent":"三ッ橋子ども家庭支援課長","answer":"周知の仕方ですけれども、児童扶養手当、こちらはひとり親医療証発送のときに、約１,５００世帯全員の方にお知らせをいたしました。そのほか広報しながわ１２月２１日号にお知らせをしています。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど伺った、集まった５５７万円余の子ども食堂との割合、どちらにどのぐらいの割合で配分するのかということも教えてください。今回も「等」だと思うのですけれども、この「等」のところを検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"三ッ橋子ども家庭支援課長","answer":"今回、５５７万円余が集まりまして、まず子ども食堂の継続支援に１００万円、こちらは子ども応援基金の中に入れします。子ども食堂のような場所に行かれない方、声が上げにくい方もいらっしゃることは確かですので、何とか拾い上げていきたいと考えています。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"提案","question":"３年前になりますでしょうか、私が文教委員長のときに提案させていただいて、区内の子ども食堂を委員会として視察したことがあります。それとも今後、全てケアマネジャーが引き受けるということなのでしょうか、このあたりのイメージを説明するよう求めました。","respondent":"寺嶋高齢者福祉課長","answer":"これまでの災害の避難の取り組みとしましては、各町会のほうにご尽力いただきまして取り組みを進めてきたというところは把握しています。これは町会にやっていただいている取り組みを補完するような形で、最終的には皆さんの避難計画ができればというふうに考えているところです。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"確認","question":"どういう状況であるのかということを町会・自治会の人が発災時に実際に安否確認して、ここについてちょっとイメージが湧きにくかったので。そして、その上でそういうことをやっていくのか、そこについてちょっとイメージが湧かなかったものですから説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"取り組みの進んでいる町会の方に関しましては、まさに本当に補完的な役割で済むと考えています。これを基本形としまして、それに対して取り組みの進みが若干遅いところ、同じようなスタイルまで持っていければと考えています。","id":"exchange-059","title":"町会・自治会支援"},{"speaker":"あくつ委員","kind":"質問","question":"そこのところについてちょっとイメージが湧きにくかったものですから。そこが事業者になるのか、それとも委託している民間の居宅介護支援事業所の扱いになるのか、そこについてわかれば説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"区内の２０の在支それから民間の居宅介護支援事業所、いずれにしてもケアプラン作成のときにご本人の同意を得るという行為が必要になってきます。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"提案","question":"私が前からご提案しているのは、これは町会・自治会としてそういった規定をつくる必要があるということを最後にもう一度訴えまして、私の質問を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061","title":"町会・自治会支援"},{"speaker":"くにば委員","kind":"質問","question":"本日は、２４７ページ、就学前教育推進費のＩＣＴ体験事業、２４５ページから保育室等記録機器モデル導入経費についてお伺いします。コミュニケーションロボットＳｏｔａに関して、こちらの事業内容と、導入した経緯、実績や他自治体での導入状況について示すよう求めました。","respondent":"佐藤保育課長","answer":"今、区は保幼小連携を積極的に進めておりますので、関心を持つ環境を整備することで小学校への円滑な入学を目指すというところで導入したところです。他区での導入状況ですが、こちらのロボットに関しましては２３区初と認識しております。","id":"exchange-062"},{"speaker":"くにば委員","kind":"質問・要望","question":"次に、こどもモードＫｉｔＳ搭載アプリについてお伺いします。こちらも事業内容、導入した経緯等をお伺いします。","respondent":"佐藤保育課長","answer":"導入の経緯ですが、平成３０年度の品川区社会貢献製品支援事業でございまして、来年度予算をお願いしています。実績に関しましては、昨年度のモデル実施に関しましては大体６５％程度の利用率です。","id":"exchange-063"},{"speaker":"くにば委員","kind":"質問・要望","question":"２つの事業とも２３区で初ということで、こちらの事業に関して本当に庁内全体であるとか、いろいろな方々にぜひ知ってほしいと求めました。続きまして、２４５ページの保育室等記録機器モデル導入経費についてお伺いします。","respondent":"吉田保育施設調整担当課長","answer":"一部例外はありますけども、ほとんどのものを撮る予定で考えております。現場説明会は２月末に終わりまして、４月に契約、設置工事等もありますので５月頃から運用を開始しようと予定しています。","id":"exchange-064"},{"speaker":"くにば委員","kind":"質問・要望","question":"今回、まずは４園でのテスト導入ということで、こちらの導入の有用性を考えますと、区立保育園全施設において早期の導入促進を求めますが、追加設置についての取り組み、また幼稚園での設置のお考えについて説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"そういう面を含めまして、まずは４園で実施いたしまして、そこでの問題点だとかがありましたら洗い出してみたいと考えております。その後の展開につきましては、検証を経まして、どうしていくかというところを考えていく予定でおります。","id":"exchange-065"},{"speaker":"くにば委員","kind":"質問・要望","question":"保育の質という部分に関して、事故はぜひとも減らしていただきたい。やはり保育士の負担を減らす、そういった部分の側面もありますので、ぜひとも労働環境の改善も含めて取り組みをお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"利用できない期間は代替場所を確保すべきだと思いますが、いかがでしょうか。敷地面積や改築要件などから従来の高齢者の利用が狭まってしまうということはないのか、伺います。","respondent":"宮尾高齢者地域支援課長","answer":"ただその間、本件につきましてもそのような丁寧な対応をしていきたいと考えております。それと考え方ですが、こちらも、まずはゆうゆうプラザへの転換を図るというところを基本に検討させていただきたいと考えています。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"右下の写真がわかりやすいですか、電動なので坂道も平気で、後には大きなかごもつけられるので買い物などにも便利だと。伺いますが、先の高齢者クラブの懇談会で出されましたこの電動アシスト三輪自転車の購入費補助の検討を行ってはいかがでしょうか、伺います。","respondent":"宮尾高齢者地域支援課長","answer":"その１つが高齢者の外出習慣化事業ということで、そこから習慣化してほしい、こんなことを現にやっております。こういった事業を通じて、いつまでもご自身の足でいろいろなところに行っていただくというところをベースに推進していきたいと考えているところです。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"こんな事例があったのですけれども、昨年１２月、私の主催する報告懇談会に、しばらく見ていなかった８０代の男性が久しぶりに参加してくれたのです。伺いますけれども、この電動アシスト三輪自転車というのは有効だと思いますけれども、この効果についてはどのように区はお考えか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"一つ言えるのは、例えばその中には体調がなかなか思わしくなくて会議に出ることができない、こういったことをおっしゃる方もいらっしゃいます。そういったさまざまな工夫をする中で外出支援、それから社会参加、こういったものをサポートさせていただいているです。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際に高齢者クラブの方からもそういう具体的な要望も出ましたので、ぜひ研究、検討してほしいと求めました。小学校４年生以上であっても考慮して午前中からすまいるスクールで受け入れるような体制をとるべきだと思うのですが、いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"登録のないお子さんに関しましても、就労等事情がある場合はご相談に応じてということになっておりますので、誰でもというわけではございませんが、現在のところ４年生以上で障害がある方で今回特別に、という方は耳に入ってきてはございません。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"率先して感染予防に協力いただいている方もいるわけですから、ぜひご検討の上、受け入れをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"木村委員","kind":"確認","question":"私からは、２１１ページの上から４行目、高齢者安否確認事業からの質問をしたいと思います。そして地域の見守りマップ作成などに取り組んでおられますけれども、成果はどのように出ているか、説明を求めました。","respondent":"大串福祉計画課長","answer":"今現在、令和元年度で６１の町会・自治会の皆様方にご協力いただいているところです。こういったさまざまな活動を通じて、町会・自治会内のひとり暮らしの高齢者等の安否の確認をやっていただいているといった事業です。","id":"exchange-072"},{"speaker":"木村委員","kind":"質問","question":"品川区では今現在、２０３の町会・自治会があると私も記憶しております。現在、本区でのパトロール活動というのをやっている町会・自治会というものは以前と変わりがないのかどうか、お聞きかせいただくよう求めました。","respondent":"大串福祉計画課長","answer":"各町会・自治会の取り組みはそれぞれです。はそれぞれの地域の特性に応じた形での見守り、取り組みの中身としては、それぞれ６１の町会・自治会でさまざまといった状況です。","id":"exchange-073","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"意見","question":"今言われたように町会・自治会ごとにいろいろなパターンがあろうかと思いますけれども、またこれもしっかりと続けてほしいと思います。何か変わったようなことが起きた事例というのはあるのかどうか、今後のためにも差し支えのない程度でお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"この事業が始まって、見守り活動の中で特に何かトラブルということがあったということでのお話は、こちらには特に届いているところではございません。","id":"exchange-074","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"質問・要望","question":"住民同士がさりげなく気遣い合い、困ったときに遠慮なく助けを求めるような、頼めるような地域社会づくりが求められていますけれども。個人個人が今以上に仲よくなる策や、また町会単位で活動を考えるべきと思いますけれども、いかがか尋ねました。","respondent":"大串福祉計画課長","answer":"まさに今、こういった方々が相互に見守り合いができるような社会、こういったものが地域共生社会の実現につながっていくと考えているところです。そうしたものをうまく醸成しながら、共生社会の実現に向けて各施策を充実させていきたいと考えているところです。","id":"exchange-075"},{"speaker":"木村委員","kind":"質問・要望","question":"皆さんが日ごろ行っている町会単位で高齢者、今以上に地域での集まりの開催というものに対して行政側はどのように思っていますか。説明を求めました。","respondent":"大串福祉計画課長","answer":"あるいは民生委員の皆さん、高齢者クラブの皆さん、そういった関係性の中でさまざまな機会と場をご用意していただいていたと考えています。こういった事業の展開等々をご紹介させていただきながら、そういった機会と場、この提供の機会を増やしていければと考えております。","id":"exchange-076"},{"speaker":"小芝委員","kind":"質問","question":"その課題を解決する一環で、昨年の決算特別委員会でも伺いました手話言語条例のことをお聞きします。ご家族の方々、また明晴学園のお考えをお伺いしながら研究を進めていきたいとのことでしたが、その後５か月を経過しました。","respondent":"松山障害者福祉課長","answer":"先ほどの話題にもなりました日本語対応手話、手話が言語であるという考えということにつきましては、ある程度ですけれども合意しつつあります。合意が非常に大事だと考えていますので、引き続き意見交換を重ねまして丁寧にすり合わせを行ってまいりたいと考えております。","id":"exchange-077"},{"speaker":"小芝委員","kind":"質問","question":"しかし、全世界でも４年に１回、アジアでは、１１年前に台湾でデフリンピックが行われました。課長からは国、都と連携して開催できるかどうか検討していきたいという答弁をいただいておりますが、その後の検討の経過をお聞かせ願います。","respondent":"松山障害者福祉課長","answer":"デフリンピックの検討状況についてです。東京都の動向を注視し、招致の可能性とか、あるいは方向性が決まりましたら、できる限り区としても協力を図ってまいりたいと考えています。","id":"exchange-078"},{"speaker":"小芝委員","kind":"質問・要望","question":"次に、２４７ページの東大井保育園についてお伺いします。東大井保育園の老朽化に伴います改築工事により、東大井公園内に仮の園舎を建設し、４月から２年間、仮の園舎を稼働するとの話を伺っております。","respondent":"吉田保育施設調整担当課長","answer":"立会川方面からの厳密に細かい人数までは不明なのですが、約５０名はいらっしゃるのではないかと考えております。","id":"exchange-079"},{"speaker":"小芝委員","kind":"質問","question":"大井消防署隣りの木の芽坂を上りまして１つ目の丁字路を左に曲がって、こちらの木の芽坂はガードレールが片方にしかございません。は横断歩道をつくるとかして環境を整えていくべきだと思いますが、こちらのほうはどうなっているのか、説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"そこのところにたしかカーブミラー等がかなり多数あったように思います。その辺は、保護者の方に十分注意していただくよう周知してまいりたいと思っているところです。","id":"exchange-080"},{"speaker":"小芝委員","kind":"質問・要望","question":"続きまして、２３１ページのヘルプカードについてお聞きします。新規といいますか配布されるとのお話を伺いましたが、その内容、形状について説明を求めました。","respondent":"松山障害者福祉課長","answer":"今現在もある程度の支援情報を記載できる部分があると考えていますが、引き続きそちらの支援情報が記載できるものをというお声をいただいておりますので、来年度につきましてはその声を反映したヘルプカードを新たに作成したいと考えております。","id":"exchange-081"},{"speaker":"小芝委員","kind":"質問","question":"周囲の方に配慮を必要としていることを知らせることで援助を得やすくなるよう作成したマークです。五反田駅、あとは都営バスの営業所で配布されているとお聞きしておりましたが、こちらは地域センターなどには配布されているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"今現在、委員がおっしゃられた駅等に配布しているものであって、これ以上の配布先としては難しいという声をいただいております。ただし、配布先まで行かれない困難な方につきましては東京都のほうにお問い合わせいただいて、郵送する場合もあるという回答を得ております。","id":"exchange-082"},{"speaker":"小芝委員","kind":"質問","question":"この１１.４％の中で世代ごとの人数というのはわかりますか。特に生産年齢で２０代から５０代まで、その世代ごとの人数を、もしわかれば説明を求めました。","respondent":"矢木生活福祉課長","answer":"世代ごとの人数ですが、申しわけございません、統計をとっておりませんが、廃止の決定通知等は私を経由しますので、その感じだと４０代、５０代の方が多いように思っております。","id":"exchange-083"},{"speaker":"小芝委員","kind":"質問","question":"もしわかれば教えてください。その成果も説明を求めました。","respondent":"矢木生活福祉課長","answer":"そして成果といたしましては、平成３０年度は就労開始された方が１５人で、支援を終了された方が１２人。令和元年度は同様に就労開始された方が８人といった成果になってあります。","id":"exchange-084"},{"speaker":"小芝委員","kind":"質問","question":"そもそも就労経験がない人、引きこもりの方など、そのほかにもさまざまな理由で就労への課題を抱えた方がいると思います。そういう方々も一律にこの自立支援事業の対象に組み込まれているのか尋ねました。","respondent":"矢木生活福祉課長","answer":"こちらの就職力アップの対象者ですが、開始原因の中で傷病、障害といった疾患を抱えられている方は除きます。そして稼働年齢層、おおむね高校生ぐらいから６５歳までの年齢ゾーンの方ということで、対象者をその中から選定しています。","id":"exchange-085"},{"speaker":"小芝委員","kind":"質問","question":"ちょっと時間が足りないので進めますが、２４１ページの高校生等入院医療費助成についてお聞きします。その感想について、一言お聞かせ願います。","respondent":"三ッ橋子ども家庭支援課長","answer":"高校生の入院医療費助成ですけれども、かなり好評を得ております。","id":"exchange-086"},{"speaker":"横山委員","kind":"質問・要望","question":"２３８ページ、２４２ページ、児童保育費についてお伺いいたします。","respondent":"二ノ宮児童相談所移管担当課長、廣田子ども育成課長","answer":"特別区が児童相談所を設置するに当たりましては広域調整等の仕組みが必要であるということは、委員ご指摘のとおりです。児童相談所を設置する自治体というのは措置権者と言われて… 委員ご案内のとおり、児童センターは子育て世帯にかなり信頼を得ているところです。今現在、今後については委員の意見を参考にさせていただいて、子育て支援を進めていきたいと思ってあります。","id":"exchange-087"},{"speaker":"横山委員","kind":"質問・要望","question":"家事育児ヘルパーなど人材育成の支援を求め、進めてほしいと求めましたが、いかがでしょうか。要支援家庭移行を未然に防止する意味で区のスキームを整理しながら活用していただきたいと考えますが、区のご見解をお伺いします。","respondent":"佐藤保育課長、廣田子ども育成課長、崎村児童相談担当課長","answer":"高い評価をいただきまして、誠にありがとうあります。今後も気を引き締めて区民サービスの充実に努めてまいります。すまいるスクールについても、引き続き地域の皆様に喜んでいただけるように取り組んでまいります。多胎児の育児支援についてですけれども、これはたしか２年前だったかと思うのですが、また経済的負担も大きいと認識しております。","id":"exchange-088"},{"speaker":"横山委員","kind":"確認","question":"国の未就園児等全戸訪問事業に関連してもお伺いいたします。未就園児などの安否確認を区でしていただいているかと思いますが、その訪問する際なのですけれども、区のお考えを説明するよう求めました。","respondent":"崎村児童相談担当課長","answer":"乳幼児健診の未受診ですとか、未就園児等の緊急把握の実施ということで、平成３０年度から安全確認や状況把握の調査を実施しています。","id":"exchange-089"},{"speaker":"塚本委員","kind":"確認","question":"初めに２２９ページ、ちょっと時間が足らなくて議論が中途半端になってしまったので再度確認させてください。そういった中で、その国の議論が前提だとは思いますけれども、区としてこの状況というかあり方についての考えということをお伺いしたいと思います。","respondent":"松山障害者福祉課長","answer":"区の認識についてですけれども、例えば上乗せ補助するという形にできるかどうかについては、現段階ではちょっと難しいかなと考えています。ですが、引き続き事業者に安定して児童発達支援に良質なサービスを提供していってほしいと考えていますので。","id":"exchange-090"},{"speaker":"塚本委員","kind":"確認","question":"これはいたし方ないというか、やらざるを得ない措置だと思いますけれども、一応、現在公表されているところでは３月３１日、今月いっぱいです。そういったことも出てきたりしているところはないのか、これまでどおり安定して通常どおりだということなのか、そこを確認したいと求めました。","respondent":"寺嶋高齢者福祉課長、松山障害者福祉課長","answer":"特養ホームを初め入所系の施設につきましては、３月３１日まで面会の原則中止という形をとらせていただいたところです。場所、消毒等を徹底してそういった対応は例外的にはできるという前提のもとでの対応となっておりますので… 今のところ施設側から特段大きな変化はないと聞いております。さらにそれ以上に感染症予防に配慮して支援を行っていると聞いております。","id":"exchange-091"},{"speaker":"塚本委員","kind":"質問","question":"一応３月３１日までということになっておりますけれども、４月以降についてもというところはあるかと思いますので、よろしくお願いしたいと思います。それから、この予算書をどう見ればわかるのかというか、どう見ればよいのかということを最初に説明を求めました。","respondent":"大澤保育支援課長","answer":"私立保育園の特別支援児の加算ですけれども、区内私立保育園経費の運営費の区加算という項目の中に入ってあります。予算としては、今年度は昨年度の実績を踏まえまして５０名程度の予算を見込んでいるところです。","id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"今現在は身体障害者手帳５級、現実的に必要なところにきちんと加配するというようなことがなし得ない部分もちょっとあるやに聞いております。かなり客観的に周りから見ると特別支援は必要だねといったような場合に加配していくというような考え方というのは難しいのか尋ねました。","respondent":"大澤保育支援課長","answer":"保護者の方に客観的な資料を求めるのがなかなか難しいというお声は確かにあって、それはご相談を受けたときは個別に対応しております。基本的には特別支援の巡回指導等で臨床心理士の方が各園を回っており、その中で対応していただいているという状況です。","id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"特に保護者の方への理解促進ということがしっかり進めばこの問題も大分解決する部分もあると思いますので、よろしくお願いしたいと思います。最初に、事務負担増というのはどういうところが増えているのかというところを教えてほしいと求めました。","respondent":"大澤保育支援課長","answer":"無償化に伴う私立保育園の事務負担ですが、一番大きなところは副食費を保護者から徴収する事務が各園でかなり大変だと聞いてあります。ただ、品川区におきましては副食費分は公費負担になってありますので、品川区内の園ではそのような事務負担は生じておりません。","id":"exchange-094"},{"speaker":"塚本委員","kind":"意見","question":"ただ、品川区内の事業者にも私も直接聞いていることでもあるので、やはりそれ以外の部分でも何か増えている部分もあるのかなとも捉えております。","respondent":"大澤保育支援課長","answer":"無償化に伴う事務に限らず、補助金ですとか公定価格の部分でかなり難しい書類がたくさんあることは認識していますが、都に出したり、国に出したりということでいたし方ない部分もあるのですけれども、できるだけわかりやすい説明をするなど、努めてまいりたいと思います。","id":"exchange-095"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２１７ページ、外国人介護人材受入環境整備、４８５ページ、後期高齢者歯科健康診査についてお聞きいたします。初めに２１７ページ、いないのかということと、取り組みをまず最初に教えてほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"品川区の法人が未実施である事業といったあたりを重点的に洗い出しまして、その中の１つであったのが外国人材の活用というところでございました。","id":"exchange-096"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"居住支援として、大体でいいのですがどういうふうにやっていくのかということと、これは時期的にいつごろから運用されるのかということです。その取り組み内容と、時期はいつごろになるのかということをお知らせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"これはぜひ取り組んでいきたいということで、それを引いた法人負担分の８分の７を月額で助成、その他もろもろの雑費等を考えております。区立指定管理につきましては都の補助金の対象にならないので、区のほうで独自に補助するということを考えたものです。","id":"exchange-097"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして４８５ページ、後期高齢者歯科健康診査についてお聞きいたします。今期、今期からの初めての事業だと思うので、まずその内容をお知らせほしいと求めました。","respondent":"池田国保医療年金課長","answer":"後期高齢者医療の歯科健診の内容についてお知らせいたします。それからフレイル評価ということで３つの健診を行うものでございまして、従来の口腔内検査だけでなく、実際にフレイルに着目した検査です。","id":"exchange-098"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"わかりました。これは対象者が７６歳、約７,０００人に対して受診の見込み者数が約２,０００人ということなのですけども、わかれば教えてほしいと求めました。","respondent":"池田国保医療年金課長","answer":"今の歯科健診についてですけれども、１月３１日で終了ということになってございまして、私どものほうに請求があった件数ですが、実際には８１８件が２月末の結果として届いている状況です。","id":"exchange-099"},{"speaker":"高橋（伸）委員","kind":"質問","question":"見込み人数もまた２,０００人ということで、これは見込みですから２,０００人という数字が出ているのですけれども、区の予想としてはどの程度になるのかということを説明するよう求めました。","respondent":"池田国保医療年金課長","answer":"今年度の実際の受診率につきましてはおよそ１４％を見込んでいたところですけども、７８歳、それから８０歳の方と３世代をまとめまして約２,０００人ほどの方に受診していただきたいということを予想しています。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"私からは２３９ページ、子育て応援課の組織改編について、２４１ページ、子どもすこやか医療費助成事業について伺います。福祉を後退させて、権利保障から自己責任に変質させるものではないのか、伺います。","respondent":"三ッ橋子ども家庭支援課長","answer":"来年度、課名を変更いたします。そしてひとり親家庭相談、またガバメントクラウドファンディングなど子育て事業の推進に向けて取り組んでまいります。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問","question":"こうした上位計画のもとでの組織改編のため、後退しかねないという危惧は拭いきれないと考えています。これまでの子ども家庭支援課では、施策を後退させるものではないということでよろしいか尋ねました。","respondent":"三ッ橋子ども家庭支援課長、崎村児童相談担当課長","answer":"児童相談機能の強化のために子ども家庭支援センターが課として設置されますので、その関係で子ども家庭支援課が子育て応援課に変更になります。業務後退は全くいたしませんので、引き続き推進して取り組んでまいります。来年度、我々の所管、児童相談担当部署で子ども家庭支援センターというものを設置いたします。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"理由はわかりました。むしろこの名称が変わってよくなったと言われるようにぜひ充実してほしいと求めましたけれども、いかがか尋ねました。","respondent":"三ッ橋子ども家庭支援課長","answer":"来年度から子育て応援課として事業が本当に進んで、いい課となるように引き続き努力してまいります。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に、子どもすこやか医療費助成について伺います。今年度の申請件数とその医療費を伺います。","respondent":"三ッ橋子ども家庭支援課長","answer":"今年度の申請が確定している件数は１６件で、その関係の費用ですけれども約１３０万円となっております。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問","question":"今年度の予算では２５０件で８０４万円となっていますけれども、見込みよりも低い水準になっているということになりますが、申請数が少ない理由は何だと考えているのか、伺います。","respondent":"三ッ橋子ども家庭支援課長","answer":"今、委員ご指摘の申請数が少ないという部分ですけれども、非常に難しいと捉えております。まだ明確なことは検証しておりませんけれども、元気な高校生が多いのか、そのあたりは検証しないと明確なことはわかりません。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそこは検証してほしいと求めましたけれども、引き続き周知徹底をお願いいたしますが、いかがか尋ねました。","respondent":"三ッ橋子ども家庭支援課長","answer":"こちらの周知徹底の部分ですけれども、４月１日、また４月２１日、そして６月２１日の広報しながわでお知らせしています。そのほか児童扶養手当、子ども家庭支援課の窓口などでも対応しております。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまでも求めてきましたが、ひとり親家庭医療費から割り出されたということで２億４,０００万円との答弁でした。１人当たり８,５００円ということになり、ぜひ１８歳まで医療費の無料化を実施してほしいと求めましたけれども、いかがか尋ねました。","respondent":"三ッ橋子ども家庭支援課長","answer":"まだまだ検証の段階だと考えています。品川区といたしまして拡大につきましては非常に難しい、また今のところ全く検討していない状況です。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"全く検討していないというお話ですが、先ほどの入院費の問題でも無料にして大変好評だということでしたので、入院費の助成を今年度から始めた効果というのはいかがだったか尋ねました。","respondent":"三ッ橋子ども家庭支援課長","answer":"今回、高校生まで拡大した高校生等の入院医療費助成ですけれども、申請された方のご意見を伺いますと非常によかったと聞いております。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"助かると思いますので、ぜひ１８歳まで拡大してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"あべ委員","kind":"質問","question":"それから２３１ページ、２４２ページ、時間があれば２５９ページのオアシスルームまでお伺いしたいと思います。特に保育園などの応援態勢を考える時期に来ているのではないかと思いますが、いかがお考えか尋ねました。","respondent":"佐藤保育課長","answer":"区立保育園における新型コロナウイルス感染症の対応ですが、ふだんから質の高い保育ということで人材を充実させているところです。３月２日に臨時の園長会を行いまして、今回の新型コロナウイルス感染症の対応に向けて全力で取り組むということで、休める環境に向けて。","id":"exchange-110"},{"speaker":"あべ委員","kind":"質問・要望","question":"そしてどのような形でシフトが組めているのかということも、保育課でぜひ確認をしてほしいと求めましたが、いかがでしょうか。あるいは歩ける医療的ケア児や知的な遅れのない医療的ケア児にも対応するかどうかということについて、お考えを説明するよう求めました。","respondent":"吉田保育施設調整担当課長、松山障害者福祉課長","answer":"公設民営園の運営についてのお話かと思います。公設民営園につきましても区立園同様、柔軟なクラス編成をもちましてこの大変な事態を乗り切っていくように考えて、周知しています。４月以降に委員会報告させていただいた後、公募の上、来年度中には開始していただくことを考えております。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問","question":"歩ける医療的ケア児などは相談できるところもとても少ないと思いますので、ぜひ事業者と相談の上、整えてほしいと求めました。その結果の数字について、二次の申し込み数、承諾数そして不承諾数を説明するよう求めました。","respondent":"佐藤保育課長","answer":"二次の内定ですが、０歳児が９７名、１歳児が７１名、２歳児が６２名、３歳児が７０名、４歳児が４２名、５歳児が１９名の３６１人です。５歳児４４名、合計１,２１７名で、一次の発表時よりも３７０名程度減っているところです。","id":"exchange-112"},{"speaker":"あべ委員","kind":"質問","question":"この１,２１７人の方々は、二次が終わった後でそれぞれどのような行き先があると考えていらっしゃいますでしょうか。今度の待機児童数がどの程度になるか、改めて見通しを説明するよう求めました。","respondent":"大澤保育支援課長","answer":"そちらのほかの施設への利用ということで考えております。実質的にはゼロに近い数になると思いますけれども、空きはあっても、待機児童としてはやはり何人かは残ると考えております。","id":"exchange-113"},{"speaker":"あべ委員","kind":"質問","question":"来年度はここにさらにプラス１００人の行き先のない子どもたちがまた出てきて、来年度の待機児童激増の要因になるのではないかと危惧しております。来年度も含めての定期利用に対するお考えというのはどのようになっておりますか尋ねました。","respondent":"大澤保育支援課長","answer":"令和３年４月の開設の計画につきましては、ひろまち保育園の閉園も見込んだ開設の計画を立てておりますので、そこは飲み込んでいけると現時点では認識しています。","id":"exchange-114"},{"speaker":"あべ委員","kind":"質問","question":"ベビーシッター制度では今度東京都が、利用者にとっては１時間１５０円という非常に利用しやすい金額での新たな事業を打ち出しているところです。こうしたことが保護者の誤解やトラブルを生まないように、区のほうでも都と連携して説明が必要だと思いますが、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"区からのご案内でも、必ず利用案内、利用約款についてはご覧くださいということを明記しており、また、必ず区の窓口に一度は来て、職員から説明を受けることになっておりますので、その中でもその辺は漏れなくご案内したいと考えております。","id":"exchange-115"},{"speaker":"あべ委員","kind":"質問・要望","question":"最後にオアシスルーム、これは要望だけにしておきますが、八潮地域で今後開設に向けて努力するというご答弁をいただいております。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"西村委員","kind":"質問","question":"２５７ページ、２５９ページ、すまいるスクールについて伺います。今、区内にどのような場所があるか尋ねました。","respondent":"廣田子ども育成課長","answer":"ぷりすくーる西五反田の子育て支援センター内にある子育て広場、家庭あんしんセンター内にありますフラット広場、地域交流室であるポップンルーム等があります。","id":"exchange-117"},{"speaker":"西村委員","kind":"質問","question":"私も区報などを見ながら、区内の親子施設を改めて整理してみたのですが、室内で平日をメインにいつでも行ける場所はどちらでしょうか。ぷりすくーる西五反田内の地域子育て支援センター、平塚橋の子育て支援センター、ポップンルーム、児童センターで合っていますか尋ねました。","respondent":"廣田子ども育成課長","answer":"場所によって曜日が決まっているものもありますが、全て自由に行くことができます。","id":"exchange-118"},{"speaker":"西村委員","kind":"質問","question":"ベビーカーで行く行動範囲でいつでも行ける場所というと、ずっと減ってしまうのではないかと思いますが、いかがでしょうか。区内に空白地域はないか尋ねました。","respondent":"廣田子ども育成課長","answer":"品川区の児童センターの中に親子サロンというのを設けておりまして、そちらについてはいつでも行くことができます。品川区内に児童センターが２５館ありますけれども、空白地域ということで、こちらで子育て交流サロンを開いているという経過があります。","id":"exchange-119"},{"speaker":"西村委員","kind":"質問・要望","question":"その方にお話を伺いますと、小学生が一気に流れ込んできたりして、危なかったというふうなお声もありました。小さな子どもを育てている親がほっと和めるような居場所としての改善を要望しますが、いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"親子の広場につきましては月齢ごとに分けてクラブという形でやっているところがたくさんありますので、そちらもご利用いただければと思ってあります。","id":"exchange-120"},{"speaker":"西村委員","kind":"質問・要望","question":"区民の皆さんがサービスを活用するために、もう一度、地域のネットワークがどうなっているのかも見てみていただきたいと思っています。今後、子育て支援活動を行っているグループに対する支援の取り組みイメージがありましたら、説明を求めました。","respondent":"廣田子ども育成課長","answer":"一つは、地域の団体の方が自主グループで支援事業を行う際に、新年度から上限５万円として事業に対して助成をする制度も持ってあります。","id":"exchange-121"},{"speaker":"西村委員","kind":"質問・要望","question":"地域のつながりの中で、ほっとサロンをサポートしてくださっている方々での、横の連携もあるというふうに伺いました。声をかけ合っているというふうに区民の方から伺っておりますので、ぜひとも支援の輪を広げていただけますようお願いいたします。","respondent":"三ッ橋子ども家庭支援課長","answer":"こちらは地域で子育ての援助を行いたい方、子育ての援助を受けたい方、依頼会員を支援するための事業です。今後は、委員ご指摘のことも含めてさまざまな課題解決に向けて、一歩一歩進めていきたいと考えています。","id":"exchange-122"},{"speaker":"西村委員","kind":"質問・要望","question":"何か今の時代にそぐう形で、求めている方がこれだけいらっしゃいますので、できないかと思っています。今、提供会員の中で、１人の方が何人ものお子さんを見るというような現状もあると思うのですが、そのあたりの現場の雰囲気を説明するよう求めました。","respondent":"三ッ橋子ども家庭支援課長","answer":"委員ご指摘のように、提供会員が少ないという部分に関しましては、依頼会員との比率でやはり、さまざまな状況、現場の声を聞いております。そのあたりにつきましても、平塚、大井ファミリー・サポート・センターの皆さんと、打ち合わせを持って対応してまいりたいと考えています。","id":"exchange-123"},{"speaker":"西村委員","kind":"質問・要望","question":"新型コロナウイルス感染症におけるすまいるスクールの体制に関しまして、改めて、区民の方々の声を届けさせてほしいと求めました。どのような声が区民の方から届いているか、説明を求めました。","respondent":"廣田子ども育成課長","answer":"そちらについては少人数で部屋を分けて、対応しています。いろいろ賛否があろうかと思いますけれども、働く親御さんに協力していくという形で取り組んでおります。","id":"exchange-124"},{"speaker":"西村委員","kind":"質問","question":"最後に申し上げました、○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○、特に低学年のお子さんは先生方もサポートしてくださっていると伺っておりますが、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"大倉委員","kind":"質問","question":"それについて伺いたいのですが、これ自体は金額が異なっているということと、内容の違いがあるのかということを簡単に教えてほしいと求めました。そういったところの影響というのはどのようにあったのかということで、今の状況や閉館の影響についてお知らせほしいと求めました。","respondent":"佐藤保育課長、大澤保育支援課長、宮尾高齢者地域支援課長、寺嶋高齢者福祉課長","answer":"区立保育園５歳以上を対象に、また、実際にオリンピック・パラリンピックを見学する場合の熱中症対策等の経費が入っております。私立保育園については公立保育園と同様ですが、私立幼稚園に関しましては、このほかにバレーボールセットを各園にお配りすることになっております。団体の方からは、活動の場所がなくなってしまってとても残念だというお声は、確かにちょうだいしております。やはりそこは… 特養ホームというご指摘がありましたので、お答えいたします。","id":"exchange-126"},{"speaker":"大倉委員","kind":"質問・要望","question":"５歳児の子どもたちと一緒に見学しに行くということが、どのくらいの子どもたちが行けるのかということを教えてほしいと求めました。いきいき健康マージャン広場、いきいきカラオケ広場などがありますが、この辺についてはどのようになっているのか教えていただきたい。","respondent":"吉田保育施設調整担当課長、宮尾高齢者地域支援課長","answer":"これはやはり何十年に１度しかないものですので、観戦する子どもたちの心の記憶に残るような形で、対応がとれればと考えております。それから園単位ですけれども、例えば冷やせるようなものを何か配ろうということで予定しております。 その他、例えば春先、春以降に行っているものにつきましては、慎重に見極めさせていただいて、また別途判断させていただきたいと考えています。いずれにしましても、丁寧なご案内を心がけてまいりたいと考えています。","id":"exchange-127"},{"speaker":"大倉委員","kind":"質問・要望","question":"オリンピック・パラリンピック応援事業ですけれど、どのくらいの子どもたちが参加できるのか教えてほしいと求めました。５歳児ということ、７月できっとかなりの暑さだということで、記憶に残るように取り組んでいっていただきたいのです。","respondent":"吉田保育施設調整担当課長","answer":"どういうことをやっているというのがわかるような、記憶に残るような、ずっと子どもの思い出に残るような形で伝えていければと考えています。人数につきましては、予定ですけれども、大体１,５００人ぐらいです。","id":"exchange-128"},{"speaker":"こんの委員","kind":"質問・要望","question":"２４５ページ、２６５ページ、この４点をお伺いしたいと思います。障害者団体の方々などのご意見やご要望、かばんなどにつけられるようにすることなどを求めてきたことが反映されたもの、ストラップ。","respondent":"松山障害者福祉課長","answer":"来年度予算でヘルプカードをつくるものにつきましては、一括して収納できるようなものというのは、私どもでも考えております。ただし支援情報等の細かい記載内容につきましては、その情報を見てどのような支援をわかりやすくできるのか、ちょっと検討していきたいと思います。","id":"exchange-129"},{"speaker":"こんの委員","kind":"提案","question":"これを区の窓口で配布してほしいという声を聞くのですが、私も都に確認をいたしました。直接ストラップにヘルプマークが付してあるストラップ、カードが収納できる形状にしてはいかがかと考えるのですが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"委員ご提案の形状のものにつきましては、東京都のほうがやはり権利を持っているところなので、東京都福祉保健局と十分に相談の上、ご利用者の声が反映できるようなものをつくっていきたいと考えています。","id":"exchange-130"},{"speaker":"こんの委員","kind":"確認","question":"ぜひ東京都のほうにも確認していただいて、スクラップに両方入れるよりもさらに利便性が高まるかと考えますので、よろしくお願いします。高齢者福祉部門や子育て部門でも配布をする、こうしたことも必要ではないかと考えますが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"現在のヘルプマークは、幅は広いのですけれども、なかなか支援情報というのが、任意に記入が難しいというデメリットがあります。さまざまな支援が必要な方の声があると思いますので、お声を聞きながら、検討していきたいと考えています。","id":"exchange-131"},{"speaker":"こんの委員","kind":"質問","question":"双方で入力をして、そして保護者の方は見たいときに見られる、そうしたことで大変に有用だと考えております。成長ぶり、それが動画や写真でも伝えられるようになるというふうに思うのですが、その点の運用はどのようになっていますか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"モデル実施をする際には、現行の紙のものを電子にしてみたらどうなるかというところから始めましたので、特に写真、動画等の使用はしておりません。","id":"exchange-132"},{"speaker":"こんの委員","kind":"質問","question":"それで、この運用に当たってもう一つ気になるのが、セキュリティの関係です。いわゆる情報漏えい、第三者の侵入、こうしたことが気になりますけれども、セキュリティ対策はどのようになっていますか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"セキュリティの面では４点あるかと思います。そういうようなところを契約上に盛り込みまして、安全な状態を確保して、それを利用者に使っていただくということで対応してまいります。","id":"exchange-133"},{"speaker":"こんの委員","kind":"質問","question":"すまいるスクール運営費でお伺いしたいと思います。午前中、午後を過ごされているのか、簡潔に、答えるよう求めました。","respondent":"廣田子ども育成課長","answer":"過ごし方といたしましては、午前中に１時間、学習タイムで自習をするであるとか、学校図書館で本を読むであるとか、間を見て校庭、体育館で体を動かすような形で、バランスよく過ごしています。","id":"exchange-134"},{"speaker":"こんの委員","kind":"提案","question":"これは提案なのですが、一つの案として、いわゆる学習の面で、学習塾などさまざまな民間事業で学習できる環境を提供する動きが広がっております。学校の教室を開放していただき、子どもたちがテレビで学習をする、こうした時間も過ごしてみてはいかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"なかなか長期化していく中で学習も大切ですので、今後教育委員会と協議して、検討してまいります。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"職員の増員ということは、もう前々から言っておりますが、どういう状況になっておりますでしょうか。それから施設の建て替えが計画されると思うのですけれども、今後全体的な計画はどうなっているか尋ねました。","respondent":"廣田子ども育成課長、二ノ宮児童相談所移管担当課長","answer":"保育園と調整しつつ、今年度予算で計上しております１８歳以上の施設については、適地となるところの検証を令和２年度にしようと考えております。今後については、どのような施設をつくっていくかというところを検討した中で… こちらは地域力を生かした見守りによる児童虐待の未然防止、早期発見を実施して、迅速かつ的確に対応するというものです。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"ノウハウを検証しながら継承してほしいと求めましたけれども、人員はどうなのでしょうか。ぜひ増やしてほしいのですが、いかがか尋ねました。","respondent":"廣田子ども育成課長、二ノ宮児童相談所移管担当課長","answer":"今現在、１８歳を超えても社会自立できないというので、言い方は悪いですけれど困難を抱えたお子さんだけを集めるような施設はあります。今の人数で委託を拡充し、もっと児童指導職の育成ができるような形をとりながら… 先ほどお答えした視点の２番目で、区の対応のサービスを生かし支援を必要とする子どもと家庭を重層的、横断的に支援するとお答えしたところです。","id":"exchange-137"},{"speaker":"西本委員","kind":"質問・要望","question":"本当に全国的にも先駆けてすばらしいことをやっている方々が多いものですから、ぜひとも後継者を育てていただきたい。総合的に１人のお子さんがどういうふうな子どもに育ってほしいかということも、ぜひさまざまな所管課で協力してやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですから、これから国保料は毎年値上がり続けるわけです。今回の国保料算定の大もとの賦課総額を伺いたいと思うのです。","respondent":"池田国保医療年金課長","answer":"令和２年度の国民健康保険の算定に当たりましての賦課額ですけども、後期高齢者支援金、介護納付金の合計分ということでやらせていただいております。後期高齢者支援金分につきましては２６億円、合わせまして１２１億１,０００万円ほどが納付金という形になっているところです。","id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問","question":"この条例審査のときにいただいた資料には、納付金と保険事業費が賦課総額という枠で囲われているのですね。なので、この１２１億１,０００万円と、この１２１億１,０００万円というのが賦課総額ということで考えていいのか尋ねました。","respondent":"池田国保医療年金課長","answer":"今回の場合は基礎分が７.１４％、後期高齢者支援金分については２.２９％、２３区共通の国民健康保険料ということになります。その式に基づいて出た数字が賦課総額という形になるところです。","id":"exchange-140"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、区も、国や都には公費の投入を求めています。保険料が想定よりも集まったというか、収入があったという、その理由は何か、説明を求めました。","respondent":"池田国保医療年金課長","answer":"保険料の収入が多くあったですけれども、こちらにつきましては保険料の収納率、こちらが多くあったです。それと繰越金ということにつきましては、平成２９年度から平成３０年度に繰り越したお金を繰入金のほうに戻したということで、やっておるところです。","id":"exchange-141"},{"speaker":"石田（ち）委員","kind":"意見","question":"収納率が９２％あるというのは知っているのですけれど、想定よりも保険料の収入があったということを説明されているのです。ですので、想定していたよりも保険料が集まってきた理由というのを説明するよう求めました。","respondent":"池田国保医療年金課長","answer":"収納が多くなった理由というのは、まず加入されている方の納付意欲があった、向上されているということで、自主納付が多くなっていたこと、それと私どもの職員の収納に対する努力が実りまして、結局のところ、予想以上の収納があったということだと考えています。","id":"exchange-142"},{"speaker":"石田（ち）委員","kind":"質問","question":"９２％という高い収納率の品川区、２３区でトップです。品川区のここ１０年間の滞納処分の執行停止数、この推移を説明するよう求めました。","respondent":"池田国保医療年金課長","answer":"２億３,０００万円、２億２,０００万ということで、すごく多かった年もあります。私どもとしてはその年、その年で、お支払い困難な方とか、徴収ができないものについては、執行停止ということで処理をしています。","id":"exchange-143"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に大変な方には、収納率にもしっかりと反映してきますので、執行停止ということを進めていただきたいと思うのです。なぜ今回徴収することとしたのか、そして今まで徴収してこなかったのはなぜなのか、伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"なぜ令和２年度から実施をするかについてですけども、今回、延滞金の運用を考えさせていただいたことがまず一つあります。そういったものを受けまして、令和２年度から延滞金の運用を開始するところです。","id":"exchange-144"},{"speaker":"石田（ち）委員","kind":"意見","question":"多分、国保が始まってから７０年間取ってきていないですよね。これからのことはわかったので、なぜ今までとってこなかったのかという理由をもう一度説明を求めました。","respondent":"池田国保医療年金課長","answer":"なおかつ医療費のほうも増えていくというところで、保険料の収納がこれまで以上に大事なものであるですので、延滞金のほうを始めするということでご理解いただければと思います。","id":"exchange-145"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほども自主納付が多くなった、職員の努力だということをおっしゃっていましたけれども、引き続きそういう形で進めていけばいいのではないのですか。区の公費も減らしているのに運営できているわけですから。","respondent":"池田国保医療年金課長","answer":"平成３０年度は多少減ったところですけれども、実際に令和に入った段階では、医療費総額というのは増えているところです。保険料の現在以上の収納の確保ということで、延滞金の運用を始めするということで、ご理解いただければと思います。","id":"exchange-146"},{"speaker":"石田（ち）委員","kind":"質問","question":"今までよりも国保財政が厳しくなったということだと思うのですけれども、だったら払える国保料にしていったらいいではないですか。これだけ９２％のトップの収納率を上げてきたわけですから、国保財政が厳しくなったというのは、私は理由にならないと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"渡部委員","kind":"質問","question":"４点目、最後ですけれど、地域偏差があるではないですか。わかれば説明を求めました。","respondent":"佐藤保育課長","answer":"今後分析してまいります。３、４、５歳に関しては一定程度出ているところです。","id":"exchange-148"},{"speaker":"渡部委員","kind":"質問・要望","question":"どこかに行けるような状態をつくっていただければというのは要望しておきますし、状況を見極めながら、それぞれよろしくお願いいたします。２３３ページ、どういうお話かというのもあらあら伺ったので、どういうことをやるかというのは承知しているつもりです。","respondent":"廣田子ども育成課長","answer":"今回は荏原地区の公園でモデル実施をして、荏原地域の方々の反応であるとか、どんなお子さんが来るのか様子を見るということを思っています。荏原地区の子どもたちにもプレイパークと近いことを体験させてあげたいと考えていますので、現時点では思っているところです。","id":"exchange-149"},{"speaker":"渡部委員","kind":"質問","question":"後で館長などに聞いていくと、彼らに報酬というのでしょうか、何か出ているのだよねと言ったら、何言ってるのですか、無償ですよという話です。何か育てる方法はないのかなと、無償と聞いたときにつくづく思ったのですけれど、どうか尋ねました。","respondent":"廣田子ども育成課長","answer":"できれば１８歳以上の場所については、何か事情がある子だけではなく、ともに何かできるような場所にできていけばいいかなと思います。そんな壮大な建物ができるかどうか、すぐにはできないと思うのですが、今後の課題として取り組んでいきたいと考えています。","id":"exchange-150"},{"speaker":"渡部委員","kind":"質問・要望","question":"面倒を見てあげようと思える子たちであるわけですから、ぜひ研究をして進めていただきたいと思って、これも要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"本多委員","kind":"質問・要望","question":"２４７ページ、区立保育園の改築について、そして民営化について伺います。代替地は、大規模改修に限らず必要になるケースもありますけれども、その代替地を選んでいく進め方について教えてほしいと求めました。","respondent":"吉田保育施設調整担当課長","answer":"そこに３階建てぐらいの建物が建つのですけども、それだけの土地を確保するというのはなかなか難しいところがあります。この辺は関係所管と連携をとりながら、今後も進めていきたいと思っているとこです。","id":"exchange-152"},{"speaker":"本多委員","kind":"質問・要望","question":"民営化について伺います。この予算のプレス発表資料のところで、民営化調査検討経費２５３万円について、内容を説明するよう求めました。","respondent":"吉田保育施設調整担当課長","answer":"その業者と今度４月から、令和３年４月の三ツ木保育園の公設民営化に向けて、その際の支援を行っていただきます。コンサルの持っているノウハウをいただきながら、無理なく、無駄がないような形で、利用者の理解を得られるよう、移行していくところです。","id":"exchange-153"},{"speaker":"本多委員","kind":"質問","question":"民営化のメリットにつきまして、サービス向上というと本当に広くいろいろ入ります。それと既存の公設民営の検証を広める点について、既存の公設民営のサービスや運営についてですけども、そういったところについてはいかがか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"区の保育園だと一律な方法になりますけれども、民間事業者が持つノウハウとか、サービス向上とかが見込まれるものと考えております。もともとが業務委託という形で、その分の枠を確保したということでございまして、まだこちらにつきましては検証等が済んでいないところです。","id":"exchange-154"},{"speaker":"本多委員","kind":"質問・要望","question":"令和３年度から始まる内容については、広く状況をお知らせする必要があるかと思いますので、質問しました。ぜひ、そうしてほしいと求めましたが、どのようなイメージか説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"実際にそこの園の利用者等の声を聞きながら進めていくとともに、第三者評価においても高い評価となることを目指して、頑張っていこうと思います。","id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"伺ったところ２月は２６名ということ、１日に１名いらっしゃるかどうかというところで、利用の状況が大変少ない。そして改善、これはまさか利用の抑制ということではないと思うのですが、支援サービス拡充、そして受け入れ体制の整備のお考えはいかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"ただ、その後ちょっと難しいということで福祉的な支援が必要になったときの受け皿として、就労Ｂのほうはニーズがあるものと考えております。","id":"exchange-156"},{"speaker":"高橋（し）委員","kind":"質問","question":"平成３４年９月３０日まで待たずに、この施設の指定管理の対象を再検討するべきではないかと思います。例のひろまち保育園の、あれは委託ですけれども途中で解約したこともありますが、その点についてはいかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"次の体制につきましては、現在検討しています。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"保育士はかなり忙しいようですが、人数は足りているのでしょうか。そして、マスクと消毒液は当面、十分あるのか尋ねました。","respondent":"佐藤保育課長、吉田保育施設調整担当課長","answer":"１点目ですけれども、フリーとか、副園長等を配置しております。非常勤が７００人と、計１,５００人も公立保育園のほうには配置しておりますので、十分対応できているです。 不足するという園から連絡がございましたので、それにつきましてはまた２月下旬に必要な数を配布したところです。今後も、確保ができ次第、配布していく次第です。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"民間の状況ももちろん把握されていると思うのですが、その辺の人材等に関して、どうなのでしょうか。説明を求めました。","respondent":"大澤保育支援課長","answer":"時間を短縮して利用されている方がいるということで、今、保育士の人数としては問題なく運営ができております。マスクや消毒液等についても、現時点で不足しているという園の情報は入ってきておりません。","id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"保育所などで職員や園児が感染した場合、臨時休園するようになっていますが、区内の全ての保育園が同様なのでしょうか。そして、実際に休園しなければいけない場合には、何日ぐらい休園するのか、説明を求めました。","respondent":"佐藤保育課長","answer":"基本的に２週間以上を考えております。東京都や保健所と状況を確認して、休園するか、しないかを判断するです。","id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"ですから、勤めている方も会社を辞めざるを得ないという状況があります。最大限のウイルス感染防止対策を、私はこの品川区でしているのかと思うのですが、その辺について対応策を説明するよう求めました。","respondent":"佐藤保育課長","answer":"新型コロナウイルス感染症に関する対応策ですが、今のところそれが徹底しているので、感染者が出ていないで通常どおり運営できているものだと考えております。","id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"そういうところの対応というのはどうされているのですか。本当に条件的には密閉空間で濃厚接触をするわけですから、それにしては手洗い、うがいだけで済むのか尋ねました。","respondent":"佐藤保育課長","answer":"下旬に２回、検温も含めて徹底をお願いしますといった対応をしておりますので、各園で滞りなくやっていると把握をしております。園内の保健衛生の管理はきちんとやるようにということで取り組んでおりますので、できることを精一杯やっていきたいと考えております。","id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"お子さんの安全というのを、それだけできっちり守れると言い切れるのですか。何か足りないのではないか尋ねました。","respondent":"佐藤保育課長","answer":"検温の徹底についてのご質問だと思いますけれども、各家庭で検温していただいている場合もあります。検温をしておりまして、３７度５分を超えた場合は保護者にご連絡して、お迎えに来ていただくという運用を徹底しています。","id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"人員不足の影響もあるようですが、訪問介護を含めて、品川区内の区立や民間の介護施設ではどうなのでしょうか。そして、職員不足の施設やサービスはあるのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"施設につきましては、面会の中止等々対応しておりまして、一定程度感染防止に努めているところです。それ以降につきましては少しずつ不足が発生するという情報もありますので、これは庁内会議等で情報提供して、対応を検討している最中です。","id":"exchange-164"},{"speaker":"須貝委員","kind":"質問","question":"それは一体どうするのですか。ぜひそういうところの対応をしっかりやっていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう要望にも応えられるのか、伺いたいと思います。特別支援学校も含めて、小中高に通学する医療的ケア児の人数は、それぞれ何人なのかについても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"福祉の支援体制が整うまでの間、特別支援学校でお預かりするというような体制をとっていただきまして、教育のほうと連携いたしまして対応しています。３点目ですけれども、通常の利用日数が少ない方でも、必要な方については支給日数を増やして、この間対応を行っております。","id":"exchange-166"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"拡大の方向でぜひ取り組んでいただきたいと思うのですが、いかがでしょうか。ぜひこの場合、住民税非課税世帯は無料ということにしていただきたいと思うのですけれど、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"内部障害の方も１級から３級という形で対象となっておりますので、ならないかというのが、対象としては重度の方も対象になっています。それから、次に利用料の件についてですが、委員ご指摘のとおり３００円の通信料はかかってくるものです。","id":"exchange-167"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２,０００人ちょっとだと思うのですけど、そのうち高次脳障害で手帳をとられている方の人数がわかれば教えてほしいと求めました。高次脳機能障害をご存じですか、これは委員長にも断っているのですけれど、これがどのように活用されているかということについても説明を求めました。","respondent":"松山障害者福祉課長","answer":"先ほどの緊急通報システムの件につきましては、継続して、また今後も検討してまいります。障害者差別解消法のハンドブックにも、支援方法について記載させていただきましたので、今後とも周知を図ってまいりたいと考えております。","id":"exchange-168"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区でもぜひ高次脳機能障害者支援センターをつくって、支援の充実をしていただきたいと思うのですが、いかがでしょうか。高次脳機能障害専門のデイサービスや自立訓練、就労Ｂについても必要ではないかと思うのですが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"委員ご指摘の、目黒区の高次脳機能障害支援センターも承知しております。数の把握が非常に難しいということと、心身障害者福祉会館で行っている自立訓練の生活訓練の中で、高次脳機能障害の方をお受けしている状態です。","id":"exchange-169"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は、２１１ページの成年後見制度利用促進基本計画策定について伺いたいと思います。そうしたネットワークを運営していくための中核となる、中核機関の設置等が求められておりますけれど、これについての考え方を示すよう求めました。","respondent":"大串福祉計画課長","answer":"地域連携ネットワーク、専門職ですとか、当該の被後見人の権利擁護をどう図っていくかということを検討する機関であり。これまでの成年後見センターの取り組み、中核機関という形で位置づけていければと考えていますし、検討していきたいと考えているところです。","id":"exchange-170"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そうした中で、私は市民後見の活動をされている市民後見人の方からお話を伺う機会がありまして、今現在は社協が助成をしたりしているわけです。あわせてご見解をお願いいたします。","respondent":"大串福祉計画課長","answer":"今回の法律の中で求められている地域連携ネットワーク、こちらについては社協と十分話し合いをしながら進めていければと考えているところです。","id":"exchange-171"},{"speaker":"たけうち委員","kind":"質問・要望","question":"午前中もありました不正防止は当然のこととして、今の状況に甘んじることなく、この計画を通してさらに促進を図ってほしいと求めました。要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-172"},{"speaker":"大沢委員","kind":"質問","question":"２１９ページ、外出習慣化事業と、それから派生した社会保障について聞きます。外出習慣化事業ですけれども、高齢の方がひきこもりがちだということを防止するために、この事業が行われているのですけれど、現状を説明するよう求めました。","respondent":"宮尾高齢者地域支援課長","answer":"さらに今年度からは、歯科衛生士等による口腔機能向上プログラム、これを各期１回ずつ実施させていただいているところです。ちなみにこちらの事業は、現在４会場にて実施しています。","id":"exchange-173"},{"speaker":"大沢委員","kind":"質問","question":"これは今、大体、引きこもりがちの方はどれぐらいいらっしゃるのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"こちらは各会場とも定員が９名ということで、掛ける４会場で３６人。各会場とも２期、実施させていただいているという状況です。","id":"exchange-174"},{"speaker":"大沢委員","kind":"質問","question":"これに出てくる方は比較的、引きこもるということに対して否定的であって、積極的に自分自身の改善をしようという元気な高齢者だと思います。どのように現状を捉えていらっしゃるのか、想像していらっしゃるのか、説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"７５歳以上のご高齢の方で、そこからいろいろなサービスにつなげる、その一助となればということでやらせていただいているところです。","id":"exchange-175"},{"speaker":"大沢委員","kind":"質問","question":"デリケートな年代の方たちですから、２０２５年、この事業あるいは事業に対する見立てというか見通しをどのようにやっていこうと思われていらっしゃいますか。","respondent":"宮尾高齢者地域支援課長","answer":"確かに委員おっしゃるとおり、これから当面高齢化は進むというふうに、我々は想定、認識をしております。その方に担い手となってその事業のお手伝いをしていただきたい、こういった貴重なお力としても、我々は期待させていただいているところもあります。","id":"exchange-176"},{"speaker":"大沢委員","kind":"質問","question":"どう見ても今のところ、ご存じのようにこういう世相でありまして、それが十分に機能していないような感じがします。２０２５年についてはそこの部分が機能しない、あるいは機能不全、どのようにお考えか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"確かに心配すべきというか憂慮すべき点はありますけれども、我々としてはそこを見据えて、そうならないように、いろいろな手立てを打って介護予防等含めて、充実を図ってまいりたいと考えています。","id":"exchange-177"},{"speaker":"大沢委員","kind":"意見","question":"あらゆる年代のところで社会資源を活用しながら、この事業が行えれば非常に…、言っていることが自分でもわからなくなってきました。ちょっと直しますけれども…、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-178"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は５４０ページ、地域包括ケアシステムのことについて伺います。これは受け皿づくりが求められていて、出口戦略が必要だということであります。","respondent":"大串福祉計画課長","answer":"なかなかその辺の病院の運営、あるいは開設といったところで、区が関与できる領域はなかなか難しいと考えています。まさに居住支援協議会、これから始まるところですので、多角的な議論の中でそういったところも触れていければと思っているところです。","id":"exchange-179"},{"speaker":"石田（秀）委員","kind":"意見","question":"それを品川区だけ、私もかかりつけ医は港区だけれども、もちろんそういう人がたくさんいるわけです。逆にコストも下がってくると思っているので、そこら辺のところをぜひお願いだけして、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-180"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/273075?Template=document&Id=1114#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":127412,"voices":410}},{"id":"r02-20200310-3","meetingId":"r02-c-budget","date":"2020年3月10日","dateIso":"2020-03-10","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を163件整理しています。","topics":[{"id":"topic-01","title":"行う委員の質問を先行して行い、該当の質問が終わり次第、品川区保健所長をはじめとした関係理事者には退席していただくこととしましたので、ご了承願います。 それでは…","agenda":"行う委員の質問を先行して行い、該当の質問が終わり次第、品川区保健所長をはじめとした関係理事者には退席していただくこととしましたので、ご了承願います。 それでは…","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"２８５ページ、２９３ページ、中小企業経営支援事業費についてお伺いいたします。平成２８年の指針改定に伴いまして、約３０％近く減らした予算が計上されていますが、今年度の受診率の減少が目立ったということなのか尋ねました。","respondent":"高山健康課長","answer":"胃がん検診についてのお尋ねです。それから胃がんリスク検診という３つで検診を用意しているところなのですが、直接、こちらを重点的に実施するものです。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問・要望","question":"前回の決算特別委員会では、課長答弁では、時期尚早か実行すべきか慎重に判断されるという答弁をいただきました。歯科医師会への取り組みも含めて教えてほしいと求めました。","respondent":"高山健康課長","answer":"来年度におきましては、その事業の実施にかかわります研修経費の助成という形で支援をさせていただきたいというふうに考えているところです。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問","question":"競技場周辺で行っているボランティアの清掃活動を行政が支援することはできないものなのでしょうか。ぜひ「しな助」としての清掃活動をご支援ほしいと求めましたが、検討されていますか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"オリンピック・パラリンピック準備課とどういった形で連携がとれるかというところは、今後、検討したいというふうに思ってあります。ふれあい班を期間中は特に強化して清掃、周辺環境の美化に努めてまいりたいと考えております。","id":"exchange-003"},{"speaker":"小芝委員","kind":"質問","question":"大井町のとある飲食店で話を聞けば、前年度比４割減との話も伺っております。急な事案に対しての予算であると思うのですが、こちらの財源は中小企業資金融資あっせんの６億９,２４６万７,０００円なのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"財源につきましては、委員お示しの中小企業資金融資あっせんの予算の中でです。","id":"exchange-004"},{"speaker":"小芝委員","kind":"質問・要望","question":"ちなみに、今日に至るまでの相談件数がもしわかれば教えていただきたいのと、あと、相談に来た事業者の中でどういった業種が多いのかなど、その特徴も教えていただけますか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"今回の新型コロナウイルス感染症対策という観点では、もう１００を超える相談を受けております。業種につきましては、委員お示しのございました飲食業ですとか、宿泊関係、それからタクシーの自営の方などが多いかということが１つの特徴です。","id":"exchange-005"},{"speaker":"小芝委員","kind":"質問・要望","question":"今後とも、国難ともいうべき新型コロナウイルス感染症の影響を極力最小限に抑え乗り切ってもらえるよう、区としても積極的な支援をお願いいたします。こちらは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"せお委員","kind":"質問・要望","question":"２８７ページ、２７１ページ、受動喫煙防止対策費についてお聞きします。できる範囲でやっていただきたいとは思うのですが、先週からほかの委員からも質問がありますので、簡単にで結構です。","respondent":"仁平品川保健センター所長","answer":"実際に健診中ですけれども、ふだんより換気に努めているところです。こちらは簡略化、資料のお渡しなど簡略化して、健診の総時間の短縮化に努めているようなところです。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問","question":"掲示物や案内表示などの見直しや清掃は、時期などを決めて定期的にやっていたりしますでしょうか。そちら、何かあれば説明を求めました。","respondent":"仁平品川保健センター所長","answer":"区では全庁的にイメージアップ運動をしていますので、１２月には一斉に館内を点検している、そういう状況です。その辺は適宜交換する等して、今後とも見やすい掲示物、案内に努めてまいりたいと考えております。","id":"exchange-008"},{"speaker":"せお委員","kind":"質問","question":"現状、健診において発達障害が疑われる事例において、どのような対応がなされていて、紹介機関は決まっていたりするのでしょうか。説明を求めました。","respondent":"仁平品川保健センター所長","answer":"そういう機をとらまえまして、早期に発達上の課題のあるお子さん、課題があるのかどうかの発見に努めているところです。児童発達相談支援センターのほうへお話といいますか、保護者へそういう療育といいますか、次の機関のほうへつなげるような勧奨をしています。","id":"exchange-009"},{"speaker":"せお委員","kind":"質問","question":"保護者の考え方だったり、保健センターなどにおいて、発達障害の正しい知識を得られる講演会などを行うといった機会はありますでしょうか。説明を求めました。","respondent":"仁平品川保健センター所長","answer":"現在、保健センターにおきましては、発達障害関係の講演会は、企画も、実施したこともございません。そういう傾向のお子さんをつかまえていく、次の機関につないでいくというような、そういう役目を負っているかと思います。","id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"そこで、人工芝の対策も取り組んでいただきたいところですが、人工芝については学校での整備が多かったりしますので、教育費のほうで質問します。プラスチック製品をなくす、減らすということについて、品川区で取り組まれていることがありましたら、説明を求めました。","respondent":"小林環境課長","answer":"減らしていく取り組みとしましては、各種イベント等で使用します使い捨て容器類をプラスチック以外のものに変更することを進めていくところです。別の商品に変えていく、そういった取り組みを来年度から進めていきたいというふうに考えているところです。","id":"exchange-011"},{"speaker":"せお委員","kind":"意見","question":"１日中、中身が足りなくなってしまったり、買い足そうとするとペットボトルを買ってしまうということになります。まずは庁舎などにおいて、ペットボトルを売っている自販機を減らしていく方向で取り組まれてはいかがかと思いますが、見解を説明するよう求めました。","respondent":"小林環境課長","answer":"その中には、それらはその場での水分補給ということを目的に設置されているであろうかと思っているところです。職員に対するマイボトルの積極的活用の周知について、区として可能な取り組みは引き続き研究してまいりたいというふうに考えているところです。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"次に、プラスチックごみを再生利用するということですが、予算書にリサイクル活動支援事業とありますが、これはどのような事業でしょうか。説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"こちらは、集団回収事業といいまして、集団回収団体の活動が活性化するような支援をしています。リサイクルショップの運営というところで、区がリサイクルショップの運営に対して補助している、このような事業です。","id":"exchange-013"},{"speaker":"せお委員","kind":"意見","question":"品川区をはじめ２３区などがそのような宣言をしてもいいかとは思っています。このワンウェイプラスチック削減のほかに、今後、検討している取り組みなどがありましたら、お知らせくださいとの意見を述べました。","respondent":"工藤品川区清掃事務所長","answer":"どうしても出るものはしっかりとリサイクルするです。買ったものは徹底的に使う、また再利用等を行う、こういったところを重点的に取り組んでまいりたいと考えています。","id":"exchange-014"},{"speaker":"せお委員","kind":"意見","question":"日本では、受動喫煙による年間の死亡者数は推定で１万５,０００人と言われております。４月１日から改正健康増進法と東京都受動喫煙防止条例が全面施行されるにあたって、事業内容の説明とあわせて説明を求めました。","respondent":"高山健康課長","answer":"これまでの取り組みとしましては、さまざまな制度に関する説明でありますとか、一部苦情対応などもさせていただいているところです。そして４月からの全面施行に伴いまして、命令などの取り締まりが始まりますので、そちらの対応をしてまいります。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問","question":"副流煙は１５分から２０分ぐらい体内にとどまって、その時間、周囲に影響を及ぼすというデータもあります。心筋梗塞や脳卒中などの発症リスクも高まりますが、区として目標をもって受動喫煙対策に取り組むべきと考えますが、その点はいかがか尋ねました。","respondent":"高山健康課長","answer":"区では、健康増進計画ということで、しながわ健康プラン２１を、今年度、中間評価見直しということで改定いたします。そして、その中でたばこ対策ということを重点的な目標と定めまして、数値目標を立てて取り組んでまいります。","id":"exchange-016"},{"speaker":"つる委員","kind":"提案","question":"２０１８年１月の文教委員会で、そういうような提案もさせていただいていることから、この法律の改正は非常に喜んでいるところです。今回の法律改正に応じて、１年と期間が延びたことから、品川区の施策においてもさまざま見直しを図っていくことが求められるわけですとの意見を述べました。","respondent":"仁平品川保健センター所長","answer":"母子保健法一部改正に伴う対応と今後の区の施策の考え方、それと対象の範囲という形になるかと思います。東京都の「とうきょうママパパ応援事業」等の新しい補助メニュー等が入ってまいりますので、さらに施策の充実に努めていきたいと考えております。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"しっかりとそれを確認いただいて、そうした詳細をしっかりと確認いただいて、品川区の各施策に生かしていただきたいというふうに思っております。これについては歳入でも確認させていただいて、移動経費補助事業、品川区民のお母さんやお子さんをしっかりと守っていくことになると思ってあります。","respondent":"仁平品川保健センター所長","answer":"本来ですと、３月ぐらいに東京都の補助金説明会があるのですけれども、まだ詳細が入ってきていないところです。補助要綱とかを東京都のほうでつくられると思いますので、そちらの情報をしっかり把握して、区の施策に展開の仕方を考えていきたいと思ってあります。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"次に、こころの健康づくり事業に関連して、摂食障害について伺っていきたいと思います。品川区は、まず、この摂食障害に対する区の取り組みについて示すよう求めました。","respondent":"榎本荏原保健センター所長","answer":"摂食障害についての取り組みですが、摂食障害につきましては、神経性の痩せ症とか過食症などの症状があらわれる病気です。その上で、専門の医療機関におつなぎして、その方に応じた治療に結びつけているところです。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"過日、国会でも公明党の議員からの質問に対して、厚生労働副大臣からも、まず啓発活動が大変重要であるという認識が示されたところであります。国としてもそうした啓発活動との連携が今模索されている中ですが、区として、このあたりについての取り組みの考え方を示すよう求めました。","respondent":"榎本荏原保健センター所長","answer":"年に１回、広報におきましても大きな紙面をいただきまして、気軽にご相談できるような周知・啓発活動を行っております。今後はこの摂食障害についても、より早い段階でご相談や治療ができたほうがいいことも多いと思いますので、一層力を入れていきたいと思います。","id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひこのマゼンタリボン運動との連携も含めて、ご検討、推進いただきたいと考えております。小児がんなどの治療で免疫を失った子どもの定期予防接種の再接種の費用助成について、何度も確認をしていますが、現状を説明するよう求めました。","respondent":"鷹箸保健予防課長","answer":"時間をかけてまいりましたけれども、今、区として取り組めるような形でしっかり進めております。年度末までにはしっかり対応が可能になるように、今、進めております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"２０cmぐらいでしょうか。伺いたいのですけれども、条例改正後に開業したこのような常駐者がいない、フロントがない旅館・ホテルは何件ぐらいなのか説明を求めました。","respondent":"鈴木生活衛生課長","answer":"法改正後、申請のあった旅館についてのお尋ねですが、旅館については、一昨年の法改正後増えた件数について、１０数件というふうに記憶をしております。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"住民の方の不安も伺いましたので、設備からいって、住民の不安も当然だなと思いました。伺いますけれども、双方が納得するまで許可を待つべきだと思うのですけれども、いかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"説明会を開いたり、個別の対応をするなりということで、近隣とのトラブルを解消するように努めるということで指導をさせていただいているところです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、その話し合いをある程度、双方が納得するまできちんと話し合ってもらうということに品川区はある程度責任を持つべきだと思うのです。双方が納得するまで許可は待つべきだと思いますが、いかがでしょうかと伺ったので、答えるよう求めました。","respondent":"鈴木生活衛生課長","answer":"その要件をしっかりと満たしているかというところをチェックしておりまして、住民の方との話し合いについては、指導までしか権限がないです。全員が何も意見、要望がなくなるということはありませんので、法的にもそこまで許可を出さないというのは困難なことだと考えております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"許可を少し待ってもらうということはできるのではないですか。いかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"先ほど申し上げましたように、法令等の定めに従って手続をして、保健所としては主に衛生面、環境面の確認といった法に定めたものを行っておりますが、それを必要以上に住民の方の合意がないということで引き延ばすということは、法的にはできないというふうに考えております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、区はなぜ法の規定を超えて必要な規制を行う考えがないのか伺います。住民の不安に寄り添った一定の規制をかける条例改正は必要だと思うのですけれども、いかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"委員のご指摘にもありましたように、法の趣旨、またその規制に合わせた条例での規制、対応ということで、区は条例改正をしたところです。そういうようなことを総合的に勘案しまして、品川区においては法の規制を上回る規制は困難だというふうに判断したところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、私は、宿泊者にとっても地域にとっても、必要な規制は大事だと思います。今回、このケースに適用されるものはないのか伺いたいと思います。","respondent":"小林環境課長","answer":"道路上で発生していますと、それは所管する警察あるいは国が対応するです。都の環境確保条例に基づきまして、都市計画に基づく用途地域ごとに騒音の規制基準が定められてありますので、そういった中で指導していくです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"その結果、どう確認しているのか伺いたいと思います。今回の事例を踏まえて、何らかの区独自の騒音規制のルールの検討が必要ではないかと思うのですけれども、いかがか尋ねました。","respondent":"小林環境課長","answer":"本件ですが、過去に環境課のほうにそういった相談があって対応したことは把握しています。そういった相談があった場合につきましては、状況を確認した上で、また警察とも連携を図りながら情報共有を図っていきたいと考えております。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"これもＳＤＧｓの目標１３、そもそも環境保護がＳＤＧｓの１つの柱ですから、重要な価値を有するものだと考えております。収束のきざしが見えましたら、ぜひともにぎわい創出を直ちにやっていただきたいと考えておりますけれども、その点、いかがお考えか尋ねました。","respondent":"高山健康課長、小林環境課長、山崎商業・ものづくり課長","answer":"それから２点目のお尋ねとつながるところですが、これを半減するにあたっての施策という点で申しますと、主に３点考えられるかと思います。… あるいは企業の方が参加できるようなものもしっかりと検討してまいることで、今、検討を進めているところです。具体的には、太陽光発電システム… 秋に３億円ずつに加え、今年は２億円の増額を予定しておりまして、４億円ずつということで消費喚起ということで対応してまいりたいと考えています。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"そしてこの内容をどうやって区民に対して届けていくのか、その対応についてどのようにお考えになっているのかをお伺いいたします。この融資の要件は、前年度の５％影響を受けたとか、そうした要件は品川区の場合はないのか尋ねました。","respondent":"高山健康課長、小林環境課長、山崎商業・ものづくり課長","answer":"こちらは、１００ページを超える大変ボリュームのあるものですので、概要版をつくって、それを広く普及用として使いたいと考えています。それから… こういったところの活用を進めてまいりたいと思います。展示物につきましても、更新性が高いものを工夫してまいりたいと考えているところです。 前月比較で５％減です。ただ、５％では済まないというようなことで相談に来ていらっしゃるのが現実です。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"２９５ページ、５款１項１目産業経済費、経営変化対策資金について伺います。２７１ページの荏原複合施設大規模改修基本設計委託について伺います。","respondent":"榎本荏原保健センター所長","answer":"現在は、大規模改修に向けて候補地も含めて検討中で、候補地も幾つか挙げて検討しているという状況です。今、あと、事業を滞りなく継続して実施できるような体制がどのような形でできていくかということを最優先に考えて行っていきたいと考えております。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"次に、２７０ページ、母子手帳について伺います。改めて見解を伺います。","respondent":"高山健康課長","answer":"おおむね１００ページを限度に、それ以上厚くならないようにといった工夫の中で、内容については適宜見直しを図っているところです。内容においては遜色のないものと考えておりますので、今後、そうした新たなものの可能性については検討してまいりたいと考えております。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"運がよかった、条約を１人でも多くの人に知ってもらい、子どもには安心して生きられる権利があると知ってほしいと話しています。子どもの権利が実現するよう、改めて保護者の認識、理解が広がる工夫を、リーフレットでもいいので求めますが、いかがか尋ねました。","respondent":"高山健康課長","answer":"子どもの救急の関係でありますとか、あるいは妊娠にまつわるさまざまなご相談先を記載した名刺サイズのカードを入れることで提供しています。あまり過度な負担とならないような中で、内容については精査してまいりたいと考えております。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"除草剤、農薬の使用状況について伺います。特に子どもが手を触れるところでの除草剤、殺虫剤の使用状況について伺います。","respondent":"小林環境課長","answer":"特に学校においては児童が授業を受けている日あるいは時間等に実施しないなど散布等や時間等に対して十分配慮するように求められているところです。","id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"成分を確認して、環境に負荷のない安全性が高いものを選択してほしいと思いますし、使わない方向でお願いしたいと思います。２９７ページ、伴走型企業支援訪問事業、就労支援について伺います。","respondent":"山崎商業・ものづくり課長","answer":"障害者の方にとってみますと、短時間勤務等のマッチングなども含めてやらせていただいているような状況です。それから、ハローワークなどの関係機関とともに、そうした改善に向けてさまざまやらせていただいているような状況にはあります。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"企業が受け入れ態勢を整えられるような区の支援が必要だと考えますが、改めて見解を伺います。区の見解を伺います。","respondent":"山崎商業・ものづくり課長","answer":"障害者福祉の部門のほうで、障害者の自立のサポートのほうで、１つの自立の答えとして就業支援を行っているというようなこと。所管部門が連携しながら対応させていただいて、よりよい就業機会の拡大に結びつけるように、区としては奮闘させていただいているところです。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"必要書類がそろっていることが確認できたときに紹介状を即日発行とあるのですが、日数は、大体どのくらいになのでしょうか。基本は国がやるべきと考えていますが、国の制度ができるまでの緊急的支援策を区として既に検討されていたら、それもあわせて伺います。","respondent":"山崎商業・ものづくり課長","answer":"こうした事業所が全２万の事業所のうち８５％を占めておりますので、小規模事業者については、ほぼこちらの融資が対応できるというような状況です。区としましては、速やかな対応ですので、ここの間に時間を要して資金ショートなどという問題は起きてございません。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"２８５ページ、エコライフ普及事業について伺います。国産材を使用する施設となるのか、建築材としては無理でも内装や家具などに間伐材を使用していくのかなど、方向性を伺います。","respondent":"小林環境課長","answer":"方向性ですが、区では平成２７年にそういったような木材利用に関する方針を策定しておりまして、木材利用の推進を図ったところです。現在、学校をはじめとしまして、現在計画を進めております環境学習施設、児童相談所においても、その使用について進めているところです。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"今日は２７７ページのこころの健康づくり事業について伺います。昨年、ＷＨＯがゲーム障害を新しい国際疾病に認定しまして、この新分類は２０２２年から発効されるというふうに伺っております。","respondent":"間部大井保健センター所長","answer":"ゲーム障害の定義ですが、ゲームを過度に集中してやり過ぎることにより、社会生活や学校生活等に影響が出る、このような定義になってあります。","id":"exchange-039"},{"speaker":"松本委員","kind":"意見","question":"実際に診断されるためには、１２カ月以上その状態が続いているとか、なかなかハードルが高いところもあるのではないかというふうに思っております。","respondent":"間部大井保健センター所長","answer":"平成３０年度の精神保健に関係する相談件数につきましては、大井の３所のトータルですが、約１,１００件ほどあります。過去３年を見ても、大体１,０００から１,１００件ぐらいで推移しておりまして、かなりの数のご相談があるという形では認識しています。","id":"exchange-040"},{"speaker":"松本委員","kind":"意見","question":"なので、かなりわからない部分もあるのだろうというふうに思います。医学上、正式な依存症としての定義があるのかどうか、お願いいたしますとの意見を述べました。","respondent":"間部大井保健センター所長","answer":"一般的には、やめたくてもやめられず、濫用がとまらないというような定義があります。私もいろいろな現場での対応を見てみますと、ある方はアルコールにいったりという中で、そういった形で依存症については捉えている現状です。","id":"exchange-041"},{"speaker":"松本委員","kind":"確認","question":"一応確認なのですけれども、明確に国際的にこういうふうなものだったら、ネット依存症だ、スマホ依存症だという形で診断しなさいみたいな基準は特にないというふうに伺ってよろしいか尋ねました。","respondent":"間部大井保健センター所長","answer":"ＷＨＯの分類につきましても２０２２年１月から発効ということで、日本におきましても、ゲームの時間の制限にかかわってエビデンスかあるというような状況ではございません。","id":"exchange-042"},{"speaker":"松本委員","kind":"確認","question":"ゲームの時間のところもまたあとで触れたいところですけれども、ありがとうあります。対処法が確立しているわけではない、これも一応確認しておきたいのですけれども、ご答弁をお願いいたします。","respondent":"間部大井保健センター所長","answer":"現在のところ、いまだ確立はされてございません。","id":"exchange-043"},{"speaker":"松本委員","kind":"意見","question":"過去の議会の議事録を拝見いたしますと、品川区でも思春期講演会で久里浜医療センターの方を講師にお招きというふうな情報が出てきました。どのような講演会だったのか、こちらもお願いいたしますとの意見を述べました。","respondent":"間部大井保健センター所長","answer":"久里浜医療センターにつきましては、平成２３年度よりネット依存外来を国内で初めて始めたという専門的な医療機関です。平成３０年１２月に思春期講演会ということで、依存症のことだとか、そういった内容について触れたものです。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"そういった中で、それがよいのか悪いのかというところを含めてお話があったのでしょうか。お願いします。","respondent":"間部大井保健センター所長","answer":"私どもが開催しました思春期講演会で講師を務めていただいたのが久里浜の先生で、１つの考え方として、そういうゲームを取り上げるというか、時間に制限を設けるようなことも対策上は有効ではないかというお話があったところです。","id":"exchange-045"},{"speaker":"松本委員","kind":"質問","question":"ゲーム障害、あるいは依存症と言われているものの発症を防ぐためのゲーム時間の制限に科学的な根拠や有効性があると区としてはお考えでしょうか。お願いいたします。","respondent":"間部大井保健センター所長","answer":"私どもにつきましても、先ほど来ご紹介のありました政府の答弁と同様、現在のところ、エビデンスについては承知していないです。","id":"exchange-046"},{"speaker":"松本委員","kind":"意見","question":"確かに使い過ぎていろいろと問題が出ているというところはあります。そういったところから、これは区に限らず大切だと思いますので、そこはご留意いただければというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２０１８年の第３回定例会の一般質問で、我が会派として求め、いよいよその成果物が出てまいりました。このことを要望したいと思いますが、いかがか尋ねました。","respondent":"高山健康課長、小林環境課長","answer":"この間、１００ページに手が届くようなボリュームになってしまったということもありますので、やはり概要版の作成を予定しています。やはりこれはしながわ健康プラン２１のある種の流れを汲むものですので… 素材感につきましても、環境に配慮した素材のエコバッグなどを含めて検討をしてまいりたいというふうに考えております。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"確認","question":"月に１回、特に就労されている方、仕事をされている方向けの相談窓口を開いていただく委託をするということを伺いました。そんなところあったのですか」などとこれから言われるようであれば、そこら辺の準備について、周知の徹底をぜひお願いしたい。","respondent":"高山健康課長","answer":"この事業は４月からということではございませんが、しっかりと秋から始まりますこの事業に関する周知の期間に充てたいと考えております。のがん相談支援センターでの周知はもちろんのことなのですが、周知を努めた上で、秋の事業開始を迎えたいと考えております。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"確認","question":"職場においても見られるでしょうし、通勤・退勤の最中でも見られるから、ＳＮＳでの発信もお願いしたいと思いますが、いかがでしょうかというところ。これも同じように月１回やっていますけれども、どれぐらいの方の利用数があるのか、そこについても確認したいと求めました。","respondent":"高山健康課長","answer":"こうした若い層に向けたより効果的な周知方法としてＳＮＳの活用なども図ってまいりたいと考えております。ナイトマギーズに限定ということになるのですけれども、おおむね年間で１１０名ほどの利用というふうな数字で伺っているところです。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私たちが視察しに行った年から、江東区はたしか委託でそれを始めたと思っています。繰り返しになりますが、そこのところをしっかりと知らしめていただきたいということをお願いいたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"私からは、２７１ページ、受動喫煙防止対策費について伺います。世界での日本の状況と区内の状況を区はどのように認識しているのか伺います。","respondent":"高山健康課長","answer":"区といたしましても、都のこうした施策、そして国の動きをしっかりと捉えて、区内における受動喫煙対策について進めてまいります。具体的には、そちらを重点的に取り組むことによって、そうした受動喫煙の害に遭ったという人の割合を減らしてまいりたいと考えております。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"乳幼児突然死症候群で４.７倍としており、毎年１万５,０００人で、交通事故死の４倍になると発表しています。こうしたたばこによる健康被害の周知徹底が必要だと思いますが、いかがか尋ねました。","respondent":"高山健康課長","answer":"品川区がん対策推進計画におきましても、たばこががんの要素として大変危険な因子であるということを、コラムなどを交えまして説明をしています。具体的には、確実ないしはその可能性があるといったリスクの因子として挙げられている点につきましても、計画の中で対応しています。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問","question":"具体的にどのように周知を進めていくのか、先ほど、具体的にどうしていくのかというところで伺いたいと思います。はたばこの健康被害についてのパンフレット作成など、周知を徹底していくべきだと思いますけれども、いかがか尋ねました。","respondent":"高山健康課長","answer":"品川区がん対策推進計画を進めていく中で、がんの予防に資するさまざまな生活習慣などをわかりやすい形で周知をしてまいりたいと考えております。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"パンフレットの作成ということでお聞きしましたので、見通しということになるかもしれませんが、伺いたいと思います。この加熱式たばこの害についての区の認識と、この害についても周知をすべきだと思いますが、いかがか尋ねました。","respondent":"高山健康課長","answer":"喫煙に対する知識を高めるという中で、目標値を定めているところですので、こうした健康増進計画の推進も１つ後押しになるのではないかと思います。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ力強くやってほしいと求めましたし、子どもたちにも、ぜひそういったたばこの害について教育をしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目は、地域医療連携、感染症対策についてをお伺いいたします。状況の進展に応じて講じていくべき施策、地域医療体制の平準化のあり方などをご検討いただきたいのですが、区のご見解を伺います。","respondent":"鷹箸保健予防課長、榎本荏原保健センター所長","answer":"３月１日に国から出された方針で、考え得る対策、どのように医療体制を充実していくかということで国から方針が示されているところです。… 軽度知的障害や境界知能のお子さんや若者の抱えている課題と相談支援の状況ということですけれども、より一層、社会の中で適応しにくい状況。","id":"exchange-057"},{"speaker":"横山委員","kind":"質問","question":"４点目、中小企業活性化推進事業費についてお伺いします。政治家、そういう考え方なのですけれども、このようなスキームを五反田バレーなどでも取り入れてはいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"昨年１０月にリニューアルいたしました武蔵小山創業支援センターのコワーキングスペースの利用者などの声としましては、具体的には、あと。２点目の五反田バレーのご提案の中身につきましては、ご提案の趣旨については研究してまいりたいというふうに思っているところです。","id":"exchange-058"},{"speaker":"横山委員","kind":"質問・要望","question":"今まさに消費者、テレワークなどのＩＴ支援や、そのスキルを向上するための研修等の支援を素早く加速していただきたいというふうに思っております。こちらは要望を伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"２８１ページ、２９３ページ、この３点をお伺いいたします。国や都の受診率と比べて、区の受診率の現状をどのように捉えていますか尋ねました。","respondent":"高山健康課長","answer":"直近の数値、平成３０年度の数値で申しますと２５.４％ということで、いずれも２０％を超える受診率ということになっております。しかしながら、国が目標とします５０％という高い目標には、品川区も含めてなかなか到達が難しい状況にあります。","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問","question":"次に、この受診率向上への取り組みについてお伺いしたいと思います。課題とか、さらに今後の取り組みをどのように考えていくのか、受診率向上への取り組みの現状と今後の方向性を説明するよう求めました。","respondent":"高山健康課長","answer":"２年に１回の受診機会ではありますが、ご自身の健康を見直す契機として、この通知を役立てているところです。図書館においても、乳がん、子宮がんなどの女性のがんの実態などについての展示コーナーを設けまして啓発をしたといったところが直近の動きです。","id":"exchange-061"},{"speaker":"こんの委員","kind":"提案","question":"女医による検診の提案など、残念ながら、いまだそれは取り入れられていない状況であります。こうした同日１カ所の医療機関でできる、こうした体制を増やすことも必要ではないかと思いますが、ご見解を説明するよう求めました。","respondent":"高山健康課長","answer":"委員ご紹介のとおり、現在、旗の台の検診センターと牧田総合病院の検診クリニックの２カ所というふうに私どもも認識しています。今後もそうした加盟の医療機関の中で手を挙げていただけるよう、私どもとしても環境の整備に努めてまいりたいと考えております。","id":"exchange-062"},{"speaker":"こんの委員","kind":"質問","question":"次の質問にまいります。利用できる零細企業はどういう要件なのか、日数などを、簡潔に説明するよう求めました。","respondent":"山崎商業・ものづくり課長","answer":"相談をいたしまして、銀行に融資を実施していただくことがありますので、紹介状の発行を基本的には即時に行います。融資の額自体は５００万円ということで、これまでのことを考えまして、そのようなリレーを今は考えているところです。","id":"exchange-063"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこで、実際に緊急資金を活用したい場合の相談対応についてお伺いしたいのですが、細かい案件で恐縮ですが、お聞きいたします。こうした零細企業もこの緊急事態を乗り切るためにご相談に乗っていただきたい、こういう思いで質問するのですが、お考えを説明するよう求めました。","respondent":"山崎商業・ものづくり課長","answer":"区としましても、あるいは、いろいろな催し物がキャンセルによって影響を受けているというような特徴があるかと考えております。まずは相談でしっかりご誘導したり、融資あっ旋などをしっかり紹介をする所存ということで臨んでいるところです。","id":"exchange-064"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ大事な観点の啓発の冊子ですので、より一層、読んで、見て、行動に移れる、そうしたところまでの踏み込んだ啓発のものにしていただきたい。ＳＤＧｓの１７項目の中でも６項目が環境にあたる項目でもあると思いますので、取り組みやすい環境対策をお願いして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私は、成人歯科健診は１５歳からの毎年の実施を求めてきましたけれども。そうした方が歯科治療につながっているのかどうかというところまで把握はされているのでしょうかということを伺いたいと思います。","respondent":"高山健康課長","answer":"平成２９年度に、委員ご紹介のとおり、二十歳まで年齢を引き下げまして、二十歳から７０歳までの５歳刻みで、今、事業を実施しています。これが１０％を超えていけば、さらにいいということになってまいりますが、年齢拡大とともに推移を見守ってまいりたいと考えております。","id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"受診率が９％台ですので、まだまだ多くの方が自分の歯の状況をどうなっているか知らなかったり、わからない状況にいるのではないかと思います。そのかむ力、咀嚼力についての区の考えというか、認識をお聞かせほしいと求めました。","respondent":"高山健康課長","answer":"咀嚼力の低下の区の認識という点です。区で実施しております８０２０運動でありますとか、９０１６運動であるとか、それが何よりも健康長寿を支える上では大切なことだと思います。","id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"質問","question":"その歯周病にどういうふうにかかっていくか、その歯周病がどう歯が抜けるところまで及ぼすかということまで、すごくわかりやすいのではないかと。歯石をとろうかな、そういうところまで知らせていただけないかと思うのですけれども、いかがか尋ねました。","respondent":"高山健康課長","answer":"しながわ健康プラン２１の中における歯周病の関係をより詳しくの解説があったほうがいいのではないかというご提案だと思います。そうした点につきましては、この計画の内容にとらわれずに、さまざまな場面を通じて啓発してまいりたいと考えております。","id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"医師会の先生方がこの２つの年齢だけでいいと言うわけはないだろうと思って医師会の先生方に確認しましたところ、ないよりは２つの年齢のほうが。そして今年度もということで、やっぱり年齢拡大をしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"高山健康課長","answer":"事業をしていきながら内容について検討していく中で、あるいは結果なども見ながらということで、現在進めているところです。年齢拡大につきましては、とりあえず今年が終わり受診率などが出てきますので、そうした精密検査などの状況などを見ながら検討してまいります。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ拡大していただきたいですし、医師会の先生方もそうおっしゃっていますので、ぜひお願いします。体制強化、そういった職員拡大をしていくべきなのではないかと思うのですけれども、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"私の課で感染症に対応している保健師は４人ですけれども、今、福祉のほうにいる保健師なども含めて全庁的にみんなで対応にあたっているところです。何とか潰れないよう区民の方に影響がない形で、いい形で感染症対応は進めていきたいと考えております。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当にご苦労はあるだろうと思っていますし、帰りが遅くなるということもお聞きしています。そういう中でやっぱり体制強化、これからさらに対応が必要だと、戦いが必要だとまで言われていますので、ぜひ保健師の増をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"提案","question":"そういったことを指定管理者に提案するつもりはないでしょうか。この点についていかがか尋ねました。","respondent":"高山健康課長","answer":"必ずしも機械的に２割ということではないのですけれども、双方が折り合う話として、この割合がこれまで続いてきたという状況です。割合もそうなのですけれども、区と指定管理者双方にＷｉｎ－Ｗｉｎの関係でこの割合が決まっていけばいいものというふうに考えております。","id":"exchange-072"},{"speaker":"高橋（し）委員","kind":"提案","question":"ですから、今のところで年度協定の中での提案を改めて求めます。指定管理者制度全体の考え方としてお伺いしますとの意見を述べました。","respondent":"柏原企画調整課長","answer":"健康部門の年度協定というところもありましたけれども、年度年度において、その考え方は整理をしながらというところはもちろんあります。今、方針等々を見直している部分ではありますけれども、そういった中で大きく検討していければと思ってあります。","id":"exchange-073"},{"speaker":"高橋（し）委員","kind":"質問","question":"現在はどのような状況ですか。どのような勤務の状況というのでしょうか、勤務先での評価というか、その辺をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"これは平成２９年度にそうした会員に対しての措置要綱を制定し、シルバー人材センターで改善活動が行われているというようなことです。","id":"exchange-074"},{"speaker":"高橋（し）委員","kind":"質問","question":"それぞれマナーやモラルについての問題も解決していると伺いました。区としては、今後、このシルバー人材センターの取り組みの拡大について、どのように行っていくのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"シルバー人材センターの保育園への派遣などにつきましては、当該所管部門との調整を十分に図る必要性を認識させていただきつつ、区としましては。","id":"exchange-075"},{"speaker":"湯澤委員","kind":"質問","question":"水泳教室・ぜん息健康教室とありますが、このぜん息健康教室とはどういった教室であるのか、ぜん息との診断がないと申し込めないのでしょうか。定員と応募状況などもあわせて説明を求めました。","respondent":"高山健康課長","answer":"年長児から小学校６年生、それからぜん息健康教室については、小学校１年生から中学校３年生までというような形です。募集の定員については５０名ということですが、基本的にはこの５０名の定員内で応募いただいているところです。","id":"exchange-076"},{"speaker":"湯澤委員","kind":"質問","question":"水泳は呼吸器の機能を高めるということで、小児ぜん息などの予防には大変効果的だと聞いておりますので、この事業での効果が出ていると思いますが、そちらはいかがか尋ねました。","respondent":"高山健康課長","answer":"こちらは、品川区の水泳連盟の方々のご協力のもと、非常に丁寧に指導していただいておりまして、多くの子どもたちが連続する４日ないし５日の期間を満了して修了証を皆さんが受けとっているということで、事業としては大変充実したものと考えているところです。","id":"exchange-077"},{"speaker":"湯澤委員","kind":"質問・要望","question":"予防事業として、ここに書いてあります年齢以上の方に対する取り組みがあれば教えてほしいと求めました。ぜん息と診断された方への区の取り組みなどもあれば、あわせて説明を求めました。","respondent":"高山健康課長","answer":"福祉的な視点で実施している事業がございまして、こちらは公害認定を受けられた方と、おおむね５０名程度を定員としている事業です。そうしたぜん息をうまくコントロールする、そういったことを身につけていく、そのような事業として実施しているものがあります。","id":"exchange-078"},{"speaker":"湯澤委員","kind":"質問・要望","question":"それから、全国的に見ると、伝統工芸への従事者は年々減少傾向にあると思いますが、品川区においてはいかがでしょうか。しながわ展への来場者数はどのくらいであったか、ここ数年の推移と、しながわ展への区の評価もあわせて説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"土曜日が非常に天気がよくて４,０００名ほどの来場がありまして、日曜日はその逆で２,０００名ほどで、計６,０００名というようなことです。ほぼ毎年度そういった推移で来ているというようなところです。","id":"exchange-079"},{"speaker":"湯澤委員","kind":"質問","question":"昨年はＴＯＣで開催されておりまして、大変盛り上がっておりましたので、そちらの企画を担当された方にお話を伺いました。先ほど、しながわ展の事業目的をお伺いしましたが、区内で育まれた伝統と歴史を持つ職人の技と味を多くの方に知ってもらうとうたってありました。","respondent":"山崎商業・ものづくり課長","answer":"例えば、そのような新製品といいますか、そういったところも区としては一定の開発支援の補助をさせていただいているというようなことです。こうしたことを通じて、区としてもしっかり承継がなされることを応援してまいりたいというふうに考えるところです。","id":"exchange-080"},{"speaker":"湯澤委員","kind":"提案","question":"お話を伺った方からは、あらゆる方に体験してもらいながら魅力を五感で感じてもらうことが大きなコンセプトであると教えていただきました。さまざま提案をさせていただきましたが、区のご見解はいかがかと思いまして、ご回答ほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"イベントは効果的に集客をさせるというのは、１つ、実施する側の工夫なども含め、おっしゃるとおりだと思います。それをさらに伝統の技と味展のイベントのほうに集客するような工夫も、もう１つ、やらせていただけたらというふうに思ったところです。","id":"exchange-081"},{"speaker":"湯澤委員","kind":"質問・要望","question":"さまざまな取り組みをされていることで理解させていただきました。本当に人材育成を目的として、これからもしながわ展が体験型重視で開催されることを要望させていただきまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"木村委員","kind":"質問","question":"しながわ家庭エコチャレンジからの質問ですけれども、小学生のいる家庭に冊子を配布して、そこでお聞きいたします。小学生のいる家庭にリーフレットを配布とありますけれども、なぜ小学生がいる家庭だけにこだわるのか尋ねました。","respondent":"小林環境課長","answer":"小学校だけにこだわったところではございませんが、さまざまな年代に対して啓発活動を進めているところです。さまざまな年代の中で一番適切だというところを判断させていただいた上で、小学生に対してこういったものを配っているです。","id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"それより家庭での教育、大人に対してしっかりと告知をすべきではないか、まずは大人がしっかりと努力等をしなければいけないのではないか。家庭では親の言葉に反応するわけですから、その点について、お考えを説明するよう求めました。","respondent":"小林環境課長","answer":"親子で一緒にやっていただいて、親子でいろいろな答えを出してもらう、そのようなところもここの中の趣旨には入っているかと考えています。そういった中でも親に対しての環境に対する意識の向上も含めて、さまざまな形で、今現在進めているところです。","id":"exchange-084"},{"speaker":"木村委員","kind":"質問・要望","question":"令和２年２月２２日に、スクエア荏原にて、新型コロナウイルス感染症のために中止になったということでありました。現在、本区での認定店は何店あり、そして実際に認定店の活動や活躍ぶりというものはいかがか尋ねました。","respondent":"小林環境課長","answer":"こちらは平成２７年から事業を開始したものでございまして、来年度、令和２年度に１５０店舗を目標に進めている事業です。そういった中では、少しずつこういった店舗が増えているといったところが成果の１つではないかというふうに捉えているところです。","id":"exchange-085"},{"speaker":"木村委員","kind":"質問・要望","question":"どうぞ頑張ってほしいと求めました。行政側として、しっかり指導をして、しっかり調査等は行っているのかどうか、もう一度説明を求めました。","respondent":"小林環境課長","answer":"さまざま幅広く、今、啓発を進めているところです。広く展開してまいりたいところで、今後、検討してまいりたいと考えているところです。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"次に、２８７ページのリサイクル活動支援事業からの質問です。ずばりお聞きいたしますけれども、区内にあるリサイクルショップは何のためにあるのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"リユース事業ですので、実際にそういったリユースの場である店舗の中に来ていただいて、直接やりとりしていただく。そういったところでリユースの大切さを実感していただける、そのようなところです。","id":"exchange-087"},{"speaker":"木村委員","kind":"意見","question":"この２店舗のリサイクルショップ運用費９１１万円余でありますけれども、利益のために行っているわけではないと考えています。我々はどうしてもお金をむだに使ってしまう、そういうことをなくすためにも、まず行政側から区民の皆さんに伝えることがあればお伝えくださいとの意見を述べました。","respondent":"工藤品川区清掃事務所長","answer":"やはり３Ｒ、特にリユース（再利用）ということは大変重要です。そういった意識を持って発信してまいりたいと思ってあります。","id":"exchange-088"},{"speaker":"くにば委員","kind":"質問","question":"２９７ページ、競争力強化支援事業および３０１ページ、３０３ページの商店街国際化推進事業についてお伺いします。今回、予算計上された２９７ページの競争力強化支援事業と３０１ページの商店街ＩＴ導入支援事業について、それぞれご説明をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"商店街ＩＴ導入支援事業につきましては、区の商店街に対しての支援ということで、あるいは研修会を開催したりというような経費です。個店のほうにそうしたキャッシュレス対応機器のハード経費でありますとか、そうしたものを個店のほうに支援する部分と、一体的に連携しながら。","id":"exchange-089"},{"speaker":"くにば委員","kind":"質問","question":"ぜひ導入店舗を増やしてほしいというふうに思うのですけれども、事業者からは、賛否両論で一概に導入が成功しているというものではありません。地域密着店の多い１０５の商店街を有する品川区において、事業者のご意見や感想等、地元ならではでお聞きになられている点を示すよう求めました。","respondent":"山崎商業・ものづくり課長","answer":"品川区の統計的な飲食店の数からしますと、８０％くらいの割合かなというふうなことで、数字的にはかなり申し込まれているかという感じはいたします。それから、その辺が小さなご商売をやっているそれぞれのお店で、そういった声を聞く機会が多いかという感じがします。","id":"exchange-090"},{"speaker":"くにば委員","kind":"質問","question":"ちょっと短い質問になりますけれども、それでは、国の施策とはまた別に、品川区としては、今後、商店とかを含めて、キャッシュレス導入について、どのようにお考えか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"この決済事業者でＩＴ化にしっかり対応した商店街をつくっていくのだというような自主的な部分に区としてはご支援をするということで、商店街みずからのお考えのものを尊重しつつ、最適化を図っていきたいというふうに考えているところです。","id":"exchange-091"},{"speaker":"くにば委員","kind":"意見","question":"この短い期間中に訪れる多くの訪日外国人が品川区で体験する１つ１つのことをＳＮＳ等を通じ世界中に発信します。中小事業者、商店にどのようなメッセージを発信し、支援、後押しをしていくのか、説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"この３年間、外国人のおもてなし店ＰＲということで発掘をして、一定程度、店舗があります。そうした方向性で実現可能になるよう側面支援をしっかりしていくというようなところで取り組んでまいりたいというふうに考えているところです。","id":"exchange-092"},{"speaker":"くにば委員","kind":"意見","question":"大会期間中に大挙して、事業者にとってはそれが体験したことのないイレギュラーな事態として、ちょっと予測ができないことも発生すると思います。その辺について、短期間でのどのようなバックアップ支援していくか、最後にお願いいたしますとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"商店街のいろいろな諸活動を支援するサポーター制度がありますので、その辺を柔軟に区としては支援といいますか、応援をするということで対応してまいりたいと考えております。","id":"exchange-093"},{"speaker":"くにば委員","kind":"質問・要望","question":"この数年間、まさに東京２０２０大会に向けて、インバウンド施策にさまざま取り組んできましたので、この数カ月の間でぜひとも成功させていただきたいと強く望みまして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"西村委員","kind":"質問","question":"２９５ページ、武蔵小山創業支援センター、創業スタートアップ支援の充実についても伺ってまいります。少しくにば委員のご質問と重なる部分があるかもしれませんが、まず初めに、商店街との連携について伺ってまいります。","respondent":"山崎商業・ものづくり課長","answer":"来年度の新規事業で、五反田バレー商店街連携事業というものを１つ計画しています。製品、いわゆるソフト事業の地産地消的なつながりを地元でつくれればいいなというふうに思って、こうした事業の展開を考えております。","id":"exchange-095"},{"speaker":"西村委員","kind":"意見","question":"一体どうしたら商店街が元気になるのか、一時的に売り上げが上がっても、根本的な解決につながるものはなかなか見当たりませんでした。担当課も手応えを感じていらっしゃる点や、区のお考えを説明するよう求めました。","respondent":"山崎商業・ものづくり課長","answer":"そちらも盛んなところで、そこの魅力がコラボをすることによって、さらなる付加価値を生むというような地域特性があるかというふうに思っています。","id":"exchange-096"},{"speaker":"西村委員","kind":"質問・要望","question":"五反田バレーの方に実際に伺いますと。渋谷、品川のビルでは、入居の審査で３期分の決算が求められ、赤字だと入居は難しくなると聞いたことがあります。","respondent":"山崎商業・ものづくり課長","answer":"これは１つ、平成２０年ぐらいから、そうした分野の支援も少しずつ始めてきた経緯があります。その流れの中で、一昨年、区と協定を締結してということで、さらに動きが可視化され、加速し始めているというようなところかと思っているところです。","id":"exchange-097"},{"speaker":"西村委員","kind":"質問","question":"次に、武蔵小山創業支援センターのリニューアル工事について伺ってまいります。リニューアルの目的と概要を簡単に説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"武蔵小山創業支援センターは平成２２年８月にオープンしまして、そこに１０年前から始めた創業支援で蓄えた知恵を踏まえて、しっかり頑張っていこうというようなねらいです。","id":"exchange-098"},{"speaker":"西村委員","kind":"質問・要望","question":"今後、利用可能人数はどれぐらい見込めるのでしょうか。例えば１階の交流スペースだけを登録制などで利用することができるですとか、サービスの幅を広げると、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"調整をつけさせていただいて、６階についてはそのようなところで、検討を今後考えてまいりたいというふうには考えているところです。武蔵小山創業支援センターの１階につきましては、３事業者が入るチャレンジショップということで、そのようなところをねらっているところです。","id":"exchange-099"},{"speaker":"西村委員","kind":"質問","question":"乳幼児を育てるフリーランスや在宅ワークの方は、区内にどれぐらいいらっしゃるのでしょうか。在宅ワーク支援につながるこのような整備も区全体で検討していただきながら、引き続きお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"おくの委員","kind":"質問・要望","question":"２０５０年までの温室効果ガス実質ゼロを目指す立場から、ＲＥ Ａｃｔｉｏｎへの参加の検討、非常事態宣言などを求めて質問しました。パリ協定以後、すなわち２０５０年での温室効果ガス実質ゼロを目指すべきだと変わってきた、こういう認識を品川区はお持ちか尋ねました。","respondent":"小林環境課長","answer":"委員ご指摘のとおり、実質ゼロを目指していくというところについては、各国、動きがあることは承知しています。区としてもそういったところは情報として把握しています。","id":"exchange-101"},{"speaker":"おくの委員","kind":"質問","question":"この認識、時期が早まってきたという認識はお持ちなのでしょうかと伺ったのですけれども、その点はいかがでしょうか。もう一度お願いいたします。","respondent":"小林環境課長","answer":"国も含めて、例えば昨年６月に策定しました温暖化に対する長期戦略の中でも、前回よりも少し早まったところかとは認識しております。見直しの時期を迎えるところでございまして、そういった内容を踏まえて、必要に応じた対応を区としてもとっていきたいと考えているところです。","id":"exchange-102"},{"speaker":"おくの委員","kind":"提案","question":"思い切って削減目標を、啓発冊子もそれを前提にしたものに見直されることを提案しますけれども、いかがでしょうか。お伺いいたしますとの意見を述べました。","respondent":"小林環境課長","answer":"そういったところも、国はそれを踏まえて具体的な支援策を来年度検討していくということが、勉強会などを含めてやっているところです。","id":"exchange-103"},{"speaker":"おくの委員","kind":"質問・要望","question":"２０５０年実質ゼロというのは、非常に大きな流れになっているということを、これを目標に掲げること自体に意味があるということを踏まえて頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"高橋（伸）委員","kind":"確認","question":"これは確認ですけれども、２８９ページ、オリンピック・パラリンピック開催期間中の収集対応で１,５００万円余となっています。これは、おそらく資源も含まれているということと、幾つかのものを合算した金額だと思うのですけれども、まず最初にそれを確認したいと求めました。","respondent":"工藤品川区清掃事務所長","answer":"２８９ページのオリンピック・パラリンピック開催期間中の収集対応というのは、資源回収のほうも増やすというところで、それを合わせた経費です。このような形で予算を盛り込ませていただいているものです。","id":"exchange-105"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、同じく２８９ページの車両購入ですけれども、小型プレス車を４台購入するということですけれども、この４台の内容を教えてください。お願いします。","respondent":"工藤品川区清掃事務所長","answer":"こちらに記載していますように、小型プレス車４台を、今回計上させていただいてあります。来年度は４台のうちハイブリッドの清掃車を２台購入しまして、あとの２台は通常使っている清掃車両を購入するという形になってあります。","id":"exchange-106"},{"speaker":"高橋（伸）委員","kind":"質問","question":"わかりました。それをしない理由をお聞きしたいのと、あと、清掃事務所の直営車の台数と今後の購入はどういう考え方をされておられるのかお聞きしたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"最後のご質問の今後の購入の考え方ですけれども、考え方としては、６年ごとの更新を一定の目安にしています。一般の連絡車両等につきましては１０年というところで、車両の損傷具合等を勘案しながら買い替えを行っているところです。","id":"exchange-107"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"引き続き環境に配慮した取り組み、また事故防止の取り組みを要望して、この質問は終わらせていただきます。大体例年行い、今回で９回を迎えていて、エントリー数は件数自体が増えているかどうかという確認をさせてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"過去には、一番最高では、第２回の１２３件です。それから、一番少ないところでは、平成２９年度の７８件というようなところです。","id":"exchange-108"},{"speaker":"高橋（伸）委員","kind":"確認","question":"私の知人がエントリー審査、プレゼン審査に残って、信用組合賞を受賞しました。どういう経過でかかわっていただいているのかということだけを確認させてもらいたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"ビジネスグランプリで受賞した人に賞品ということで協賛を創業支援センターのほうで募りまして、そういう意味で、地元の信金が幾つかございましたけれども、本グランプリの事業趣旨などに乗っていただいて、ともに応援しますです。","id":"exchange-109"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、２８７ページ、リサイクル活動支援の中から、リサイクルショップの運営と、関連してリサイクル情報紙の「くるくる」について伺います。タブレットを１台、例えば棚が欲しいとかという要望の方には、基本的にはプッシュ配信がされる。","respondent":"工藤品川区清掃事務所長","answer":"いろいろとそのようなツールがある中で、リサイクルショップをどのようにしていくのかというところは、１つ課題だというふうに思ってあります。今後の運営につきましては、そういった部分を含めて、そういった中で検討してまいりたいと考えているところです。","id":"exchange-110"},{"speaker":"芹澤委員","kind":"提案","question":"その１つの提案として、ＩＴ、例えば地域の五反田バレー内でのマニフェスト大会とかというのをつくっていただいてもいいのかなと思います。その１つのマニフェスト大会の中で、もちろん民間企業ですから、行政側も企業者たちを評価してあげるとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"委員おっしゃったような、１つ、先々の教育に資するような何か取り組みだとか提案を発表するピッチ大会みたいなこともやらせていただいております。そういう意味では、さまざま取り組んでまいります。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問","question":"２９２ページ、それから２８３ページの（仮称）品川区立環境学習交流施設、２８５ページのプラスチックの削減などについてお伺いしたいと思います。区の現状と今後の見通し、そしてその対策に対する決意をお願いいたします。","respondent":"山崎商業・ものづくり課長","answer":"そのときに対応したもの、そこは喫緊の課題ですから、早く対応しようというようなことでやらせていただいています。それから、多様な働き方の中のテレワークなり時差出勤なり、このようなところも含めてさまざま最適に検討してまいりたいと考えております。","id":"exchange-112"},{"speaker":"あべ委員","kind":"質問・要望","question":"３月末までとありますけれども、早急に期限の延長を検討し、周知をしていただきたいというのが１点。ご答弁をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"もちろん延長については、そうした方向で考えてあります。それから、実はもともと個人事業主も中小企業ということで位置づけをしまして、従来より融資の対象ということで適正に応援しています。","id":"exchange-113"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは国に対して働きかけていっていただきたいと、これは要望にしておきます。コンクリートを埋めて、ＣＯ２で換算すると一体どれだけの環境負荷がある建物なのか、試算をしていれば説明を求めました。","respondent":"小林環境課長","answer":"建設によってＣＯ２がどれだけ発生するか、それはやはり規模観とこれから設計を進めていく中で、さまざま設備の中に取り入れていく予定です。さまざまな工夫をしていきながら、環境負荷がかからない活動は引き続き検討してまいりたいというふうに考えてあります。","id":"exchange-114"},{"speaker":"あべ委員","kind":"質問・要望","question":"教育費のところでまた伺いたいと思いますが、もう１つ、ビーズクッションです。環境の負荷をより小さくするための捨て方を検討し、そして指針をつくって広報していく必要があるのではないかと考えておりますが、いかがか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"ごみリサイクル通信や、例えば地区連絡会といいまして、廃棄物減量推進員の連絡会があります。そういった中で、どのような形で出していただけるのかというところは考えてまいりたいと考えています。","id":"exchange-115"},{"speaker":"あべ委員","kind":"質問・要望","question":"大きさから言えば、ごみ袋の中に入れてしまえば、それが入っていることに気づくのはなかなか困難だと思います。まずは出す方がほかのものと混ぜてしまったら、そちらの方向でぜひよりよい方向を考えてほしいと求めましたが、改めてご答弁をお願いします。","respondent":"工藤品川区清掃事務所長","answer":"ビーズクッションにつきましては、排出方法等につきましては、引き続き検討したいと考えています。","id":"exchange-116"},{"speaker":"大倉委員","kind":"質問・要望","question":"品川区の１つの魅力に商店街があるのかと私は思っておりまして、今、そうした啓発についてはどのようにお考えでしょうかということと。かなり水切りの費用が高いのかというところで、なかなか難しいところもあるかと思うのですが、その辺についてのお考えを説明するよう求めました。","respondent":"山崎商業・ものづくり課長、小林環境課長","answer":"スマートフォンの普及を考えて、より汎用的なアプリというのは、すごく現実的なご提案かと思うところです。これは商連と区も連携して、そうした方々を通じてアプリの有用性なども含めて、テーマに取り組んでいきたいと考えたところです。 全て一気に変えようとしては、なかなか難しいのかと考えています。そういったところにつきましては、庁内でも情報共有を図りながら、可能な限りの取り組みは進めてまいりたいというふうに考えているところです。","id":"exchange-117"},{"speaker":"大倉委員","kind":"質問・要望","question":"マドラーとか、こうしたところのまずは削減をしていくというところで、目標とか削減方針みたいなものがあるのでしょうか。イベントで使っていくときに、その点の目標や削減方針みたいなものがあれば説明を求めました。","respondent":"山崎商業・ものづくり課長、小林環境課長","answer":"観光との連携という意味では、観光計画の中におきましても、商店街は品川区の大きな１つの担い手、魅力という位置づけです。所管を連携してというのは当然そういう意識で効率的ににぎわい創出などに努めてまいるということで基本的には… 毎年毎年調達方針は変わっているところでございまして、今年度もプラスチックに関する目標達成に向けて、さまざまな方針が示されたところです。","id":"exchange-118"},{"speaker":"大倉委員","kind":"質問","question":"よかったね、また来ようと思っていただける商店街の視点から、おもしろい商店街を見ていただけるように取り組みをしていただければと思っています。さまざま取り組みがされてきましたが、品川区としてもそうした啓発も含めた企業、大学等の連携の考え方について説明を求めました。","respondent":"小林環境課長","answer":"目標ですが、まずは来年度、区内の区民まつりを１３地区合わせて、また区の主催するイベントに対してそういった取り組みを進めているところです。地域との連携、大学との連携につきましても、その辺の情報収集は引き続き図ってまいりたいというふうに考えているところです。","id":"exchange-119"},{"speaker":"塚本委員","kind":"質問","question":"２８３ページ、２９７ページ、２８５ページの資源回収についてお伺いしたいと思います。あるいは、それと、今後これを区内においてどのように推進していくというようなお考えがあるかお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"例えば五反田に集積が進んでいるＩＴベンチャーなどにおきましては、今日的な課題に対応するために、既にテレワーク。今日的な注目ですとか、ここを１つのきっかけに多様な働き方を推進するという意味でも、充実をさせていきたい領域だというところで考えるところです。","id":"exchange-120"},{"speaker":"塚本委員","kind":"質問・要望","question":"それを１つの契機として、充実させていっていただきたいということはそのとおりなので、ぜひお願いしたいと思います。あるいは課題解決のための製品、こういったことも考えていくということについては、いかがでしょうかということでご答弁ほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"いろいろな企業の有効な人材活用の視点も含めて、これはトライしていくチャンスがあれば取り組んでいきたいというふうには思っておりました。募集をしたのですが、なかなかいい提案なりがなかったような状況にはあります。","id":"exchange-121"},{"speaker":"塚本委員","kind":"質問・要望","question":"最初に確認をさせていただきたいのですが、一見目立たないのですけれども、多くの方がよく利用しています。こういったものも引き継がれるのかどうかを確認させてほしいと求めました。","respondent":"小林環境課長","answer":"今回の施設の建設にあたりましては、施設の敷地の建物の中にキッズルームを設ける予定です。具体的にはこれからの検討になるかと思っているところですが、今後、検討していく予定で考えているところです。","id":"exchange-122"},{"speaker":"塚本委員","kind":"確認","question":"多目的スペースなど一時に結構たくさんの人が来ることができるスペースもあり、多目的スペースの定員は１００名となっております。そうするとかなり苦情が来るということも予測されるというところで、駐輪対策はそういった意味で十分でしょうかというところを確認したいと思います。","respondent":"小林環境課長","answer":"そういったところも活用していく必要があるかというところで、その辺は関係する課と調整を図りながら進めてまいりたいと考えています。そういったときにつきましては、運営事業者と調整を図ってまいりたいというところで、今後検討してまいりたいと考えています。","id":"exchange-123"},{"speaker":"塚本委員","kind":"意見","question":"門の左側にちょっと、せいぜい１０台ぐらいはありますけれども、それ以外はあまりない。この駐輪対策については、利用がどれぐらいあるのかということをよく想定していただいて、十分受け入れられる駐輪場の設置をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-124"},{"speaker":"本多委員","kind":"質問","question":"区有施設ということで、これは分析が進んでいるというふうに理解すればいいのでしょうか。その違いも説明を求めました。","respondent":"小林環境課長","answer":"方向性ですが、やはり区の環境に関する方針の中では、区が一事業者として温室効果ガス排出量を減らしていく目標が示されているところです。そうした中では、今回の分析委託を含めながら中身はしっかり把握していきたいというふうに考えているところです。","id":"exchange-125"},{"speaker":"本多委員","kind":"質問","question":"いろいろ取り組みはあるかと思いますけれども、１つだけ伺います。従来型のものをつけるのか、それとも新しく開発されたような環境にふさわしいエアコンをつけるのか、その辺についても説明を求めました。","respondent":"小林環境課長","answer":"室外機から発生する音の対策、そういったところも十分に把握していきながら設置場所については検討されているものというふうに聞いているところです。","id":"exchange-126"},{"speaker":"本多委員","kind":"質問","question":"ミスト設備設置助成について伺いますが、令和２年度における対象件数は、今年度の予算計上についてご見解を説明するよう求めました。","respondent":"小林環境課長","answer":"太陽光はご指摘のとおり、例年と同等の額を助成額として見込んでいるところでございまして、家庭用３０件、１件当たり最大９万円の助成です。ミストの設置につきましては２種類の考え方がございまして、１つは、その２種類に対する助成が行われたところです。","id":"exchange-127"},{"speaker":"本多委員","kind":"質問","question":"以前は２０万円以上するものとかでしたけれども、レンタルとかリースとかも、その辺も全部含めて大丈夫ということですか。説明を求めました。","respondent":"小林環境課長","answer":"リースについてですが、移動式のものにつきましては、リースについても助成対象としたところですので、今年度もそのような助成をさせていただいたところです。","id":"exchange-128"},{"speaker":"本多委員","kind":"質問・要望","question":"最近、日本全国でも１００以上の自治体が検討されているようなのですけれども、今後そういうものが普及してくると思うのです。１つの移動トイレで男性用と女性用が隣になっていたので、あれはちょっと、男性用と女性用と別々の移動トイレを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"渡部委員","kind":"質問・要望","question":"融資あっ旋のところは確認させていただきたい点を少しお伺いするのと、２９７ページは、あとはエコバッグのところでお伺いできればと思います。区への融資の相談というのは、大体そのような感じなのではないかと思うのですが、傾向はどうなのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"企業体というよりも、個人事業主の方々ということですので、とにかく相談に来たという方もいらっしゃるという傾向があります。経営者なり、経営のご担当の方が、委員ご紹介のような前捌きをしてご相談に来られるとかというケースが多いかなという気はしております。","id":"exchange-130"},{"speaker":"渡部委員","kind":"質問","question":"これは２３区横並びではなくて、品川区のものはまあまあ使い勝手のいい制度が含まれていたのかなどというふうに思います。２.０％なり、もし国のほうでいい制度が出てきてしまった場合には全部もう１回やり直しになるのか、そこだけ説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"区の制度融資の中では２億８,０００万円をお貸しできる制度融資がありませんので、その中で最適なものをセレクトする、選ぶということになります。","id":"exchange-131"},{"speaker":"渡部委員","kind":"質問・要望","question":"承知いたしました。何とか乗り切っていただきたいと思うところですが、話し合いをされていて、その年々の制度融資の金利は決まっていくのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"区のほうでは、それを日ごろから検討して、次年度には設定の利率を変える必要があるのかないのかという検討をします。それから現在まで、来年度もその予定ですけれども、現行の利率でいくということで考えているところです。","id":"exchange-132"},{"speaker":"渡部委員","kind":"確認","question":"ちょっと確認させていただきたかったので、ありがとうございました。本当に続けてほしいと思うのですけれども、意気込みをお願いしたいのと、このデザインがいいですよね。","respondent":"山崎商業・ものづくり課長","answer":"今年度１０月に行われましたＡＩ・業務自動化展などで、来訪者の方、ブースを訪れた方にＰＲとして配布をしております。今後もそういった形でワンポイントをつくっていきたいというふうに思っているところです。","id":"exchange-133"},{"speaker":"渡部委員","kind":"質問・要望","question":"何かこれ、ほかのものにも活用できたらいいなというのは要望でございまして、私もこれを持ってうろうろ歩こうと思います。ちなみに、今年もこの品川パビリオンは、環境展と機械要素技術展とＡＩ・業務自動化展の３つでいくのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"オリンピックの開催の関係で、会場が実は幕張メッセのほうに変わったり、開催日程がというようなことで、来年度の予定につきましては、ＡＩ・業務自動化展と、それから機械要素技術展の２本でいくというような計画になっております。","id":"exchange-134"},{"speaker":"渡部委員","kind":"質問・要望","question":"お話はいろいろ伺っていて、改めてもう一度教えてほしいのと、荷物を入れたら肩にかけたい。これから間に合うのであれば、そういうものをしっかりとやっていただいて７月に間に合わせていただければ、お考えを説明するよう求めました。","respondent":"小林環境課長","answer":"区商連と連携した取り組みということで、８,０００枚から１万枚ぐらいは配りたいということで、予算を計上しています。ふだんから使ってもらえるデザインが、そういったところも情報収集をしながら、また使いやすさというところも含めて検討をしています。","id":"exchange-135"},{"speaker":"渡部委員","kind":"質問・要望","question":"ちょっと肩からかけられるというようなものをぜひ検討いただきたいのと、これは、デザインがいいのです。こういうものもありますので、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問","question":"２９３ページの伝統的産業の振興に入るのでしょうか、中小企業センターの中で実演をしていただいております。次に、２９５ページの事業承継支援事業、この成果はどれだけだったのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"他の、例えば東京都庁の観光のブースで出展をいただいたりとか、さまざま工夫しながらＰＲの場ということで考えてまいりたいと考えています。来年、２期目を迎えるということで、改めてしっかり財団と組んで付加価値を高める産業振興施策を展開していきたいと考えるところです。","id":"exchange-137"},{"speaker":"西本委員","kind":"提案","question":"なので、そこそこのところは、それについては別ないろいろな方法がありますよという提案も必要になってくるのかというふうに思います。過去にとらわれずに、このマイスターという本来の時代に合ったものをこれからもつくっていただきたいと意見を申し上げて終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"私は、２９２ページ、産業経済費についてお聞きしたいと思います。説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"例えば今回の感染症の影響という意味では、収束をして結論が出ている状況ではありませんので、まだなかなか答弁しにくいところかという感じです。ただ、そうしたお声に真摯に対応していく必要があるかというところは感じているところです。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"経営変化対策資金、これは先手を打つものですごく重要なことですが、これは全ての小規模企業に案内を出していただけるのでしょうか。予算は限度があるはずなので、説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"今回の１つの特徴が、今はまだ２週間あまりですけれども、そのようなことを申しておりました。ただ、まだ結論づけて定義をしてというような状況ではありませんので、区としては一生懸命対応していくというようなところで考えているところです。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"こちらからメールマガジンで連絡している、品川区内の中小・零細企業は、そんなに少ないわけないではないですか。１軒１軒こちらからきちんと案内状を送って、もう一度、ご見解を説明するよう求めました。","respondent":"山崎商業・ものづくり課長","answer":"こちらは、商連を通じて商店街のほうからアナウンスをしていただくような、そういうようなことでまず対応をしているということです。区のほうでは先ほどの説明にかぶりますけれども、今、やらせていただいているような状況です。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"やはり、品川区なのですから、その地域へ行けばわかります。地場産業が完全に崩壊してしまうではないか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"今の状況については、喫緊の課題であって、対応を看過なくしっかりしたことが必要だという認識はあります。ぜひ品川区の会議室で特設ブースでもつくって対応したらどうだ、品川区の産業の力で何とか乗り切ってまいりたいというところが私どもの考えです。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、せっかく地元、この品川区の区民のため、企業のため、小規模事業者のため、身近な品川区が、案内状を出すことはいいではないですか。もう一度、ご見解を説明するよう求めました。","respondent":"山崎商業・ものづくり課長","answer":"そのご支援をするということで、状況をしっかり確認しながら最適な組み合わせでこの対策のさらなる充実がというような状況になりましたら、区としましてもいろいろな角度からさまざま研究をして臨みたいという思いではおります。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に申し上げます。ぜひ区民の声、それから中小・零細企業、小規模、そういう企業の叫びは、実態はしっかり認識して、舵を少し切ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"中塚委員","kind":"質問・要望","question":"２９３ページの中小企業経営支援事業費について、新型コロナウイルス感染症に影響しての経営支援について伺いたいと思います。ぜひ機敏な対応をしてほしいと求めましたが、補正についてのお考えを伺いたいと思います。","respondent":"品川財政課長","answer":"補正予算につきましては、現在、さまざまな需要が見込まれているところです。どのぐらいの需要が見込まれるかというところを正確に見据えていきながら、補正予算につきましては、このように考えております。","id":"exchange-145"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ品川区としては、国に対して引き上げを要望していただきたいというのが１点。同じことですけれども、正規、非正規と差をつけるという考え方も私はおかしいと思っているのですが、区の考えを伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"事業者宛に厚労省から出ている新型コロナウイルス感染症の影響を受ける人という、わかりやすくまとまっているパンフレットがあります。国が方針なり決めた部分、今は状況を見極めつつ、区としての産業振興施策を適正に行っていくという考えです。","id":"exchange-146"},{"speaker":"中塚委員","kind":"質問・要望","question":"フリーランスと自営業の休業補償が１日４,１００円、最低賃金をさらに下回る、こういう状況でよいのかと私は思います。先ほど伺ったのは、引き上げを国に求めてほしいと求めましたが、改めて伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"今、国の制度の設計について、区として意見を申し上げるという状況ではないのかです。やはり正しく状況を把握し、品川区としてとるべき産業振興施策などをしっかり適正に実行していくというようなことが必要かと考えるところです。","id":"exchange-147"},{"speaker":"中塚委員","kind":"提案","question":"ぜひどういう業態に影響が起きているのか、相談で把握するのではなく、区から状況を把握してほしいと求めましたが、いかがでしょうか。引き上げを求める状況だと思いますので、重ねて伺いますが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"いわゆる窓口景況感は、品川区内では、品川区の産業振興の窓口でしか得られない景況感があります。区としましては、国の動向にも注意しつつ、最適な産業の振興施策を展開するというふうに考えるところです。","id":"exchange-148"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかも、所得が減っている、日本経済の６割を占める個人消費が落ち込んでいるというリーマンショックにはない影響があると思います。国に対しても、ぜひ自営業やフリーランスに対する給付の引き上げを強く求めていただきたいとお願いして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２８５ページのもったいないプロジェクト等について伺いたいと思いますが、３０３ページのプレミアム付区内共通商品券発行助成について伺います。１５０の目標に対して１４９店舗、これについて、新年度の予算の中でどういった取り組みがされていくのか教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長、小林環境課長","answer":"来年度のプレミアム付区内共通商品券につきましては、プラス２億円という形で、計８億円というようなことです。４億円、４億円でというスキームにはなっておりますが… 来年度以降につきましても、目標は達成したところですが、引き続き店舗の拡充については区としても進めてまいりたいというふうに考えております。","id":"exchange-150"},{"speaker":"たけうち委員","kind":"提案","question":"ＳＤＧｓは、ＳＤＧｓの推進をそういった角度で行っていただければどうかというふうに提案をいたしますが、ご見解をほしいと求めました。","respondent":"小林環境課長","answer":"まず冊子のほうですが、やはり食品ロスが１７の目標に対して非常にかかわりが大きいところは区としても認識しております。委員ご提案の商店街との連携ですが、その周知が広がる取り組みについては、今後も検討していきたいというふうに考えているところです。","id":"exchange-151"},{"speaker":"たけうち委員","kind":"質問","question":"商業・ものづくり課長もうなずいているので、一言ほしいと求めましたが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"ＬＥＤ化を例に出していただきまして、そうした考え方が浸透しております。東京都の補助金、かなり認知度が広がっておりますので、そうした観点から関心を持っていただく必要性も大いにあるかというところで感じた次第です。","id":"exchange-152"},{"speaker":"大沢委員","kind":"質問","question":"２９９ページの商店街活性化事業費をお願いしますが、役所も含めて、そこのところのお話はされているのでしょうか。お願いします。","respondent":"山崎商業・ものづくり課長","answer":"手続の簡素化ということと、１つ１つの標準的にかかる時間を短くするという簡素化、双方でいろいろ検討をしております。今回の新型コロナウイルス感染症に関しての緊急支援について、結果、時間の短縮を図っているというようなことでやらせていただいているところです。","id":"exchange-153"},{"speaker":"大沢委員","kind":"質問","question":"時間の短縮も、それはもちろんですけれども、手続上、ペーパー上の、申請したりとか、もろもろを少なくしながら簡素化を図りながらやられるようなことはお話をされているということでいいのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"経営変化を判断する５％という指標がありますが、数字的なものではないキャンセル台帳を確認するとか、そういったことで対応を短くさせていただいているというようなところです。","id":"exchange-154"},{"speaker":"大沢委員","kind":"質問・要望","question":"そういう方ばかりではないと思いますので、そういうところを簡素化に努めてほしいと求めました。そこのところはどのようにして解消されて、緊急かつ円滑な融資が行われるのか説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"その場で一緒につくるという作成支援も含めてやらせていただいておりますので、それが最大の時間短縮につながっているかという感じがします。","id":"exchange-155"},{"speaker":"大沢委員","kind":"質問・要望","question":"昔、そのときはアイスクリームという１万円ぐらいの在庫を幾つも常に在庫として抱えているものですから、そこのところは融資が比較的おりました。その動態を読みながら、今後の商業動向、商業特性についてどのようにお考えなのか説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"平成２８年度に商店街の実態調査を実はやっていまして、商店街などで物をお買い求めになることが消費者の満足度を上げることです。","id":"exchange-156"},{"speaker":"大沢委員","kind":"意見","question":"事業の中で、まさに物からサービスへという消費動向の変化とともに、イベント事業の助成があります。それがまさに商店の物に対してイベントという付加価値をつけた事業ですけれども、これについての目的と現状の課題をお知らせくださいとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"告知をするというような、いわゆるＰＲ効果といいますか、そういったことが１つ大きな目的かなというふうに捉えております。なかなか継続的なご商売の販売の促進だとか、日常との乖離といいますか、その辺が１つ課題かなという気はしています。","id":"exchange-157"},{"speaker":"大沢委員","kind":"質問","question":"その課題を解決するために、もうちょっと仕掛けが必要であると思いますけれども、その課題解決に向けた、平成２８年ということですから、もう２年余がたっているわけですけれども、その平成２８年以降の取り組みの中で、課題解決に向けてどのような取り組みをされたのか説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"夕方、ワゴンセールを行うとか、そうした小さいイベントを複数回実施していただくようなことを条件にインセンティブの助成をさせていただいています。","id":"exchange-158"},{"speaker":"大沢委員","kind":"質問","question":"その今のイベントの取り組みを伺いましたけれども、消費動向、消費に対するトレンドが今後変わっていくのは間違いないです。そもそもの商店街のありよう自体をもう１回、そのように考えることを始める必要があると思いますけれども、どのようにお考えか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"区民の皆様の身近なお買い物、サービスのインフラとして、公共性が商店街にはあります。先ほど来ありました環境に対する取り組みが行われたり、商連などと連携しながら、そういった取り組みも１つ必要かというふうには思うところです。","id":"exchange-159"},{"speaker":"石田（秀）委員","kind":"質問","question":"２８７ページ、集団回収について伺います。そこら辺のところをどう考えて、今これを行っていこうとされているのか、ここからお聞かせ願いたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"私ども、ルート対策費を設定しておりまして、そういった形で支援をしているです。いずれにいたしましても、その原資が地域活動に資されるというところで進めてまいりたいというふうに考えておるところです。","id":"exchange-160"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここら辺のところは、しっかり今の体制を維持していくのだというような答弁に聞こえたのだけれども、そういうつもりでいいでしょうかという確認。それから、今言ったように、６円を変えないでいこうとするのか、そこら辺の確認もしたい。","respondent":"工藤品川区清掃事務所長","answer":"これは２３区の動向等を常に私どもも把握していますが、現在のところ、２３区中２０区ぐらいが６円です。そういった部分、回収金額も含めまして、そういった部分の制度設計等は引き続き検討してまいりたいというふうに思ってあります。","id":"exchange-161"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"極論を言えば、５０円値段を上げてもいいではないですか。１つ統一的につくるということを、そういうエコバッグを作ってもいいと思うのだけれども、その辺の感覚を教えていただきたい。","respondent":"小林環境課長","answer":"委員ご提案の内容も含めまして、検討を進めてまいりたいと思っているところです。さまざまな観点で広く区民の方から愛されて使っていただける工夫は、しっかりと検討してまいりたいというふうに考えているところです。","id":"exchange-162"},{"speaker":"石田（秀）委員","kind":"意見","question":"１つだけ、町会で考えて議論しながらやっているのだから、そこを優先してもらいたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-163"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/273075?Template=document&Id=1116#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":125845,"voices":364}},{"id":"r02-20200312-3","meetingId":"r02-c-budget","date":"2020年3月12日","dateIso":"2020-03-12","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を176件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"私からは３０７ページ、シェアサイクル事業、３１１ページ、無電柱化推進事業、３４７ページ、多言語翻訳機賃貸借経費について伺います。シェアサイクルについて伺います。","respondent":"今井土木管理課長","answer":"ポートの数は、現在、７７ポート、ラックは６６０ぐらい設置しています。観光などに資する１日利用の回数をさらに高めていく、それから、利用回数を増やしていくのが目標です。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問・要望","question":"１点、少し懸念があって、自転車のマナーが以前からも言われてきたかと思います。バイクシェアをぜひ拡充していただきたい中で、何か推進できないものかなと思っていますが、お考えを説明するよう求めました。","respondent":"今井土木管理課長","answer":"Ｕｂｅｒ Ｅａｔｓなどの個別宅配事業者への対応ですが、今も都心１０区で連携している事業者、この課題は十分認識しています。やはり、自転車利用者登録者全てに対して、プッシュ方式で登録会員に警視庁本部からの注意やマナー喚起をするような体制をとっております。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問・要望","question":"無電柱化の推進について、前回もさまざまな地域で取り入れていただきたいという要望をさせていただきました。もちろん道路なので危ないのですが、車が通っていないときに確認していただいて、今自分がいるところはどこなのだ。","respondent":"多並道路課長","answer":"トランスの考え方ですけれども、無電柱化を進める上で、四角いボックスが地上に設置される形になります。広報広聴課や防災課などとよく連携を図りながら、技術的な部分について連携しながら、必要があれば検討していきたいです。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"続けて、多言語翻訳機賃貸借経費について伺います。この事業の内容、あとは運用方法を説明するよう求めました。","respondent":"中島防災課長","answer":"対応するにあたりまして、このような多言語翻訳機があるといいと考えまして、導入していきたいと思います。平時は、訓練等でも活用していきたいと考えています。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"それは、ネットワークがつながって、翻訳されるというものになるのか尋ねました。","respondent":"中島防災課長","answer":"ネットワークがあるという前提で、今、Ｗｉ－Ｆｉなども区では整備を進めております。それらを活用しまして、運用していきたいと考えています。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"質問","question":"『旅の指さし会話帳』をつくっている出版社があって、そこでは、被災地支援外国語対応ツールというものを無料で公開していると伺っています。そういったものの活用について、ご見解を説明するよう求めました。","respondent":"中島防災課長","answer":"ご提案のアナログというか、紙ベースのものの準備というのは、災害時には有用だと考えています。今、そのあたりのところは、今後の防災対策の中で研究をしていきたいと考えています。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"質問・要望","question":"聴覚障害の方々、さまざまな方々に安く、広く使っていただけるようなツールの作成を品川区でご検討ほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問・要望","question":"要望をいただいた当時、すぐに相談いたしました。この備蓄マスクの配布について、どのように考えていますか尋ねました。","respondent":"中島防災課長","answer":"ただ、委員ご指摘のとおり、今回の新型コロナウイルス感染症のような場合では、やはり平常時とは違う対応が求められるところです。基本的な考え方といたしましては、いざというときに備えて一定量を確保しつつ、災害の備蓄物資を使用していくことを考えております。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問・要望","question":"先ほど、課長のご答弁がありましたが、ぜひ品川区でも積極的に活用していただくよう要望しまして、次の質問に移ります。しかし、昨今起こる災害により、電柱の倒壊や大規模停電など、混乱が起こる今、無電柱化は喫緊の課題ではないか尋ねました。","respondent":"多並道路課長","answer":"この中では、まず、優先的に整備を進めるべき路線として、現在４路線を挙げさせていただいて、こちらについて進めていく予定としております。都でも新たな制度が検討されているような流れもありますので、この１０年の間に、現在のところは考えてあります。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"実は、今日、３月１２日まで、区民の皆様へ意見をいただいておりますが、今現在、何件ほど、どのような意見があるのか、お聞かせください。木密地域避難経路であります、防災生活道路の無電柱化が急務と思いますが、ご所見をお伺いいたします。","respondent":"多並道路課長","answer":"その中の２路線については、広域避難場所であります戸越公園一帯への避難路２路線ということで、今回も挙げしています。今、やはり防災対策の避難路というのは大きな課題でもありますので、区としても同じような考え方で進めているところです。","id":"exchange-010"},{"speaker":"松澤委員","kind":"意見","question":"１ｋｍの範囲を無電柱化するのに、５億円以上の費用がかかります。低コスト化に向けた手法がいろいろと考えられますが、品川区として、低コスト化に向けたご見解を説明するよう求めました。","respondent":"多並道路課長","answer":"実際に戸越銀座商店街、旧東海道で無電柱化整備をする際には、狭い道路の有効性があるということで、この小型ボックスの手法を使っております。これについては、今後の設計、工事の中で検討しながら進めていきたいと思っているところです。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"次に、公園児童遊園費についてお伺いいたします。今現在、品川区の公園において、犬を連れて散歩ができる公園は何か所あるか尋ねました。","respondent":"溝口公園課長","answer":"区内には、２６８か所の公園がありますが、リードをつけて犬が散歩することが可能な公園は、２０か所を指定しています。面積が１,５００ｍ２以上や、また、現在２０か所の公園において犬の散歩を認めているところです。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"保護施設にいる犬、ペットを通じて交流を図り、新たな生きがいづくりや地域社会への潤滑油としてのメリットははかり知れないと考えています。そこで、ドッグランの設置の考えや、動物との共生社会の考えを説明するよう求めました。","respondent":"溝口公園課長","answer":"やはり大規模な公園に一定の広さを占有する形での設置になりますので、同じような形でのドッグランの設置は難しいと考えているところです。そのように考えているところです。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問・要望","question":"款が違うので、質問ではなく、動物との共生社会が整う品川区を要望しまして、次の質問へ移らせていただきます。この新規計上になります、風水害に対する予算は、どのような活動に充てられるものなのか尋ねました。","respondent":"中島防災課長","answer":"その中で、避難体制の見直し案や望ましい避難体制を検討して、来年度の台風対応等につなげてまいりたいと考えています。例えば、あるいは長期の停電に備えて非常用発電機、持ち運びできる発電機の追加配備等を風水害対応の一環で取り組んでいきたいと考えています。","id":"exchange-014"},{"speaker":"松澤委員","kind":"確認","question":"町会・自治会によっては、風水害時に自分たちで避難所を開設するという防災意識の高いところもあります。見直し、防災意識の確認をすることが最優先ではないかなと思いますが、ご所見をお伺いいたします。","respondent":"中島防災課長","answer":"基本的に避難所というよりも避難場所という考え方の中で、運営するということで、これまでも行ってきたところです。避難対策の検討の中でも、そのような地域との連携ということも念頭に入れて、考えていきたいと考えています。","id":"exchange-015","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"東日本大震災から９年目にあたり、活躍した消防団や町会の区民消火隊、ミニポンプ隊についてお聞きいたします。品川区における区民消火隊、ミニポンプ隊の配置状況、また、Ｃ級ポンプ、Ｄ級ポンプの配備状況を説明するよう求めました。","respondent":"大森災害対策担当課長","answer":"６６隊の区民消火隊にそれぞれ１基、１８４隊のミニポンプ隊にそれぞれ１基、計２５０基を配置しております。そのほかに、区民避難所です小学校、中学校、義務教育学校の４６校にＤ級ポンプを配置しているものです。","id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"地域を７つに分け、７個分団で活動しており、第四分団には消防団の本部施設がありません。この２個分団は、東京都の話がどうなったのか、説明を求めました。","respondent":"大森災害対策担当課長","answer":"区といたしましては、区有地を活用しまして、これまでも東京都の消防団の格納庫整備に協力しています。今後も引き続き協力いたします。","id":"exchange-017"},{"speaker":"つる委員","kind":"提案","question":"３２４ページ、３０５ページ、駅周辺等放置自転車対策事業について伺っていきたいと思います。ヨウコウザクラは下を向いて咲く桜だと伺っておりますけれども、それから、また改めてしっかりとやっていくという決意をしたところですとの意見を述べました。","respondent":"溝口公園課長","answer":"現在、区の庁舎内におきまして、植栽はレンタルで対応したりしています。そういったものについては、引き続きやっていきたいと考えています。","id":"exchange-018"},{"speaker":"つる委員","kind":"意見","question":"関係機関の窓口、そして公園に、花の植栽を増やしていく可能性はあるかと思います。そういったことについて、土木費の中で答えられる範疇でご答弁をお願いいたしますとの意見を述べました。","respondent":"溝口公園課長","answer":"公園の中に、地域の方たちがボランティアとして花を植えたりといった取り組みをしています。そういったものについては、引き続き検討していきたいと考えています。","id":"exchange-019"},{"speaker":"つる委員","kind":"提案","question":"これは一般質問でも確認させていただきましたが、非核平和都市品川宣言の周知も含めてご検討いただくということでありました。私の一般質問の中では、プランターに何かステッカー等を貼ることをご提案申し上げましたけれども、何か検討案があれば説明を求めました。","respondent":"多並道路課長","answer":"東京２０２０大会花いっぱいおもてなしロードの件ですけれども、この実施にあたっては、今、所管する総務課と打ち合わせているところです。大会の関係でいろいろ制限がありますので、そこら辺の表示については、いろいろな関係部署と連携を図って考えていきたいと思っています。","id":"exchange-020"},{"speaker":"つる委員","kind":"確認","question":"駅周辺等放置自転車対策事業に関してですが、１年半前ぐらいでしょうか。区営２６か所で、幼児２人乗り同乗用自転車を駐輪できる台数、幼児２人同乗用自転車が隣り同士できちんと駐輪できるかどうかも確認したいと求めました。","respondent":"古郡交通安全担当課長","answer":"２年前に実施した工事ですが、これは、３０ｃｍのものを４０ｃｍから６０ｃｍにしております。定期利用ですとチャイルドシートのゾーンなどを設置して、利用者にわかりやすくとめていただいているところです。","id":"exchange-021"},{"speaker":"つる委員","kind":"質問","question":"やはり収益なども考えてやらなければいけない部分もあるかと思うのですが、この辺の６０ｃｍ幅以上、隣り同士でしっかりとめられる。そういった収容効率なども含めて、利用しやすさ、その辺の考え方について説明を求めました。","respondent":"古郡交通安全担当課長","answer":"現在も、とめづらいなど、そういったお声を聞いたときには、指定管理者と話し合って、どういったものがいいのかということで対応しています。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問","question":"今、そうしたところがシームレスに対応できるような駐輪対策をお願いしたいなと思います。この辺の対応についても説明を求めました。","respondent":"溝口公園課長","answer":"そういったものについては、引き続き検討していきたいと考えています。公園内の禁止看板ですけれども、いろいろご意見をいただいておりますので、引き続きどのような形がいいのか検討していきたいと考えているところです。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問","question":"この点、いかがでしょうか。お伺いいたします。","respondent":"鈴木都市計画課長","answer":"国民の移動の権利については、その検討の過程でいろいろ議論されましたが、最終的には、国の法律の中では位置づけがされなかったです。","id":"exchange-024"},{"speaker":"おくの委員","kind":"質問・要望","question":"品川区でも同様に１００円と設定して、移動する権利を保障していただきたいと思うのですが、この点はいかがでしょうか。お伺いいたします。","respondent":"鈴木都市計画課長","answer":"あるいは１５０円、１００円、しっかり検討していきたいです。そうしたこともありますので、より多くの方に乗っていただくためにどういう料金設定がいいかというのは、今後しっかり検討していきたいです。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問","question":"ほかの交通網と一緒に、路線バスや鉄道などの総合的な中でコミュニティバスを位置づけていくというおっしゃり方だったと思うのです。そうしますと、先ほど申し上げた方針の中に書いてあったような、あくまでも補完という位置づけで考えたいということなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"これから地域公共交通基本方針の素案という形でお示しすることになりますが、その中では、路線バス、あるいは鉄道を補完するという位置づけです。","id":"exchange-026"},{"speaker":"おくの委員","kind":"質問","question":"あくまでも補完という形、補うという位置づけになるのは、どのような理由からなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"コミュニティバスについては、国からもガイドラインが出ておりますが、基本的には民間のバス路線と競合しない。路線、公共交通網もしっかり充実している中で、やはりコミュニティバスは補完をしていくという位置づけです。","id":"exchange-027"},{"speaker":"おくの委員","kind":"質問・要望","question":"それで、コミュニティバスの場合は、品川区が運営に関わるということで、おのずと視点が違ってくるという利点があると思うのです。やはりその点を考えてやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"わざわざ税金を使うものですから、ぜひしっかりと工夫して導入していただきたいと考えておりますけれども、ご見解はいかがでしょうか。あれから４年経ちましたけれども、そうした民営化のお考えや、また、修繕負担の大きさということについて、どのようにお考えなのか尋ねました。","respondent":"中島防災課長、鈴木都市計画課長、溝口公園課長","answer":"この消火隊に関しても、当然、地域特性に応じた対応が必要だと考えています。それらのものを総合的に活用して… あるいは事業所との連携など、今後、検討していきたいです。で、民間のバス事業者にかねてからバス路線を走らせていただきたいということを打診しておりま… そういったことも総合的にいろいろ考えながら、今後の水族館を検討していきたいというところで予算を計上させていただいているところです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"本当に難しい問題かと思いますけれども、今の良さを継続しながら、総合的に今後とも考慮していっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"３４１ページ、３４３ページの防災費、名簿作成経費について伺います。この事業内容２の対象地域をどのように選ぶのか尋ねました。","respondent":"鈴木都市計画課長","answer":"来年度は、またしっかり検討して、この２地点になるのか、ほかの地点になるのかはこれからですが、進めていきたいです。お声が集中する、来年度、測定器を３か所に設置していくかというのはしっかり検討していかなければいけないところだと思います。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望にとどめておきますので、今後、しっかりやってほしいと求めました。次に、３４３ページの避難行動要支援者経費、名簿作成経費について伺います。","respondent":"中島防災課長","answer":"避難行動要支援者名簿についてのご質問ですが、こちらは、平成２５年から災害対策基本法で作成が義務づけられています。要介護度が１から５の認定を受けた高齢の方で、視覚障害の総合等級１から３に該当する方、区が避難誘導に支援が必要と判断する方となっております。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"そもそも対象を身体障害者に絞った理由と、結果として、知的障害者の方に配った経緯について伺いたいと思います。それが混乱を招いていて、どうしてそのようになったのでしょうかということを伺いたいと思います。","respondent":"中島防災課長","answer":"先ほど申し上げた要介護度１から５、やはり避難行動に支援が必要だと思われる方ということで、そのような方を対象として考えてきたところです。アンケート用紙の表記につきましては、工夫が必要だと思いますので、それについては考えていきたいと思います。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"せっかくよい判断をしたのに、何か１枚つけるなどという配慮はできなかったのでしょうか。その辺のことがとても残念なので、今後、何かフォローをしたほうがいいと思うのですけれども、お考えを伺いたいと思います。","respondent":"中島防災課長","answer":"そういうところの機会を捉えまして、どのような形のご案内がいいかというのは考えていく必要があるかなと考えております。この送付に対してお問い合わせをいただいているところもありますので、そこについては、適切に対応していきたいと考えています。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのような資料は、今後作成されるのでしょうか。居住支援協議会向けの資料としてだけでなく、一般にも提供される資料として見やすいものがあればいいと思うのですが、いかがか尋ねました。","respondent":"森住宅課長","answer":"区としても、そういった具体的な支援を行っていく中で、その取り組みが一目でわかるようなパンフレットの必要性の認識はしています。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"１つの建物の所有者で、１階は誰も使っていなくて、それは空き家に該当するのでしょうか。伺います。","respondent":"森住宅課長","answer":"子ども家庭支援課、地域活動課や生活福祉課など、いろいろなところとどのような事業ができるのかということを検討しています。何も使っていない建物という定義ですので、そういった１部屋を貸したいということについては、今のところ考えているものではございません。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"整備基本計画策定等委託とありますが、整備基本計画というのは、どのレベルの計画でしょうか。地域の人たちの要望を聞き取るようなことも含んでの委託か尋ねました。","respondent":"溝口公園課長","answer":"来年ですけれども、新設の公園になりますので、基本計画という形で、地域の方たちに意見を聞いてやっていきたいと考えております。委託事業者の選定につきましては、今回、特に特殊な公園ではありませんので、一般競争入札で事業者を決めていきたいと考えているところです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"一般競争入札ということなのですが、仕様書の中身は区としての要望を盛り込むということで、しっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"松本委員","kind":"確認","question":"３４３ページ、３４５ページ、防災用新タブレット導入等経費について伺います。屋外広告物取締事務についてですが、取り締まりの中身というのはどういうものか、確認ですけれども、お伺いできればと思います。","respondent":"今井土木管理課長","answer":"それから、しながわ景観美化隊という除却協力をしていただいている区民のボランティアの方に除却していただいているもの、このような形で進めております。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"根拠となっているのは、東京都の屋外広告物条例かと思います。色彩、看板の表示内容については、屋外広告物条例では規制されていないという理解でよろしいか尋ねました。","respondent":"今井土木管理課長","answer":"取り去っているものは、電柱にある広告物や路上に置いてある置き看板などを取り去っているところがあります。赤色の掲示物等、デジタルサイネージなどに関しては取り締まりといいますか、規制の対象になっている地域もあります。","id":"exchange-040"},{"speaker":"松本委員","kind":"確認","question":"なぜこういった質問をさせていただいているかといいますと、昨年、千代田区の秋葉原で成人向けゲームの看板が撤去されたという事例がありました。そこで、確認なのですけれども、品川区においては、屋外広告物の表現内容を規制するような独自の条例は特にないという理解でよろしいか尋ねました。","respondent":"今井土木管理課長","answer":"私ども、土木管理課が所管しております屋外広告物、東京都の事業委託を受けております条例等につきましては、内容等にそのような規制はございません。委員ご指摘のとおり、そのような事例がありましたら、庁内連携をして対応するものと認識しております。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"第１８条の２で、有害広告物に対する措置を命ずるには、この審議会の意見を聞くことになっているということであります。先ほど、自治会・町会というお話でしたけれども、区が独自に内容面で広告主等に指導することはないと理解してよろしいか尋ねました。","respondent":"今井土木管理課長","answer":"こちら、東京都の屋外広告物条例の事業委任でやっております。国民の政治活動の自由その他、東京都と連携して、品川区としても対応することとなろうと思います。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"私も、Ｕｂｅｒ Ｅａｔｓが使っているのをよく見かけており、先ほどはマナーの点からのご質問があったかと思うのです。そのあたり、問題意識として、現状このままでいいのかというところをご回答ほしいと求めました。","respondent":"今井土木管理課長","answer":"都心１０区では法人利用、やはり、法人利用もその地域においては重要なことになっております。そして、区民の皆様、全てが使えるようなニーズを確認していきたいと考えています。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問","question":"２３区、東京都が所管しているということはわかっているのですけれども、歳末警戒などで謝礼が出ているので少しお伺いしたいのです。もし機会があれば、こういう健康上の配慮についてご指摘ほしいと求めましたが、いかがか尋ねました。","respondent":"大森災害対策担当課長","answer":"ご意見等を踏まえまして、消防署としっかり連携しまして、意見も伝えてまいります。","id":"exchange-044"},{"speaker":"小芝委員","kind":"質問","question":"３４３ページの消防団運営費について、３１５ページ、立会川溢水防止板設置工事等について質問いたします。品川区で災害時に断水が起きた場合、地域住民の方は生活用水をいかにして確保するのか尋ねました。","respondent":"中島防災課長","answer":"災害時における生活用水の考えについてお答えいたします。プール等の水もありますので、ろ過器を使用するなどで確保できるかなと考えております。","id":"exchange-045"},{"speaker":"小芝委員","kind":"質問・要望","question":"地域では、大分前から、その井戸を災害時に防災井戸として活用してもらいたいという声を伺っておりました。井戸の前に、洗濯やトイレで使う水を求める長蛇の列ができたのも事実です。","respondent":"中島防災課長","answer":"生活衛生課で宅地に水道が設置されていないお宅で、井戸水のみを利用されているお宅が、たしか１２軒ほどあると聞いております。区としては、恐らくそれぐらいを把握しているのではないかと考えています。","id":"exchange-046"},{"speaker":"小芝委員","kind":"質問","question":"私もこの地域を回りまして、１つの町会の中で３つ、４つあるところもありますので、実際、井戸自体はもっと多いのかなという印象があります。これまでの間で研究されてきたことの成果と、また、今後に向けた取り組みを教えてもらえますか尋ねました。","respondent":"中島防災課長","answer":"どのような形で対応ができるかというのは、やはりそのような災害の事例での活用も踏まえまして、井戸の重要性は認識しています。研究については、引き続き続けていきたいと思います。","id":"exchange-047"},{"speaker":"小芝委員","kind":"質問","question":"そこで、品川区のフリーＷｉ－Ｆｉの利用可能地域を、区内消防団の分団の詰所に広げていただけるようにお願いしたいです。あくまでも消防団の管轄は東京都ですので、なかなか苦しいとは思うのですけれども、ぜひご見解をお聞かせほしいと求めました。","respondent":"大森災害対策担当課長","answer":"大井消防団第四分団がある大井中央公園につきましては、現状では整備されていないというところも認識しております。それぞれのニーズを確認しながら、整備について考えてまいりたいと思います。","id":"exchange-048"},{"speaker":"小芝委員","kind":"質問","question":"来年度の予算でも、この工事を進めていくということですが、具体的にどのあたりに設置を広げていくのでしょうか。、答えるよう求めました。","respondent":"松本河川下水道課長","answer":"来年度の溢水防止板の設置についてですが、国道１５号線から浜川橋までの左岸側と、弁天橋から河口までの右岸側に溢水防止板を設置する予定としております。","id":"exchange-049"},{"speaker":"せお委員","kind":"質問","question":"３２７ページ、公園・児童遊園整備費、３１９ページ、やさしいまちづくり整備費についてお聞きします。水飲み場やベンチなども、誰もが楽しめる公園にはなりませんが、そのような部分での改修はこれから行っていく予定はありますか尋ねました。","respondent":"溝口公園課長","answer":"委員ご指摘の水飲み場ですとか、またそこまでのアクセスルート、そういったもののバリアフリー化が必要だというふうに考えております。２つの公園について設計、整備を予定しておりまして、１つの公園の改修に向けた設計を行っていく予定をしています。","id":"exchange-050"},{"speaker":"せお委員","kind":"質問・要望","question":"さて、インクルーシブ公園に関しては、先日の都議会の一般質問の答弁にて、区市町村に対する補助制度の創設についても検討していくとありました。大井坂下公園で終わりではなく、機会があれば、インクルーシブ公園の整備を進めてほしいと求めましたが、見解を説明するよう求めました。","respondent":"溝口公園課長","answer":"そういった中で、インクルーシブ、ユニバーサルデザイン、そういったところの視点も、あわせていただいているところです。そういったものは今後、大井坂下公園にとどまらず、今後の公園整備の改修に活かしていきたいというふうに考えているところです。","id":"exchange-051"},{"speaker":"せお委員","kind":"意見","question":"その利用方針で示された土地利用の考え方の２番目に、「社会福祉機能の充実と、にぎわいと交流とが生まれる生活空間の形成」とあります。そこで、品川区として、都に積極的に、区民のお声や品川区の状況、そして整合性をお伝えしてほしいと考えますが、見解を説明するよう求めました。","respondent":"溝口公園課長","answer":"今後の整備にあたりましては、地域のご要望も区に寄せられているところではあります。そういったものは東京都にしっかり伝えながら、整備していってもらうように働きかけていきたいというふうに考えているところです。","id":"exchange-052"},{"speaker":"せお委員","kind":"提案","question":"都の場所というか持ち物とはいえ、品川区内でありますので、積極的に提案などをお願いいたします。乗り換えの際に使用するエレベーターを設置していただきたいと考えますが、鉄道会社のほうに要望は出されておりますか尋ねました。","respondent":"鈴木都市計画課長","answer":"区としましても、ＪＲに働きかけを行って、これまでもエレベーターの設置を要望してきたところです。しかしながら、非常に狭いところでの設置ということで、なかなか構造的に難しいと、ＪＲからは回答をいただいているところです。","id":"exchange-053"},{"speaker":"せお委員","kind":"質問","question":"ＪＲ五反田駅のエレベーターのように、品川区として財政的支援をお願いしたいと思うのですが、その点はいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"ＪＲ目黒駅への乗り継ぎのためのエレベーターの設置については、構造的に難しいという回答はいただいてありますが、次に取り組むべきものとして。区としては、引き続きしっかりした助成制度、促進策をもって、ＪＲに強く働きかけを行っていきたいです。","id":"exchange-054"},{"speaker":"せお委員","kind":"意見","question":"ぜひ、財政的支援をしていただきながら。オリンピックには間に合わないですが、やはりとても必要なことかと思いますので、ぜひ支援をお願いしたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"確認","question":"３４３ページ、そして時間があれば３４５ページ、り災証明書発行計画案作成経費について伺います。もしそういう方針が来ているのであれば、受注者の意向というものは確認をされたのかどうか、説明を求めました。","respondent":"多並道路課長","answer":"直ちに受注者のほうに、工事の中止等の対応がないかという意向を確認させていただいたところです。その他の工事についても、確認できる範囲で確認した限りでは、今のところはないです。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問・要望","question":"業界の方にお話を伺うと、受注ストップをしていたりとか、あとはもう納品の延期がなされている状況があると。予備費なのかわかりませんけれども、区には、やはりそういう体制もとっていただきたいという趣旨で質問いたします。","respondent":"多並道路課長","answer":"３月末で１回終わって、そのときに、新たな補正予算等を組むような方法が考えられると思います。財政課であったり、その必要な措置について協議しながら、適切に進めてまいりたいと思っているところです。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"提案","question":"昨年の第３回定例会の一般質問で、専門部署の設置をご提案したところ、専門担当部署の設置について検討していくということでした。どのような部署、人員体制をお考えになるのか、またどういったものを担当されるのか、お答えのできる範囲で教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"新ルート計画案が公表されて以降の対応としましては、意見等の全般的なところについては、都市計画課で所管してまいりました。区としてしっかり組織を一元化していきたいと今考えているところでございまして、それから担当１名という形での新設一元化を考えているです。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"提案","question":"そのときのご提案の趣旨として、重点的に求めていくためにということで、新たな部署が必要ではないかというご提案でございました。確認ですが、これは品川区議会の決議でもありますけれども、取り組みを粘り強く求めていただくということでよろしいか尋ねました。","respondent":"鈴木都市計画課長","answer":"騒音も含めてまさに一元化をして、区民の声をしっかりお聞きして、それを国のほうに強く伝えると。あるいは周辺の関係する区とも連携しながら、区がこれまで求めてきた固定化しない取り組み、この組織でしっかりとやっていくものです。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"提案","question":"これも昨年の一般質問の中で、個人情報保護について、区としてそのひな形を示す必要があるというご提案をさせていただきました。これを入れ込んだほうがいいのではないでしょうかというところで、今回、何回か質問をさせていただいているのですとの意見を述べました。","respondent":"中島防災課長","answer":"具体的にどのように反映していくかというところは、避難行動要支援者の支援の補助事業を来年度までの５か年計画で進めているところです。その際当然、防災区民組織の母体は町会・自治会となりますので、地域活動課とも連携を図りながら検討を進めてまいりたいと思います。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問","question":"ただ、そのことを想定して、想定外のことを想定するのがやはり災害対策ですので、お互いに何ができて何ができないのか。倒壊しかけた建物の判定なんていうことは行政書士には無理ですから、現場に行ってその方からお話をお伺いして、いかがか尋ねました。","respondent":"中島防災課長","answer":"委員ご指摘のとおり、行政書士の方には相談業務等での協力を期待しています。今回の体制の中で、そのあたりのところも検討を進めてまいりたいと思います。","id":"exchange-061"},{"speaker":"くにば委員","kind":"提案","question":"３年分のさまざまな委員会で防災行政無線について取り上げた議事録を全て読み返しまして、それに対する答弁やその後の報告事項等を再確認しました。５点目、ＦＭしながわをアプリで聴取できるようにしてほしいとの提案に対して、インターネットサイマルラジオでの配信を開始との意見を述べました。","respondent":"中島防災課長","answer":"デジタル化へ完全移行しますと、旧来のアナログ対応の防災ラジオが使えなくなることから、これについては引き続き検討してまいりたいと思います。","id":"exchange-062"},{"speaker":"くにば委員","kind":"提案","question":"これから、防災行政無線について私からご提案申し上げます。このシステムについて把握なさっていたか、またサービス内容をお聞きになられてのご所見をお伺いしますとの意見を述べました。","respondent":"中島防災課長","answer":"今、委員からご紹介いただきましたものにつきましては、すみません、私のほうはちょっと存じ上げておりません。ただ、さまざまなツールを活用していくというところは、常に考えているところですので、今、ご提案のところについても調べていきたいと考えています。","id":"exchange-063"},{"speaker":"くにば委員","kind":"質問・要望","question":"こちらは、０３－３７７７－２２９２に電話をすれば、防災行政無線でアナウンスした内容を録音された音声にてそのまま聞くことができます。こちらに関して、現状の課題として、例えば何があるか、お聞かせ願えますか尋ねました。","respondent":"中島防災課長","answer":"広報広聴課のほうで運用、設置しているところでありますが、防災上運用しておりますので私のほうからお答えします。そのような中で今、運用しています。","id":"exchange-064"},{"speaker":"くにば委員","kind":"提案","question":"こちらについては、例えば一つご提案なのですけれども、先ほど電話をして確認したのですけれども、繰り返し音声が流れているのです。こちらに関して、運用上の問題なので、費用がかからず実現できる可能性はあると思うのですけれども、ご所見を説明するよう求めました。","respondent":"中島防災課長","answer":"委員ご指摘のような場面というのはやはり、立会川、目黒川とかの水位が上がって、サイレン吹鳴とか、そういうものになります。災害対応の緊迫した状況ですので、今のような対応ができるかどうかというのは、一つの考え方として捉えさせていただきたいと思います。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問","question":"３４３ページ、防災訓練経費に関連して、水害対策と、首都直下型大震災の対策についてそれぞれ伺いたいと思います。こうした中、浸水ハザードマップの浸水予測区域内にある自主避難施設の開設は危険ではないかと思うのですけれども、まずその点を伺いたいと思います。","respondent":"中島防災課長","answer":"その場面、場面の考え方の中で、あえてそこに開設するということではありません。そういうところは今後の開設計画の中で、今回、風水害の検討委託もしていますので、包括的に考えていきたいと思います。","id":"exchange-066"},{"speaker":"中塚委員","kind":"確認","question":"場面、場面でということですけれども、つまりは水害の際、浸水ハザードマップの浸水予測区域にある地域には、自主避難施設は開設しないという方向で検討されているのかどうか、確認したいと求めました。","respondent":"中島防災課長","answer":"基本的な考え方としましては、浸水想定区域内には開設しないというところで考えていきたいと思います。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"今年の夏はこの地域では開設しないというのであれば、そのことをあらかじめ住民に説明することが必要ではないかというのが１点伺いたいことです。あわせて、ではどこなんだという情報も、あらかじめつくっておく必要があると思いますので、その点もお伺いしたいと思います。","respondent":"中島防災課長","answer":"やはり地域の方々の避難の考え方というところ、距離等もありますので、なかなかあらかじめ開設しないという周知が難しいところです。やはりそういう考え方を一定程度整理して、自主避難施設および避難所の考え方も整理して、しっかり努めてまいりたいと思います。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"ケース・バイ・ケースとおっしゃいますけれども、実際台風の進路がどうなって、どこでどう雨が降ってどうなるかというのはわからないわけです。そのかわり、この地域の方はこちらになりますよと、そういう計画をしっかりつくることが必要ではないかと思いますが、改めていかがか尋ねました。","respondent":"中島防災課長","answer":"それと、当然そういう規模の災害が想定される場合には開設することはできないと考えるところです。一概にちょっと、この段階でなかなか開設場所というのはあらかじめ決めるという回答は難しいところですけれど、計画に努めてまいりたいと思います。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"それもどういう計画なのかよくわからないのですけれども、さまざまな意見を集めながら整理していただきたいと、これは要望しておきたいと思います。この通知に基づく計画を実施するための計画や備蓄、訓練は整っているのか、伺いたいと思います。","respondent":"中島防災課長","answer":"ただ、発災初日から、すぐに長期の避難生活を想定した対応というのは、なかなかできるものではございません。長期の避難生活に備えた取り組みについては、これまでも続けてまいりましたし、これからも続けてまいりたいと考えています。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問","question":"の準備をしなければいけないと思うのですけれども、現状において整っているのかを改めて伺いたいと思います。なぜならば、さらに計画と訓練を強化しなければいけないと私は思っているのですけれども、改めていかがか尋ねました。","respondent":"中島防災課長","answer":"３日分の食料の備蓄にしっかり努めていたり、またトイレなど本当に早急に必要なものについては、充実に努めております。短期的な対応と長期的な対応と、優先順位を決めて、しっかりと対応しています。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問","question":"このパーテーションは何個必要だと考えているのか、簡易ベッドは何個必要だと考えているのか、その想定数を伺いたいと思います。輸送をするという計画も、当然必要になってくるかと思いますが、そこはどのようになっているのか尋ねました。","respondent":"中島防災課長","answer":"国から支援を受けるもの、協定等で対応するもの、内閣府の通知に基づいた対応をしていくことが必要ではないかなというふうに考えておりますので。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"このパーテーションと簡易ベッドは風水害用であって、首都直下型大震災の対応ではないということなのか、確認させてほしいと求めました。首都直下型大震災も想定して数えるべきだと思うのですけれども、簡易ベッドは何個必要だと考えているのか、伺いたいと思います。","respondent":"中島防災課長","answer":"あくまで今回購入するパーテーションと簡易ベッドの主たる目的は風水害対応、風水害の際に自宅が失われた方の避難所生活を支援するためです。国および都または協定等からの支援、長期的な避難所生活に対応するように、計画をしています。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、高齢者、障害者などの支援について１点伺いたいと思います。避難所生活中の高齢者、障害がある方などの支援計画をしっかりと位置づけて進めるべきだと思いますが、いかがか尋ねました。","respondent":"中島防災課長","answer":"障害のある方の支援ということだと思いますが、災害時の見守りとか、そういうところにも活用できるものです。","id":"exchange-074"},{"speaker":"木村委員","kind":"質問","question":"私から、３１９ページ中段にありますけれども、やさしいまちづくり整備費の中の、しながわお休み石修繕費等、６２８万円余からの質問をいたします。お聞きいたしますけれども、そういうことが過去あるからこの予算を組んでいるのかどうか、説明を求めました。","respondent":"鈴木都市計画課長","answer":"その木造の座面を取り換えるということを行っていたのですが、やはり木造ということで、非常にこの傷みが早いと。計画的にこの座面を、木目調の合成樹脂の座面に取り換えるということで、来年度の予算計上をしています。","id":"exchange-075"},{"speaker":"木村委員","kind":"質問","question":"全て石でできているものと思っておりましたので、人が故意的に壊さない限りは壊れないだろうということでこのような質問をいたしました。全国的にこのお休み石というものは、あまり有名ではありませんけれども、これはどういうきっかけでつくることになったのか尋ねました。","respondent":"鈴木都市計画課長","answer":"この事業は平成１０年から開始しておりますが、ベンチ等を整備していただけないかという区民の方からのお声がきっかけで、事業を開始したと。平成１０年から行っているわけですが、景観的にもいい形のものを、ということで取り組んでいるものです。","id":"exchange-076"},{"speaker":"木村委員","kind":"質問","question":"これから行われるであろうオリンピック・パラリンピックで来日する多くの海外の方々の目には、このお休み石というのがどのように映るのか。このデザインを見て、どのような品川区を感じるとお思いか尋ねました。","respondent":"鈴木都市計画課長","answer":"それから木目調の木造の座面、全体的に見ますと、非常に日本的なデザインをしています。品川区、外国の方に来ていただいて、非常に日本的な部分を感じて実際に座っていただけるのではないかなというふうに感じてあります。","id":"exchange-077"},{"speaker":"木村委員","kind":"質問","question":"次に、公園管理費で、３２７ページの中ほどにありますミスト噴水設置工事１,０００万円から質問をいたします。噴水の稼働時期、何月から何月、そして時間的には何時から何時までということで行っているのか尋ねました。","respondent":"溝口公園課長","answer":"昨年度から実施しておりまして、実際、夏場の梅雨の明けた時期というのを一つの目途にオープンして、９月いっぱいまでとしています。実際運用は１１時から１６時４５分まで、毎時の時間と３０分と、一応１５分間隔でミスト噴水が出るような形の運用をしています。","id":"exchange-078"},{"speaker":"木村委員","kind":"意見","question":"ただ、微細な霧を噴出するだけに、結構、洋服が濡れるのではないかということが大変心配されるわけですけれども、長時間利用して大丈夫なのかどうか。そして高齢者が多く集まりそうな気がするのですけれども、年代的には幾つぐらいの方々が利用されるのか、説明を求めました。","respondent":"溝口公園課長","answer":"公園に設置しているものは、多少濡れるかもしれませんけれど通常のミスト、そういったものでやっていきたいというふうに考えております。さまざまな方が暑いときにミストのところに行って涼んだり、そういった光景が見られているところです。","id":"exchange-079"},{"speaker":"木村委員","kind":"質問","question":"２６８か所の公園があり、トイレのある公園がその約半分の１２８か所であることを考えても、それをどういうところにつけるのか。お聞かせほしいと求めました。","respondent":"溝口公園課長","answer":"今後、公園内でのミストの設置の関係ですと、一応来年度予算で、オリンピックの開催時までということで、５公園、しながわ区民公園等の大きな公園を対象にしておりますが、ミストを設置していきたいというふうに考えているところです。","id":"exchange-080"},{"speaker":"木村委員","kind":"質問","question":"今１か所に設置をされているということでありますから、今５か所と言いましたから、次年度は４か所予定をしているということになるのでしょうか。そして、先ほども言いましたけれども、年代的にはやはり高齢者になるのか、これも最後にもう一度説明を求めました。","respondent":"溝口公園課長","answer":"今回もう既に設置しているところと合わせて、来年度中に６か所、設置していこうというふうに考えているところです。暑さ対策というのも必要だと考えていますので、今設置したところの効果等を十分検証しながら検討していきたいというふうに考えているところです。","id":"exchange-081"},{"speaker":"西村委員","kind":"質問","question":"３４５ページ、３４７ページ、オリンピック・パラリンピックの災害時対応について伺わせてください。初めに、防災用新タブレット導入等経費ですが、今、何町会に配付されていて、うち何台が差し替えられるのか、改めて説明を求めました。","respondent":"中島防災課長","answer":"防災区民組織が２００、そちらを２０程度、区のほうで保有するということで計２５０台を購入する予定です。これの差分については回収という形になる予定です。","id":"exchange-082"},{"speaker":"西村委員","kind":"質問","question":"これで全町会・自治会に配付されるという認識でよろしいか尋ねました。","respondent":"中島防災課長","answer":"説明が足りず申しわけございません。少し老朽化等がございましたので、入れ替えをするという中で、今回は町会・自治会、あと区のほうに配備するということで考えてあります。","id":"exchange-083","title":"町会・自治会支援"},{"speaker":"西村委員","kind":"意見","question":"実際町会・自治会でどれだけ使いこなせていただいているのか、バージョンアップしていただいてもそのあたりが少々気になっております。実際にどのように浸透させていっているのか、また課題がありましたら説明を求めました。","respondent":"中島防災課長","answer":"少し動作が遅かったり、ちょっとケーブルテレビの回線の関係で、自宅から持ち出せないとかといった制約がございました。そういう中で活用範囲を広げる、なかなか初めはちょっと操作が難しいとは思うのですけれど、そのあたりは丁寧に説明をさせていただきたいと思います。","id":"exchange-084","title":"町会・自治会支援"},{"speaker":"西村委員","kind":"質問・要望","question":"せっかく配付していただきますので、実用性のあるものにしていただきたいと思っています。防災課のほうでログインの確認をするなど、もう既に取り組んでおられることもあるかもしれませんが、何か取り組みがございましたら説明を求めました。","respondent":"中島防災課長","answer":"来年度は導入の初年度になりますので、ちょっとどこまで対応ができるかはあれですが、ある程度活用するというのがやはり一番有効かと思いますので、そういうところを考えて、日常的にも使えるように考えていきたいと思います。","id":"exchange-085"},{"speaker":"西村委員","kind":"質問・要望","question":"テレビやインターネットで自分が住んでいる地域の震度を確認する、津波警報が出ていないか確認する、隣り近所の人と無事を確認する。ご見解を説明するよう求めました。","respondent":"中島防災課長","answer":"今回導入するスマートフォンアプリ、民間のものを活用するのは主に、防災行政無線の補完というところを考えて導入させていただきたいと考えています。","id":"exchange-086"},{"speaker":"西村委員","kind":"質問","question":"次に、備蓄物資購入に関連しまして、家庭での備蓄について伺ってまいります。循環させるということですけれども、今、区内における自助のきっかけとなるような情報提供はどのようにされていらっしゃるか尋ねました。","respondent":"中島防災課長","answer":"ローリングストックはやはり自助、家庭での在宅避難の重要な一つと考えております。区のホームページでありますとか、そういうところも活用して、引き続きこちらの啓発に努めてまいりたいと思います。","id":"exchange-087"},{"speaker":"西村委員","kind":"質問","question":"最後に、公園・児童遊園費について伺ってまいります。区内のボール遊びができる公園というふうに絞って考えますと、どれくらいあるか尋ねました。","respondent":"溝口公園課長","answer":"初めに、品川区の管理している公園の中で、キャッチボール、ボール遊びができる公園は、２２公園です。これはほかの公園利用者等との事故等を防ぐ観点で、そこを指定して、ボール遊びをしていただいているところです。","id":"exchange-088"},{"speaker":"西村委員","kind":"意見","question":"この２２という数字が多いのか少ないのか、ちょっと不勉強でわかりかねるのですが、空白地域があるのかどうかと、また、ある場合にはその補完の考え方を区はどのように考えていらっしゃるのか、説明を求めました。","respondent":"溝口公園課長","answer":"ボール遊びですが、区内２６８か所の公園がある中の２２か所となっていますので、当然地域の中で格差が出てきているというのは感じているところです。","id":"exchange-089"},{"speaker":"西村委員","kind":"意見","question":"空き地が自由に使えるような状況ではなくなってきている昨今ですので、ぜひとも引き続き子どもたちの声を聞いていただきながら、公園の整備をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"横山委員","kind":"質問","question":"１点目に、この品川区におきまして、東日本大震災から現在までどのくらい高まったのでしょうか。午前中につる委員の質問にもありましたが、しながわ中央公園の花壇の維持管理につきましてどのようになっていますか尋ねました。","respondent":"中島防災課長、溝口公園課長、多並道路課長","answer":"そういうものを東日本大震災以降に実施している中で、指令情報部という本部訓練も含めまして、しっかり行っております。昨年度は台風がございましたので… ３６５日適正な管理をしていきたいということで、植栽、そういったものの管理を含めて一つの事業者に委託しています。そういったものも兼ねて… これは東京２０２０大会の開催にあたりまして、こちらの道路にプランター花壇を設置して、色取りどりの草花や潤いある華やかな演出をしようという事業です。","id":"exchange-091"},{"speaker":"横山委員","kind":"質問・要望","question":"危機管理力というのもあわせてさらに高めていただきたいというふうに思っておりますので、こちらは要望でお伝えします。ガーデナーズブログみたいなものがありますということを掲示されていたりですとか、このあたり、もうちょっと詳しく教えていただけないか尋ねました。","respondent":"溝口公園課長","answer":"委員のお話にあったように、花の種類を多く植えていたりですとか、また、花の名前を入れたりとか、そういった解説も一緒にあわせてやる。花摘みとかそういう日々の管理というのを徹底することによって、皆さんに楽しんでいただける花壇ができているという形になっているものです。","id":"exchange-092"},{"speaker":"横山委員","kind":"意見","question":"大体で大丈夫です。その種類では多様性であったり、また維持管理のところであったり、そういったところを少し説明を求めました。","respondent":"溝口公園課長","answer":"やはり一つの考え方としては、しながわ中央公園ですとまさにこの時期、きれいな花が咲いている木があったりするのが見られると思います。皆さんに快適な公園を過ごしていただくことができませんので、維持管理といったものにも力を入れて取り組んできているところです。","id":"exchange-093"},{"speaker":"横山委員","kind":"意見","question":"区の職員の方々ですとか、品川区の緑にいろいろ手入れをしていただいていて、本当に感謝をしております。さらにおもてなしというところで、ぜひお願いしたいなと思うのですけれども、維持管理の部分とかでの連携について説明を求めました。","respondent":"多並道路課長","answer":"東京２０２０大会花いっぱいおもてなしロード事業につきましては、今ありましたしながわ中央公園における花壇の手入れの状況だとかそのようなノウハウはよく連携を図りながら、一緒に連携して進めていきたいと思っているところです。","id":"exchange-094"},{"speaker":"横山委員","kind":"意見","question":"区が持っている知識ですとか、今までの経験というのを活かしながら進めていってほしいと求めましたが、最後に一言お願いしますとの意見を述べました。","respondent":"多並道路課長","answer":"今回の花壇の事業が一つのきっかけとなりまして、今後いろいろ、花壇だけではなくて、こういう緑化施策全体についても波及できるように、レガシーとして捉えていただければいいかなと思っているところです。","id":"exchange-095"},{"speaker":"塚本委員","kind":"質問・要望","question":"３２５ページ、いい道具があるからすぐに置き換えるというようなことができないということも、この間の議論で伺っているところです。今後こういったものを区内の各公園の砂場に展開していってほしいと、できれば全てにというぐらいの思いはありますけれども、お伺いしたいと思います。","respondent":"溝口公園課長","answer":"委員ご質問の設置箇所数なのですけれど、パーゴラの設置数までは全体把握をしていないのですが、大体９５ほどの公園に砂場が設けられているものです。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問・要望","question":"この剪定の時期に関して、この樹木剪定の時期は、しっかりと考慮されてやられているのかというところをちょっと確認したいというのが一つと。新たな木陰をいっぱいつくって、現在ある公園に植樹していく、考え方としてどういうふうに思っていらっしゃるのかをお聞かせほしいと求めました。","respondent":"溝口公園課長","answer":"こういったものの配置も含めてしっかり検討ができるというのと、子どもたちが安全に遊べるようにという、その配慮を求められているところです。配置を考えて設置できるのですが、砂場の上に設置しようとしたときに、公園管理者としてはやりたくてもできないところもあります。","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問・要望","question":"こういった倒木について、しっかり公園、道路等、今後も再発防止という意味では管理をしていっていただきたいと思うのです。こういった木が倒れるということの危険性、十分に考慮されるような部分というのはあるのでしょうかというところでの確認です。","respondent":"森住宅課長","answer":"特定空き家について、木が大分大きくなっていることのみで判断するということは、なかなか難しいかなと考えています。樹木がかなり成長して、近隣の方々が不安に思っているというところも、当然大きな検討要因になってくると思います。","id":"exchange-098"},{"speaker":"塚本委員","kind":"意見","question":"これは、西品川一丁目が対象となっていて、平成２９年度から予算がついて始まっているかと思います。これまで、これまでこの地域における防災上の課題としてどういったことが挙げられているのか、お知らせくださいとの意見を述べました。","respondent":"高梨木密整備推進課長","answer":"気密性が高い西品川一丁目は、今ご案内がありましたとおり、平成２９年度から防災まちづくりの検討等を行ってまいりました。今年度は、そういった検討をお知らせするとともに、地域の防災まちづくりへの機運の醸成といったところを取り組んできているところです。","id":"exchange-099"},{"speaker":"塚本委員","kind":"質問・要望","question":"区としてのまちづくりの方向性というものをそろそろ示していくような時期に来ているのではないかというふうにも思っております。今後は、どういう取り組みが想定されるのかをお聞かせほしいと求めました。","respondent":"高梨木密整備推進課長","answer":"東京都から令和３年度以降となる新たな防災まちづくりの計画であります、東京都防災都市づくり推進計画の基本方針の案が示されました。","id":"exchange-100"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３３５ページ、品川シェルター設置助成、３３７ページ、コンクリートブロック塀等安全化支援事業についてお伺いいたします。最初に３３５ページ、品川シェルター設置助成について、質問させていただきたいと考えています。","respondent":"長尾建築課長","answer":"相談件数につきましては、今年度で言いますと、年度当初に２件ほどございました。そのうちの１件が今年度実績としていますが、うち１件につきましてはまだ実績には結びついていない状況です。","id":"exchange-101"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"しかし、これは居ながらにして約１日で完成するということで、自己負担は多分ないのかなと思っています。令和２年度も５件に対して２５０万円余ということで、今後の区の考え方について、お知らせほしいと求めました。","respondent":"長尾建築課長","answer":"品川シェルターにつきましては、建築課で耐震化支援事業の中の一つとして、これまで取り組んでまいりました。命を守る空間を確保できる支援策をご準備しておりますので、耐震化支援事業をお伝えするとともに、ご案内していきたいと考えております。","id":"exchange-102"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして３３７ページ、コンクリートブロック塀等安全化支援事業についてお伺いします。その後、このチラシの問い合わせ等々があったのかどうかということをまず示すよう求めました。","respondent":"長尾建築課長","answer":"昨年度行いましたコンクリートブロック塀に関しての基礎調査の中で、ポスティングを全て行ったところです。ポスティングを行いまして、その後ですけれども、反響が一定程度ございまして、毎日１０件前後ぐらいお問い合わせをいただいているところです。","id":"exchange-103"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"何と言うのですか、対象にならないの、というご相談をいただきました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"のだて委員","kind":"確認","question":"２月２日から１２日まで実機飛行確認が行われ、品川区の上を飛行機がひっきりなしに飛んできて、区内にも衝撃が走りました。想定以上の騒音だと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"著しく上回る結果が出た場合については、原因究明をしっかり行っていく、また必要に応じて新たな対策を検討していくというものです。７機のうち何機が８０デシベルを超えたかというのは、全体からすると非常に少ない結果だったという受けとめです。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"想定以上の騒音がやはり発生しているということは事実だと思いますので、そこはしっかりと認識をしてほしいと求めました。その今回の認識を改めていただきたいということで、さらに大きな騒音が発生するということだと思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"さらにその騒音値が想定よりも超えてくるということについての認識のお尋ねですが、国がその結果について精査中で、これから公表するです。この精査の結果についてはしっかり注視していきたいです。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、国や都、区によって測定場所が７か所設けられていますけれども、距離があって、新ルート直下という感じがしないのです。大井町などの新ルート直下の場所にも、測定局の設置をすべきだと考えますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"今回区内３か所に測定局を設置して、２か所設置をして、ご指摘のとおりです。来年度設置にあたっては、しっかり測定できるところを検討して設置していきたいということは、基本的に当然変わりはございません。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"この新ルート実施にあたって、騒音軽減のためとして、降下角度が３.５度の急角度にされました。この急角度のルートにより、どれだけ音が小さくなったのか、騒音軽減の効果はあったのか、伺います。","respondent":"鈴木都市計画課長","answer":"そのうちの６日間が荒天時ということで、３度を超える３.５度の角度で実際行われたわけですが、その結果をしっかり待ちたいです。ただ、やはり高度が上がった分については、総体的には、３度、実際３度は１日だけでしたが、効果はあったのではないかです。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"世界約１２０か国２９０の航空会社が加盟する国際航空運送協会、国土交通省に、急角度になる着陸方法の変更を求めています。なぜこの危険なルートを求めたのか、伺います。","respondent":"鈴木都市計画課長","answer":"この計画が公表されてから、騒音環境軽減に向けた取り組みを、もう常に区は求めてきました。その中で示された取り組みということで、実際、着陸位置が延ばされて、高度が上がったという結果にもつながっているものです。","id":"exchange-109"},{"speaker":"あべ委員","kind":"確認","question":"３２４ページ、３４１ページの居住支援協議会、そして３４７ページの避難所生活環境改善経費について伺っていきたいと思います。もう少し合理的に遊び場を使い分けることができるようにならないか、ぜひ検討をお願いしたいと思っているのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長、溝口公園課長","answer":"国は昨日から３月２９日の本格運用に向けて、区内全域全戸にポスティングでの周知を開始しています。あるいは延期に向けた検討を行っているですとか、区の受けとめとしては、計画どおり行われるものという認識です。 ただやはり、子どもの居場所は公園だけで全て賄えるものではありません。そこはやはり関連部署としっかり連携をとって、そういったところも注視しながら検討していきたいというふうに考えているところです。","id":"exchange-110"},{"speaker":"あべ委員","kind":"質問","question":"ここに対して、どこまで行政が、ある程度、対応分担、リスク分担できるかということだと思います。リスク分担について、行政の介入を考えていらっしゃるのか、説明を求めました。","respondent":"森住宅課長","answer":"拒否感はあるものの従前より弱くなっているというような回答をされており、交渉なりを行う余地はあるのかなというふうに考えているところです。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問・要望","question":"もう東日本大震災から９年が経ちました。これは全力で取り組んでいただきたいと思うのですが、お考えをお願いします。","respondent":"中島防災課長","answer":"そういう部屋をしっかり確保しましょうというところをマニュアルの中にもうたっており、各避難所のマニュアルにも反映に努めているところです。避難所運営マニュアルの中にもしっかり、チラシ的なものも含めまして反映して、避難所連絡会議の中で周知を図っているところです。","id":"exchange-112"},{"speaker":"あべ委員","kind":"質問","question":"一歩、やはりこの具体的に犯罪を防いでいく環境づくりということで、ご答弁をお願いできればと思います。","respondent":"中島防災課長","answer":"パーテーションというところは、なかなか、発災後すぐに対応することはちょっと難しいところです。環境を整えるというところで、相談体制なども含めまして、しっかりと避難所連絡会議等で協議を重ねていきたいと考えています。","id":"exchange-113"},{"speaker":"湯澤委員","kind":"質問","question":"私からは３０５ページ、駅周辺等放置自転車対策事業、それから３３７ページ、住宅改善工事助成について質問します。今回、あわせて新たに禁止区域となった範囲を含めた基準と、この取り組みに合わせて新たに設置される自転車置き場の数と使用台数を説明するよう求めました。","respondent":"古郡交通安全担当課長","answer":"当日３２４台、計７５１台の駐輪場が新設されたということを含めまして、放置禁止区域を広げたものです。","id":"exchange-114"},{"speaker":"湯澤委員","kind":"質問・要望","question":"駅周辺にはパークシティ武蔵小山に７５１台とか、そういった駐輪場が設置をされて、中原街道側のほうの駐輪場の確保はされているのでしょうか。大型店舗が所有している駐輪場や、このような想定につきまして、区の見解はいかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"やはり適地がないということで非常に難しいということで、パルム商店街とか町会等とも連携しながら、現在そういったものの周知をしています。午前１０時前、全体で３６０台とめてあったのですけれど、パルム商店街を通じて周知徹底を図ってまいりたいと考えております。","id":"exchange-115"},{"speaker":"湯澤委員","kind":"質問・要望","question":"そのために、駐輪場がどこにあるのか、特にモラル向上に力を入れ、そのためにチラシやポスターを作成していきたいなどというお話も伺いました。そういった、商店街の取り組みに対する支援などがあれば、教えてほしいと求めました。","respondent":"古郡交通安全担当課長","answer":"周知に関しては、現在、電柱幕を張っておりますので、そういったところで周知をしています。パルム商店街とよく連携を図っておりますので、その辺を含めて、連携を図ってまいりたいと考えております。","id":"exchange-116"},{"speaker":"湯澤委員","kind":"質問","question":"賃貸住宅個人オーナーの３つとなりますが、どこに対する助成が多いのか、昨年度の実績とともに教えてほしいと求めました。その場合、区民向け助成の中でどのくらいの割合なのかを教えてほしいと求めました。","respondent":"森住宅課長","answer":"そのうち２４３件、共同住宅については２７件というふうになってございまして、戸建ての建物あるいは分譲マンションの１室という形になってあります。","id":"exchange-117"},{"speaker":"湯澤委員","kind":"質問・要望","question":"質問なのですけれども、このオーナーが助成を受けた物件で、賃貸住宅に住んでいる区民が申請をした場合にも、この助成を受けられるのでしょうか。原状回復をしていないなど、オーナーとの間で問題になったケースなどがあれば、教えてほしいと求めました。","respondent":"森住宅課長","answer":"基本的には、賃貸住宅について先ほど言いましたように、賃借人からの申請も、オーナーの許可があれば、基本的にはオーケーしています。その後の原状回復について、何かしらトラブルになったという件については、住宅課では聞いておりません。","id":"exchange-118"},{"speaker":"湯澤委員","kind":"質問・要望","question":"本当にこの事業、これからの時代にも大変合った助成事業でありますので、より多くの方に周知していただき、多くの区民に利用されるようになりますことを要望いたしまして、質問は終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"大倉委員","kind":"質問・要望","question":"駐輪場と備蓄品について、まず伺いたいと思います。１点、その紙おむつ等の活用の検討状況はどうなっているのか教えていただきたいのと、そうした考え方についてもあわせて示すよう求めました。","respondent":"古郡交通安全担当課長、中島防災課長","answer":"放置自転車の減少につきましては、駐輪場の整備、指導・警告、そして撤去、これらを総合的に実施し、だんだんと減っていっているような状況です。これは撤去をして、おおむね６か月後に取りに来ない… メーカー推奨期限を超えているというところもしっかりと周知をした上で、各所管課としっかり連携をし、有効活用を図ってまいりたいと思います。","id":"exchange-120"},{"speaker":"大倉委員","kind":"質問・要望","question":"品川区の放置自転車が減って、そういった活用ができるようになったらやっていただきたいなと思って質問しましたので、ぜひよろしくお願いします。そういった検討はまだこれからなのか、そういったことよりもまずは庁内で検討していくということだったのか、その辺も説明を求めました。","respondent":"中島防災課長","answer":"先ほども申し上げました庁内連携の中には、個々のニーズなど、対応の方法があると思います。その中にイベントも、もしかしたら含まれるかもしれませんが、そのあたりも含めましてしっかり連携を図ってまいりたいと考えています。","id":"exchange-121"},{"speaker":"こんの委員","kind":"質問","question":"３４５ページ、以上３点、お伺いしたいと思います。空き家有効活用賃借料は、区が借り上げる費用とも聞いておりますが、具体的な事業のご説明をお願いします。","respondent":"森住宅課長","answer":"子育て支援であったり、区にぜひ使っていただきたいというようなお申し出を受けまして、先日も内覧をさせていただいたところです。今、所有者の方と協議を進めていきたいというふうに考えておりますけれども、１００万円を２件という形で計上させていただいているところです。","id":"exchange-122"},{"speaker":"こんの委員","kind":"提案","question":"我が会派が昨年の第３回定例会などで提案してきた空き家の利活用、そうしたものと理解をし、事業展開については評価するところであります。子育て世帯、ひとり親家庭、障害者などの住まいとしても活用していくことが求められると思いますとの意見を述べました。","respondent":"森住宅課長","answer":"高齢者のひとり暮らしあるいは２人世帯ということになりますと、逆に、少し狭い部分もあったりするかなというふうに思っております。そうしますと、どういった方々に使っていただくのが一番いいのかということは、今後検討していきたいということを考えております。","id":"exchange-123"},{"speaker":"こんの委員","kind":"意見","question":"住まいに困っている方の支援をどうするかという住宅施策を考えたときに、これを住まいに活用していく、こうしたことも考えられるのではないか。こうした考えについてのご見解を説明するよう求めました。","respondent":"森住宅課長","answer":"そういったものを、何とか居住支援協議会の活動の中で使っていきたいということは考えているところですけれども、今のところ考えておりません。","id":"exchange-124"},{"speaker":"こんの委員","kind":"質問・要望","question":"午前中のほかの委員の質問へのお答えで、昨年発生した台風第１５号、第１９号の教訓を活かして展開される事業とありました。この２つの事業を展開するにあたって、改めて、昨年の台風第１５号、第１９号の教訓や課題をどう捉えてきたのか、お聞きしたいと思います。","respondent":"森住宅課長、中島防災課長","answer":"オーナーがメリットを感じられるような支援が必要だろうということも言われているところです。第１回目は少し総花的な、具体的なターゲットを絞りながら… 昨年の台風第１５号および第１９号に関して、区といたしましてもさまざまな課題、教訓が得られたと考えております。それらも踏まえまして、来年度の事業につなげてまいりたいと考えています。","id":"exchange-125"},{"speaker":"こんの委員","kind":"質問・要望","question":"いわゆる避難所、避難場所、この運営マニュアルについてはどのようにされていますでしょうか。昨年の台風第１５号、第１９号の教訓を活かした、ご見解を説明するよう求めました。","respondent":"中島防災課長","answer":"その際に、区の職員が運営する中で地域の方々とどう連携していくかというところは、風水害に関する話はなかなかできていないところがあります。いざ避難場所を開設するときには、よりよい、円滑な運営ができるように努めてまいりたいと考えています。","id":"exchange-126"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望です。機器について、現状を説明するよう求めました。","respondent":"中島防災課長","answer":"ご紹介いただきましたカメラにつきましては、目黒川で２か所、立会川で７か所に設置しており、一番最初に導入したのが平成２０年度になります。比較的高精度なカメラを導入していますので、しっかり老朽化したものの更新に努めてまいりたいと思います。","id":"exchange-127"},{"speaker":"こんの委員","kind":"質問・要望","question":"平成３０年度に更新をした機器もあったということで、画像を見る限りではあまり問題はないという認識だったのでしょうか。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問","question":"３１９ページの区民の自主的なまちづくりの支援、これはどういう成果があったのでしょうか。それは改善されたのか尋ねました。","respondent":"鈴木都市計画課長、中島防災課長","answer":"次に、コミュニティバスですが、昨年１２月に、第２回目の検討会を開催しまして、骨子案を２つご提示しています。実施、導入計画の前に、しっかりその評価基準も定めながら進めていくです。 学校避難所の非常発電設備の保守点検についてですが、こちらにつきましては区民避難所の７２時間稼動する発電機の保守点検です。年２回、試運転等を行い、平素からしっかりと稼働していることを点検によって確認しています。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問・要望","question":"それから、非常発電設備なのですが、これ負荷試験ですから。法定負荷試験なので、もう一度確認をしていただいて、しっかりと進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３２１ページの密集住宅市街地整備促進事業、それから３３９ページの空き家等対策事業、３４３ページの消防団運営費について伺いたいと思います。道路は４ｍに拡幅されたにもかかわらず、意味がなさない状況になっている、この問題について伺いたいと思います。","respondent":"長尾建築課長、大森災害対策担当課長","answer":"申請者の方であるとか、隣接されている方にお話を伺いながら、電柱の移設についてもあわせて取り組んでいるところです。申請者から直接、区としましては… そのうち、例えば会議室ですとかトイレですとか含めての機能が満たされていない施設につきましては、区で把握している限りでは３か所あります。","id":"exchange-131"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひこの仕組みをつくっていただきたいということで、これはちょっとご検討いただいて、強く要望をしておきたいと思います。私はこれを、区と東京都が一緒になって、民間の土地購入も含めて早急に整備するべきだと思うのですけれど、いかがか尋ねました。","respondent":"大森災害対策担当課長","answer":"必要な規模ですとか機能、これを確保していないということは、区といたしましても十分認識しております。引き続き、さまざまな方策を活用するとともに、消防団、消防署と連携をいたしまして、必要な用地の確保等に努めてまいりたいと考えております。","id":"exchange-132"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これだけ大事な、本当に重要な役割を果たしているということは、もう本当に皆さんの共通の認識だと思うのです。どう考えても早急に設置が必要だと思いますので、ぜひ、都と一緒に取り組んでくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-133"},{"speaker":"渡部委員","kind":"質問","question":"３２７ページで、１０年ぶりといいましょうか９年ぶりでしょうか、いよいよ北側ゾーン改修設計等委託ということで文字になってあらわれてきました。でなければ、どういう形でこれから地域の方々、いわゆる設計というのに入っていくのかというところをちょっと説明を求めました。","respondent":"溝口公園課長","answer":"やはり、老朽化して改修時期に来ているところもありますので、改修をしていきたいということで、予算計上させていただいてあります。今回、計画していく中でご意見を聞きながら、どういうふうに今後整備していくのかを決めていきたいというふうに考えているところです。","id":"exchange-134"},{"speaker":"渡部委員","kind":"質問・要望","question":"天然芝がなくなってきているとかというような話をしていたのがもう７、８年前で、また戻ってきたかという話だとは思うのです。ですから、ぜひ話をしていただきたいと思うのだけれど、その辺のスケジュールはどのようにお考えか尋ねました。","respondent":"溝口公園課長","answer":"スケジュール的なものでいきますと、令和２年度、来年度１年かけて設計を進めていきたいというふうに考えております。以前の検討からやはり年数が経っているところもありますので、もう１回しっかり、進めていかなければいけないというふうに感じているところです。","id":"exchange-135"},{"speaker":"渡部委員","kind":"質問・要望","question":"たしかその照明の問題も近隣のマンションの方々だったでしょうか。多分、区役所の前は２車線になるのか尋ねました。","respondent":"多並道路課長","answer":"区役所前につきましては、今の道路よりも右折レーンが１つ増えまして、実質２車線プラス１で３車線のような形状となる予定となっております。経理課と連携しながら、その辺でより円滑に交通処理上もできないかということで今、細部については警察と最後の協議をしています。","id":"exchange-136"},{"speaker":"渡部委員","kind":"質問","question":"ですから、どういう仕掛けをつくったって、誘導しないといけなくなるような形状になるのではないですか。そこに車２台分なのか、バス１台分ぐらいの長さなのか、どうか尋ねました。","respondent":"多並道路課長","answer":"今、経理課と最後、その辺については協議、調整させていただいて、工事自体は来年度いっぱいでやっていくことになりますので、また具体的な対応については、再来年度の予算の中で計上する形になってくるのではないかなと考えているところです。","id":"exchange-137"},{"speaker":"本多委員","kind":"質問","question":"３０７ページ、水辺千本桜計画、３４０ページから始まります防災費について、防災協定について伺います。２０１８年から２０２０年度の３か年をかけて、目標２０２０年度までに１,０００本、２０２０年度の取り組み予定を説明するよう求めました。","respondent":"多並道路課長","answer":"もともとその事業開始前に水辺にあった桜が約８４２本で、平成３０年度に３７本植えさせていただいて、今年度については１１８本植えております。目黒川周辺で１０本植えする予算を計上させていただいて、今予定ですと、それで１００７本植えるという形で考えているところです。","id":"exchange-138"},{"speaker":"本多委員","kind":"質問・要望","question":"区内全域に桜を増やしてほしいという思いから聞いていきますが、目黒川を中目黒と同様、またそれ以上の桜の名所にしてほしいと求めました。そうした事例をものすごく大切にしていって、さらに桜を増やす取り組みをしてほしいと求めましたが、その点について説明を求めました。","respondent":"多並道路課長","answer":"このほかにもう１つ紹介させていただいていますのが、特に西光寺の兒桜ということで、こちらの歴史館の中にも展示してあるような内容の桜である。","id":"exchange-139"},{"speaker":"本多委員","kind":"質問","question":"２０２０年度で計画が終わりますが、それ以降、２０２１年度以降の取り組みとして、今現在の何か考え方とかがあれば説明を求めました。","respondent":"多並道路課長","answer":"２０２０年度までに進める、一つは東京２０２０大会をターゲットとしているところがありますので、それが一つの整備計画の考え方です。","id":"exchange-140"},{"speaker":"本多委員","kind":"質問・要望","question":"第１号を結んでから、ちょっとその辺の正確な数字を教えていただきたいのと、灯油について協定を結んでいる事業者が廃業してしまったと伺いました。灯油の防災協定の部分は、うまく補えたかどうか、説明を求めました。","respondent":"中島防災課長","answer":"基本的には区内のガソリンスタンドに備蓄をしていただくことで進めております。ガソリンスタンドがありますので、そちらと協定の中で、しっかりと備蓄および供給をしていただこうかと考えています。","id":"exchange-141"},{"speaker":"本多委員","kind":"質問・要望","question":"質問したいのは、新規設置について、令和２年度の予算は東急ばかりなので、ＪＲとか京急、りんかい線とか、その辺はどうなのかなと。未整備の１６駅について、東急以外の鉄道事業者の積極性をもうちょっと求めたいと思うのですが、その点について説明を求めました。","respondent":"鈴木都市計画課長","answer":"区内に６駅ありますが、まだホームドアが設置されていないというところで、ホームドア設置についてより強い働きかけを行ってあります。特に京急には、その計画に位置づけていただいて、より早い時期に整備していただけるように、今、区のほうでも協議を行っているところです。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"さらに災害時での活用、こういった点を含めて、どのような形で、基本設計、実施設計されていくのか伺います。施設を、団の方々が求めて、課長にもお願いしております。","respondent":"松本河川下水道課長、鈴木都市計画課長、溝口公園課長、大森災害対策担当課長","answer":"溢水防止板の設置ですが、先ほどご答弁したように、今回は、国道１５号から河口までの残っている部分について設置するものです。あわせまして… ３０年後の建て替え、というところもあって、昨年度アンケートを実施しています。地域の方と勉強会を予定していたのですが、今年度は見送った… 実際、来年度から基本設計、実施設計を進めていこうと考えております大井坂下公園ですが。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問","question":"一番初めに伺った立会川の財源のところなのですが、私のほうもちょっと調べが足りなかったのかもしれません。それはまた後でお尋ねします。","respondent":"品川財政課長","answer":"いろいろ所管の関係で事務処理特例交付金、財政課のほうで取りまとめをするとか、そういった部分のところで総務費で出していると、こういうことです。","id":"exchange-144"},{"speaker":"藤原委員","kind":"確認","question":"３３９ページ、区民住宅なのですけれども、借上型が計上されておりませんが、これは、特優賃が終わったということでいいのか、確認します。３１７ページで河川下水について伺いたいのですけれども、いつ完成するのでしょうか、説明を求めました。","respondent":"森住宅課長、松本河川下水道課長、多並道路課長","answer":"借上型の区民住宅につきましては、平成４年から事業を開始しておりまして、平成１４年には１６団地２９８戸の供給をさせていただいたところです。ですので… 西大井五丁目付近で実施している下水道工事ですが、新しい下水道管の整備をするために、東京都の下水道局が実施しているものです。… 補助１６３号線の交差点の関係ですけれども、こちらも今の道路が広がる関係で、交差点自体に変更が生じます。","id":"exchange-145"},{"speaker":"藤原委員","kind":"質問","question":"横断歩道つながりで伺わせていただきますが、私は前回も言いました。その辺について、交通安全という意味においても、ぜひ伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"警察とも連携を図って、取り締まりを強化しています。警察にもお願いして、免許の更新時だとかに安全教育をするだとか、そういったところで周知徹底を図ってまいりたいと考えております。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問","question":"３２１ページの、不燃化１０年プロジェクトについてお伺いしますけれども、都と連携し積極的に進めてき」ましたと。これを受けて、担当課の課長としては、まずどういうふうにやっていこうと思っているか、説明を求めました。","respondent":"高梨木密整備推進課長","answer":"本年１月に、東京都が新たな防災まちづくりの上位計画である、防災都市づくり推進計画の基本方針の案を出しました。施政方針で区長に述べていただいたとおり、積極的に東京都に対して要望活動を行っていきたい、このように考えているところです。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"その地域ごとの密集という意味において、やはりこの辺もやっていただきたいと思うし、本気度をちょっと示していただきたい。課長、いかがか尋ねました。","respondent":"高梨木密整備推進課長","answer":"ＮＨＫが１週間以上特集を組んで、特に密集度の高い豊町、二葉地区の防災広場を中心にご紹介させていただきました。１時間以上取材を受けたのですが、２３区一安全な区になったねと言われるまで、安全・安心のまちづくりをしっかり進めていくつもりです。","id":"exchange-148"},{"speaker":"藤原委員","kind":"質問・要望","question":"東京全域は警視庁ですから、やはりこの２年間の仕事、活かしていっていただきたいと思うのです。その辺の思いを残り時間全部で、どうぞ。","respondent":"古郡交通安全担当課長","answer":"まだ内示等も出ていないので、どこに行くかはわかりません。ただ、品川区で経験したものを活かして、警察官として、都民の安全と安心を守るべく、全力を尽くしてまいりたいと考えております。","id":"exchange-149"},{"speaker":"安藤委員","kind":"確認","question":"実機飛行確認による電波障害、３３９ページ、建替修繕支援について伺います。換気する必要のない屋外というのは安全との指摘がある中で、公園というのは子どもたちのためにも開放するべきと思いますけれども、いかがか尋ねました。","respondent":"溝口公園課長","answer":"今回の新型コロナウイルス感染症対策の関係で、公園を閉鎖したところは１園もありません。そういったところにつきましては、そういったところでの制限をかけているところではありますが、決して公園自体の閉鎖は一切しておりません。","id":"exchange-150"},{"speaker":"安藤委員","kind":"質問・要望","question":"次に、羽田新ルートの実機飛行確認なのですけれど、区内の複数の方から、飛行機が通過するたびにテレビの映像が乱れたとの声を伺いました。ですので今後、区民の通報で、国に現地調査を行うよう求めてほしいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"国には、飛行しているときに、実際に映りがどうか、そうした声を受けて、見ていただくようなことも場合によっては必要かというふうに考えてあります。","id":"exchange-151"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれど、品川区はこの現状をどう認識しておられるのでしょうか。あったとしたら、どのような動きがあったのかも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"しかも、直接は確認してございませんが、交通管理者としての警視庁あるいは警察からのオーケーが出ないのかなという認識は持ってあります。いずれにせよ、しっかり確認はしていきたいというふうに考えてあります。","id":"exchange-152"},{"speaker":"安藤委員","kind":"質問・要望","question":"まだ確認されていないということですので、あらゆる方策も含めて、ぜひ検討していただきたいというふうに思います。さらにそのうち、分譲マンション、つまり持ち家の共同住宅というのは何世帯なのか、伺いたいと思います。","respondent":"森住宅課長","answer":"そのうち、共同住宅につきましては１７万７,５４０戸、約８２.４％です。うち、持ち家の共同住宅、これが分譲マンションというふうにとれるのですけれども、それが５万６,７００戸、２６.３％となっています。","id":"exchange-153"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれど、マンションのこの２つの老いによる管理不全のおそれ、現時点では、品川区は区内の実態をどのように把握されているでしょうか。この問題というのは、これから品川区でも大きな課題になってくるかと思いますけれども、いかがか尋ねました。","respondent":"森住宅課長","answer":"例えば総会が１年に一度開かれていないとか、マンション管理士などと連携して、管理の支援をしていくです。そういった届け出制度を活用いたしまして、きちんとしたマンション管理支援を住宅課としてもしていきたいというふうに考えております。","id":"exchange-154"},{"speaker":"安藤委員","kind":"質問・要望","question":"現時点で、これから品川区でも大きな課題になってくるのではないかと思いますがいかがでしょうかと伺いましたので、この問題を報じておりました。先ほどの問いとあわせて伺いたいと思います。","respondent":"森住宅課長","answer":"マンション管理セミナーであったりそういったところ、時期を見て、それぞれ管理支援を行っているところです。そういった管理不全の課題というのは認識しておりますので、それぞれのマンションに働きかけをしていきたいというふうに考えております。","id":"exchange-155"},{"speaker":"安藤委員","kind":"質問","question":"この指摘をどう受けとめているのか、区は目をつぶっているのでしょうかと伺いましたので答えるよう求めました。","respondent":"稲田都市開発課長","answer":"それをしっかりと管理組合に引き継いでいくというところもございまして、しっかりと、その長期的な見通しも立てながらやっているというふうに感じております。","id":"exchange-156"},{"speaker":"安藤委員","kind":"質問","question":"かなり楽観的過ぎるといいますか、私には目をつぶっているようにしか思えないのです。超高層マンションの建設ラッシュを税金投入して再開発で進めていくというのは、私はあまりに無責任な行政だと思うのですけれども、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"しっかりとやっているというふうに、私どもは感じております。","id":"exchange-157"},{"speaker":"安藤委員","kind":"質問・要望","question":"今あるタワーマンションなどへの建替・修繕の支援はもちろん必要なのですが、解決しがたい課題を抱えている超高層マンションを無計画に広げる再開発は見直すべきだと求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"たけうち委員","kind":"質問","question":"私は、３２１ページの不燃化１０年プロジェクトの用地取得費、そして３４１ページの感震ブレーカーについて伺います。いろいろお聞きするところによると、品川区に売却するかどうかも、国との交渉のスケジュール等についてまず説明を求めました。","respondent":"柏原企画調整課長、高梨木密整備推進課長","answer":"地元の方に説明会をして、一部ご心配の声も出ておりますので、これについては丁寧な説明を繰り返していきたいというふうには思ってあります。こちらについては交渉しながら、早いところ… 取得が叶った後のその後のスケジュールですが、前回はまだ取得が確実になっていない状態で計画の説明会を行いました。そういったものを、周辺の皆様にしっかりと伝えていきたい、このように考えております。","id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"１.７倍ぐらいの予算になっていて、当然交渉事なのでどうなるかというところなのですけれど、区の持ち出しが少ない額での購入が望ましいのです。不燃化１０年プロジェクトの対象地域になっているので、もし購入できた場合の補助のあり方、あるいは補助の考え方も説明を求めました。","respondent":"高梨木密整備推進課長","answer":"地域の方々と取り組んでいるところですが、不燃化１０年プロジェクトの中で、公共施設転換用地取得支援というようなメニューがあります。このようなメニューを用いて東京都の補助２分の１をいただく方向で、来年度予算につきましては歳入のほうで、その旨計上しています。","id":"exchange-160"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そういった公の部分で使うものですから、ぜひ、強い交渉をお願いしたいと思います。これは要望させてほしいと求めました。","respondent":"中島防災課長","answer":"簡易タイプといたしまして一般世帯に１００件、高齢者・障害者等世帯に１２０件。新築については３件を予定しています。","id":"exchange-161","title":"町会・自治会支援"},{"speaker":"たけうち委員","kind":"質問","question":"トータルで１００件ということで、それが比較的安い金額にもかかわらず、合計３件ということでなかなか伸び悩んでいるのです。この辺の分析についてどのようにされているのかというのと、周知等についても、どのようにされているか、説明を求めました。","respondent":"中島防災課長","answer":"ただ、実質的にそういう世帯の負担が１万円から１万５,０００円というところで、集中してしまったというところが要因かと思います。周知に関しましては分電盤、簡易タイプ、それぞれ等しく行っておりますので、来年度につきましてもしっかりとＰＲしてまいりたいと思います。","id":"exchange-162"},{"speaker":"たけうち委員","kind":"質問・要望","question":"１００件見込まれているということで、またこれまでも求めてまいりましたけれども、その辺の見通しがあれば説明を求めました。","respondent":"中島防災課長","answer":"今、国のほうで２５％程度の木造住宅に対して普及をという指針もあります。大体そうすると２,７００棟という数字になるのですけれど、現状まだ３００棟程度の普及率ですので、今後普及に努めてまいりたいと思います。","id":"exchange-163"},{"speaker":"大沢委員","kind":"質問","question":"３０５ページの交通安全と、３２５ページの武蔵小山駅周辺地区再開発事業について伺います。最初に交通安全なのですけれども、アシスト自転車について伺いますが、大体最高速度は、どれくらい出るものなのか、教えていただけますか。","respondent":"古郡交通安全担当課長","answer":"最高時速に関しては、ちょっと私のほうは調べてございませんので、把握をしてございません。","id":"exchange-164"},{"speaker":"大沢委員","kind":"質問","question":"時速２４ｋｍから２６ｋｍ出るということなのですけれども、これはリミッターを切った場合はもっと出るということなのです。歩道と車道に敷設してある自転車専用道路において、速度の違いというのはあるのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"歩道に関しては、歩行者もおりますので、徐行という形になってあります。一方、自転車道に関しては徐行ではございませんので、その明確な速度の違いがあるです。","id":"exchange-165"},{"speaker":"大沢委員","kind":"質問","question":"それ以上、歩道を時速２０ｋｍぐらいで走行するということになると非常に危険なわけであります。そこのところをどのように利用者の方にお話をされて、指導されているのか、説明を求めました。","respondent":"古郡交通安全担当課長","answer":"自転車安全教室等で、歩道を走る場合については、車道寄りを走って徐行してくださいということでお話をしております。そういったこともお話しして、なるたけ自転車専用道、自転車レーンがある場合については自転車レーンを走るように指導しています。","id":"exchange-166"},{"speaker":"大沢委員","kind":"質問","question":"リミッターを切って走っているということをご存じか尋ねました。","respondent":"古郡交通安全担当課長","answer":"電動自転車のリミッターを切るというのは、私のほうでは承知をしてございません。","id":"exchange-167"},{"speaker":"大沢委員","kind":"質問","question":"それは法律にあるかどうかはわかりませんけれども、規則からちょっと外れているような感じはするのです。決まりはあるのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"取り締まりが、基本だとかそういった形になるとは思うのですけれども、なかなか難しいところだと認識をしています。","id":"exchange-168"},{"speaker":"大沢委員","kind":"質問・要望","question":"安全教育なり安全啓発なりをしっかりしていただきたいなと思いますし、そこのところ、事故がないようにお願いしたいと思います。武蔵小山駅周辺ということなのですが、これ、平塚口のほうは武蔵小山駅周辺と考えていいのか尋ねました。","respondent":"稲田都市開発課長","answer":"私ども、武蔵小山まちづくりビジョンという中で、にぎわい軸ゾーンというのをパルム商店街を中心に中原街道口のほうまでエリアとして設定しておりまして、中原街道の部分におきましても、駅周辺というふうな考え方でおります。","id":"exchange-169"},{"speaker":"大沢委員","kind":"意見","question":"２核１モールということで、それとまた行政の協力によって、すばらしいまちづくりが進んでいるわけです。課長はどういうふうに感じられますかとの意見を述べました。","respondent":"稲田都市開発課長","answer":"両方とも、どちらが正面でどちらが裏口だとか、そういう感覚は区のほうは持っておりません。商店街全体をにぎやかしていこうというふうな考えがあります。","id":"exchange-170"},{"speaker":"大沢委員","kind":"質問・要望","question":"武蔵小山から平塚口、そしてまた戸越銀座のほうから、戸越銀座からも流れてくるような平塚口のまちづくりを考えていただきたいと思うのです。そのビジョンなり、課長の個人的なお考えでもいいので、今私のお話ししたことについての感想を述べていただきたい。","respondent":"稲田都市開発課長","answer":"委員おっしゃる平塚口につきましては、地元の、いわゆる商店街でいえば３部、４部という地区の方とお話もさせてもらったりします。武蔵小山がとってしまうとかいう話ではなくて、両方とも、両方の商店街もそうやっていくとにぎわうのではないかなというふうに考えております。","id":"exchange-171"},{"speaker":"大沢委員","kind":"質問・要望","question":"商店街の方たちも、武蔵小山というものをずっとアピールするのはこれから３部、４部の時代ではないかなということで話をしております。そのためにもやはり、平塚口というのは非常に大事なキーポイントなので、そこのところ、今後、十分にお考えほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-172"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"特区でやるのですかという考え方。虎ノ門でやろうとか、今いろいろあるけれども、その辺の感覚を教えていただきたい。","respondent":"今井土木管理課長","answer":"１、２年かけて、東京都のほうで検討を進めてまいりました。今、この社会実験がそれぞれの都道府県レベルで、またそのような取り組みが進められていく可能性もあるというふうに認識しております。","id":"exchange-173"},{"speaker":"石田（秀）委員","kind":"意見","question":"これをどういうふうに捉えていくかとやっていかないと、今みたいに東京都がそういうふうにやってくれないと、これは進まないということになってくる。その辺の観光資源とかそういうことも含めて考えるなら、どう取り組んでいこうとされているのかというところをお聞かせ願いますとの意見を述べました。","respondent":"今井土木管理課長","answer":"それぞれの道路管理者そして交通管理者の考えもありますので、こちらのほうは、検討の範囲の幅が広いのではないかというふうに思っております。何か地域全体が大きな取り組みという団体の組織化、東京都、国へ対応していく手段になろうかと思います。","id":"exchange-174"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今大崎エリアマネージメントもいろいろなところでやろうということも考えているわけですから、ぜひよろしくお願いしたいと思います。それから、３４０ページの防災費全体のことをちょっとお伺いします。","respondent":"中島防災課長","answer":"机上の検討については、進めているところですが、そういう具体的なところまではまだ至っていないところも確かにあります。そういうところも十分肝に銘じまして、具体的な検討を進めてまいりたいと思います。","id":"exchange-175"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１点は、どうしてもとまる部分があるけれど、そこまでやってもいいと私は思うのです。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-176"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/273075?Template=document&Id=1118#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":128574,"voices":398}}]);
